window.VERI={"meta": {"title": "Politics Revision", "subtitle": "Comparative Politics · IR · Key Concepts · Heywood", "updated": "2026-06-13", "note": "Built from your own notes (Comparative Politics Revision; Mearsheimer; Concepts of Political Science; IR Theory paradigms) plus Heywood, Politics — Key Concept boxes (5th ed.) and chapter summaries (4th ed.). Concept-focused; scholars appear only as secondary cues."}, "topics": [{"id": "methods", "name": "Research Methods"}, {"id": "institutions", "name": "Institutionalism & State-making"}, {"id": "authoritarianism", "name": "Authoritarianism"}, {"id": "turkey", "name": "Turkish Politics"}, {"id": "polecon", "name": "Political Economy"}, {"id": "ir", "name": "International Relations"}, {"id": "concepts", "name": "General Concepts"}, {"id": "keyconcepts", "name": "Heywood — Key Concepts"}, {"id": "polsum", "name": "Politics — Chapter Summaries (Heywood)"}, {"id": "summaries", "name": "Political Theory — Summaries (Heywood/Chin)"}], "cards": [{"id": "m1", "topic": "methods", "front": "Small-N studies: strengths and weaknesses", "back": "Strengths (+): contextuality and causality are better explicated; suitable for theory-confirmation and theory-building; concepts are well-defined, so internal validity is strong; cases are carefully selected (method of agreement/difference).\n\nWeaknesses (−): too many variables, too few cases; case selection bias.", "mcq": {"stem": "Which is a characteristic STRENGTH of small-N research?", "options": ["Strong internal validity because concepts are well-defined", "Random case selection removes bias", "High external validity for generalizing to other cases", "Outlier cases do not hurt the overall argument"], "answer": 0, "why": "Well-defined concepts → strong internal validity is the small-N strength. The other three are large-N strengths."}}, {"id": "m2", "topic": "methods", "front": "Large-N studies: strengths and weaknesses", "back": "Strengths (+): cases are randomly selected, so there is no bias; suitable for generalizing → external validity; outlier cases do not hurt the overall argument.\n\nWeaknesses (−): too much data, costly and time-consuming; correlation does not equal causation, causality is not well explained through process-tracing; conceptual stretching is common (too many indicators, overlooking conceptual integrity).", "mcq": {"stem": "A common WEAKNESS of large-N designs is that…", "options": ["conceptual stretching is common (indicators overtake conceptual integrity)", "there are too many variables and too few cases", "case selection bias is unavoidable", "they cannot build or confirm theory"], "answer": 0, "why": "Conceptual stretching / too many indicators is the large-N weakness. 'Too many variables, too few cases' and 'case selection bias' are small-N weaknesses."}}, {"id": "m3", "topic": "methods", "front": "Small-N: methods of causal analysis", "back": "1) Cross-case analysis — method of agreement/difference; necessary and sufficient causes, Boolean algebra; typological causation is common (two or more matrices stand as different IVs).\n2) Within-case analysis — process-tracing.", "mcq": {"stem": "Process-tracing is an example of which kind of small-N causal analysis?", "options": ["Within-case analysis", "Cross-case analysis", "Temporal analysis", "Multivariate regression"], "answer": 0, "why": "Process-tracing is the within-case method; method of agreement/difference and Boolean algebra are cross-case."}}, {"id": "m4", "topic": "methods", "front": "Methods of temporal analysis (small-N)", "back": "Path-dependence; critical juncture; duration and conjunctural.", "mcq": {"stem": "Which trio are the 'methods of temporal analysis' in small-N work?", "options": ["Path-dependence; critical juncture; duration & conjunctural", "Agreement; difference; Boolean algebra", "Multicausality; context-conditionality; endogeneity", "Capabilities; state weight; subnational variation"], "answer": 0, "why": "Temporal analysis = path-dependence, critical juncture, duration & conjunctural. The others are causal-analysis tools, the reasons context matters, and Soifer's dimensions of infrastructural power."}}, {"id": "m5", "topic": "methods", "front": "Why does context matter in small-N / qualitative studies?", "back": "1) Multicausality — different causes can produce the same consequence, so accounting for context matters.\n2) Context-conditionality — a theory sometimes applies only in certain cases, so theorizing contextually is necessary.\n3) Endogeneity — reverse causality, simultaneity, multi-directional causality, intervening variables.", "mcq": {"stem": "In small-N analysis, 'reverse causality, simultaneity and intervening variables' are problems of…", "options": ["endogeneity", "multicausality", "context-conditionality", "conceptual stretching"], "answer": 0, "why": "Endogeneity covers reverse causality, simultaneity, multi-directional causality and intervening variables."}}, {"id": "m6", "topic": "methods", "front": "Mahoney & Goertz (2006): qualitative vs quantitative — logic of inference", "back": "Qualitative = 'causes-of-effects'; quantitative = 'effects-of-causes'.\nQual causation: necessary and sufficient causes, Boolean algebra. Quant causation: multivariate equations, average effect of the model or of individual IVs.\nQual: combination of variables matters, not their individuals. Quant: average effects of individual variables can be calculated.", "mcq": {"stem": "Per Mahoney & Goertz, qualitative research asks ____ while quantitative asks ____.", "options": ["'causes-of-effects' / 'effects-of-causes'", "'effects-of-causes' / 'causes-of-effects'", "'external validity' / 'internal validity'", "'path-dependence' / 'critical juncture'"], "answer": 0, "why": "Qualitative = causes-of-effects; quantitative = effects-of-causes."}}, {"id": "m7", "topic": "methods", "front": "Mahoney & Goertz: equifinality, generalization, case selection", "back": "Equifinality: qual carefully handles it (e.g. process-tracing); for quant multivariate models the prospects of equifinality are infinite, so it does not matter.\nGeneralization: qual is narrow and highly context-sensitive; quant has wider scope thanks to many cases.\nCase selection: qual selects carefully (agreement/difference); quant relies on randomization.\nVariables: qual privileges 'important' causes; quant gives all variables equal weight.\nDeviation: qual studies why cases deviate from estimates; quant largely ignores outliers.\nConcepts: qual cares about concept-building/internal validity; quant cares about indicators → open to conceptual stretching."}, {"id": "i1", "topic": "institutions", "front": "Institutionalism — who's who", "back": "North; Thelen (gradual institutional change — layering, shifting, etc.); Skocpol (revolutions); Mahoney (Latin America); Moore (democracy); Putnam (sociological institutionalism)."}, {"id": "i2", "topic": "institutions", "front": "Temporal analyses — who's who", "back": "Collier & Collier (incorporation of the working class in Latin America); Thelen (institutional change); Pierson (critical juncture); Roberts (party alignment and dealignment in Latin American party systems according to critical junctures)."}, {"id": "i3", "topic": "institutions", "front": "State-making — who's who", "back": "Tilly; Slater; Soifer (conceptualization of infrastructural power)."}, {"id": "i4", "topic": "institutions", "front": "Soifer: three dimensions of infrastructural power", "back": "1) Capabilities approach — resources that the state apparatus holds.\n2) State weight — i.e. the weight of the apparatus on societal actors and groups.\n3) Subnational variation — reach of the apparatus on a territorial basis: is it even or uneven?", "mcq": {"stem": "In Soifer's framework, asking whether the state's territorial reach is 'even or uneven' captures…", "options": ["subnational variation", "the capabilities approach", "state weight", "critical juncture"], "answer": 0, "why": "Subnational variation = territorial reach (even/uneven). Capabilities = resources held; state weight = weight on societal groups."}}, {"id": "a1", "topic": "authoritarianism", "front": "Levitsky", "back": "Competitive authoritarianism."}, {"id": "a2", "topic": "authoritarianism", "front": "Bueno de Mesquita — selectorate theory", "back": "If the winning coalition is small (as in autocracies), private goods are distributed to ensure loyalty.\nIf the winning coalition is large (as in democracies), public goods are distributed to ensure the incumbent's survival.", "mcq": {"stem": "Under selectorate theory, a SMALL winning coalition leads rulers to distribute…", "options": ["private goods to secure loyalty", "public goods to secure survival", "no goods, relying on repression only", "public goods to appease the opposition"], "answer": 0, "why": "Small coalition (autocracy) → private goods for loyalty; large coalition (democracy) → public goods for incumbent survival."}}, {"id": "a3", "topic": "authoritarianism", "front": "Geddes", "back": "Typology of authoritarian regimes and a comparison of their survival."}, {"id": "a4", "topic": "authoritarianism", "front": "Schedler", "back": "Electoral authoritarianism."}, {"id": "a5", "topic": "authoritarianism", "front": "Magaloni — PRI of Mexico", "back": "Signaling the possible costs of deference by observing electoral results. Allocating the stake in the regime to different actors, thus making authoritarian breakdown costly.\nIn sum: settling intra-elite tension AND providing information about the level of support the autocrat(s) has.", "mcq": {"stem": "For Magaloni, what do (manipulated) elections do for an authoritarian regime like the PRI?", "options": ["Settle intra-elite tension and signal the regime's level of support", "Replace private goods with purely ideological appeals", "Reduce the cost of authoritarian breakdown", "Eliminate the need for a winning coalition"], "answer": 0, "why": "Magaloni: elections settle intra-elite tension and reveal information about the level of support; they make breakdown MORE (not less) costly."}}, {"id": "a6", "topic": "authoritarianism", "front": "Svolik & Boix (2013)", "back": "Autocrats must face a double threat: from the autocratic pact (intra-elite) and from broader social segments.\nCredible institutions reduce the asymmetry of information between competing factions.\nHOWEVER, if the inequality of power is too big, such a credible-commitment mechanism would not work.", "mcq": {"stem": "For Svolik & Boix, credible authoritarian institutions work by… but fail when…", "options": ["reducing information asymmetry between factions; the inequality of power is too big", "distributing private goods; the coalition is too large", "signaling support via elections; turnout is too low", "centralizing religion; the periphery is too mobile"], "answer": 0, "why": "Credible institutions reduce info asymmetry between factions, but fail if the power inequality is too large for commitment to be credible."}}, {"id": "t1", "topic": "turkey", "front": "Mardin — center–periphery", "back": "Center–periphery linkages are missing and evolve to be inimical to each other. The Anatolian mainland was always neglected; western lands were of more importance; the devşirme system and a lack of Anatolian cadres reinforced this. As Anatolia lost its autonomy it became reactionary, while the center was always suspicious of subversive activity and of peripheral heterogeneity.", "mcq": {"stem": "Mardin's center–periphery thesis holds that the two realms…", "options": ["were weakly linked and grew mutually hostile", "were always fused through religion", "showed constant two-way mobility", "were unified institutionally throughout"], "answer": 0, "why": "Mardin: linkages missing, the two become inimical. The other options are Bakıner's/Lord's revisions."}}, {"id": "t2", "topic": "turkey", "front": "Bakıner (critic of Mardin)", "back": "Periphery and center were never too separate — mobility existed (migration, especially after the republic). Throughout the republican era neither periphery nor center was unified in its institutional/organizational aspect, and such complexities increased progressively. Religiosity was not entirely externalized from the center; on the contrary it was utilized and became a locus of reciprocal relations between the Diyanet and the Turkish state.", "mcq": {"stem": "Bakıner revises Mardin by arguing that…", "options": ["center and periphery were never too separate and religion was a locus of reciprocity with the state", "the periphery was always reactionary and isolated", "the devşirme system fully severed Anatolia from the center", "religion was completely externalized from the center"], "answer": 0, "why": "Bakıner: mobility existed, neither side was unified, and religiosity was utilized — a reciprocal relation between Diyanet and the state."}}, {"id": "t3", "topic": "turkey", "front": "Ceren Lord (on religion & the state)", "back": "The reciprocal religion–state relationship was present from the beginning onwards. If anything, religious affairs in the Ottoman Empire were already under relative centralization and control compared with their European counterparts.", "mcq": {"stem": "Ceren Lord adds to the Bakıner line by stressing that Ottoman religious affairs were…", "options": ["already relatively centralized and controlled vs. European counterparts", "entirely autonomous from the state", "irrelevant to state-building", "a purely peripheral phenomenon"], "answer": 0, "why": "Lord: religion–state reciprocity from the start; Ottoman religious affairs were already relatively centralized compared to Europe."}}, {"id": "t4", "topic": "turkey", "front": "Keyder — class & the Democrat Party (DP)", "back": "Free labor and small landowners dominated agricultural class relations despite the penetration of global markets into the hinterlands of certain ports. A national bourgeoisie was created via the massive displacement and dispossession of non-Muslim communities. The DP's class composition was heterogeneous: urban classes that suffered in wartime plus war profiteers safeguarded by the state elite and the RPP; middle farmers who benefited from international aid and rising world agricultural prices; and state elites who benefited from the economic opening.", "mcq": {"stem": "For Keyder, the Turkish national bourgeoisie was created largely through…", "options": ["displacement and dispossession of non-Muslim communities", "rapid state-led heavy industrialization", "an alliance of the Diyanet and the periphery", "the over-growth of the bureaucracy"], "answer": 0, "why": "Keyder: national bourgeoisie built via displacement/dispossession of non-Muslims. Heavy industrialization is Birtek; bureaucratic over-growth is Sunar."}}, {"id": "t5", "topic": "turkey", "front": "Birtek — surplus, SEEs and the RPP", "back": "The main aim was the accumulation of agricultural surplus through price controls and taxes, funneling it into industrial production → heavy and rapid industrialization. State economic enterprises (SEEs) provided stable employment for formerly rural classes, alleviating social tensions and gaining loyalty for the regime. The RPP tried to pursue two contradictory ideals: providing employment to the new industrial proletariat under its wing while also encouraging private business to grow.", "mcq": {"stem": "Birtek argues the early-republican economic strategy funneled agricultural surplus toward…", "options": ["heavy and rapid industrialization", "the creation of a national bourgeoisie via dispossession", "clientelist ties to peripheral voters", "embedded liberalism"], "answer": 0, "why": "Birtek: surplus accumulation (price controls/taxes) → heavy/rapid industrialization, with SEEs buying loyalty."}}, {"id": "t6", "topic": "turkey", "front": "Sunar — bureaucracy & right-wing populism", "back": "Turkish politics and right-wing populism: the main reason is that the bureaucracy grew much EARLIER than political pluralization and new political organizations. This over-established bureaucracy was, on the one hand, countered by right-wing populist parties; on the other, clientelist ties were founded to connect to peripheral voters vis-à-vis bureaucratic influence.", "mcq": {"stem": "Sunar explains Turkish right-wing populism by the fact that the bureaucracy…", "options": ["grew earlier than political pluralization, prompting populist counters and clientelism", "was captured by the Diyanet from the start", "remained smaller than party organizations", "funneled surplus into heavy industry"], "answer": 0, "why": "Sunar: over-early bureaucratic growth → countered by right-wing populist parties + clientelist ties to peripheral voters."}}, {"id": "pe1", "topic": "polecon", "front": "Ruggie", "back": "Embedded liberalism."}, {"id": "pe2", "topic": "polecon", "front": "Gallagher & Robinson", "back": "The imperialism of free trade."}, {"id": "ir1", "topic": "ir", "front": "Mearsheimer — the four organizing questions", "back": "Mearsheimer organizes his analysis around four questions: (1) What are institutions? (2) How do they work to cause peace? (3) Are they compelling? (4) Are they supported by evidence? He argues the three institutionalist approaches do not adequately answer these, and that institutions do not significantly affect state behaviour.", "mcq": {"stem": "Which is NOT one of Mearsheimer's four questions about institutions?", "options": ["Who funds the institution?", "What are institutions?", "How do they work to cause peace?", "Are they supported by evidence?"], "answer": 0, "why": "His four: what are institutions, how do they cause peace, are they compelling, are they supported by evidence. Funding is not one of them."}}, {"id": "ir2", "topic": "ir", "front": "Mearsheimer — definition of institutions", "back": "A set of norms that regulates interstate relations and competition. It is based on negotiation/conversation and helps standardize the range of acceptable behaviours. States are not legally obligated to follow the rules; institutions do not form a separate level of government — each state decides for itself whether to follow the norms. In short, institutions require cooperative effort from independent sovereign states but prohibit any centralized authority.", "mcq": {"stem": "In Mearsheimer's definition, institutions…", "options": ["are non-binding sets of norms with no centralized authority", "are a supranational government that enforces rules", "legally compel states to comply", "replace the anarchic system with hierarchy"], "answer": 0, "why": "Institutions = non-binding norms; no centralized authority; states choose whether to comply."}}, {"id": "ir3", "topic": "ir", "front": "Realism — five core assumptions", "back": "1) The international system is anarchic (decentralized units make their own decisions).\n2) States possess (armed/offensive) military capability.\n3) States can never be certain about other states' intentions.\n4) Survival is the most crucial motivation.\n5) States act rationally (wisely) to ensure their survival.", "mcq": {"stem": "Which is one of realism's five assumptions in Mearsheimer's account?", "options": ["States can never be certain about others' intentions", "Institutions are legally binding", "Absolute gains drive cooperation", "Discourses constitute reality"], "answer": 0, "why": "Uncertainty about others' intentions is a core realist assumption. Binding institutions / discourse constituting reality belong to the approaches he criticizes."}}, {"id": "ir4", "topic": "ir", "front": "Realism — three resulting patterns of behaviour", "back": "From the five assumptions, three behaviours follow: (1) states fear one another, anticipating harm; (2) they seek to ensure their own survival; (3) they aim to maximize their relative position of strength (power).", "mcq": {"stem": "Which trio captures the realist patterns of state behaviour?", "options": ["Fear others; ensure survival; maximize relative power", "Trust others; share gains; build community", "Negotiate norms; punish cheats; cooperate", "Centralize; redistribute; deliberate"], "answer": 0, "why": "Realist behaviours: mutual fear, survival-seeking, maximizing relative power."}}, {"id": "ir5", "topic": "ir", "front": "Realism — cooperation, cheating and relative gains", "back": "Cooperation exists but almost always ends in failure, mainly because of the incentives and stigma attached to cheating, and because states care about the balance of power (relative gains). Even when all parties gain, each evaluates how much it gains relative to others. The problem with cheating is that in a cooperative setting you cannot trust the other player not to cheat to gain an edge. For realists, institutions are merely arenas that reflect the existing distribution of power: powerful states create and mould institutions to benefit themselves.", "mcq": {"stem": "For realists, the TWO main barriers to cooperation are…", "options": ["fear of cheating and concern for relative gains", "lack of funding and weak norms", "discourse and recognition", "anarchy and hierarchy"], "answer": 0, "why": "Cheating + relative gains are the two realist barriers; the liberal approach is faulted for ignoring relative gains."}}, {"id": "ir6", "topic": "ir", "front": "Liberal institutionalism (and its flaw)", "back": "It describes the prospects of economic cooperation rather than how to prevent wars. It focuses on situations where states have competing interests in cooperating but no fundamental conflict, and weights economic concerns over security. Like realism, it treats IR as anarchy where states are rational self-help agents; the main barrier to cooperation is cheating. Its solution: states should comply with institutional rules to build confidence, choosing the second-best option (mutual collaboration) over cheating; cheating should be punished via institutions. FLAW: it ignores the other barrier — relative gains. Mearsheimer says it does not adequately resolve whether/when states care about relative gains.", "mcq": {"stem": "Mearsheimer's central criticism of liberal institutionalism is that it…", "options": ["ignores the relative-gains barrier to cooperation", "denies that states are rational", "rejects the assumption of anarchy", "claims discourse constitutes reality"], "answer": 0, "why": "Liberal institutionalism only addresses cheating and overlooks relative gains."}}, {"id": "ir7", "topic": "ir", "front": "Collective security approach (and its flaw)", "back": "It addresses the difficulty of establishing peace and accepts that military might, not just security, is central to IR; institutions are the key to increasing stability and controlling power effectively. States are assumed rational in a self-help world but are urged to renounce force: settle disputes peacefully; states that refuse are 'troublemakers' to be confronted collectively; responsible states' interests must align with the international community's; mutual trust is required. FLAW: it does not show how trust issues and fears are overcome — the possible presence (and possibly large number) of troublemakers makes trusting others hard; it also assumes a complex network of criteria.", "mcq": {"stem": "The collective security approach is faulted by Mearsheimer mainly for…", "options": ["not solving the trust/fear problem (the troublemaker problem)", "ignoring relative gains", "denying that institutions matter", "rejecting rationality"], "answer": 0, "why": "Its flaw is the unresolved trust/fear problem — troublemakers make trust difficult — plus reliance on a complex web of criteria."}}, {"id": "ir8", "topic": "ir", "front": "Critical theory approach (and its flaw)", "back": "Its goal is to transform the existing international order into a global society based on mutual reliance and cooperation. Discourses have a formative effect on the world; because realism was prevalent for so long, it shaped IR and state behaviour and prevented people from seeing other possible states of being. States should view IR as a community, not a stage for self-interest; accountability is central; self-help and power politics are contingent, not necessary. FLAW: it is inadequate and self-contradictory — it must but cannot answer: why has realism been dominant for so long? why discard it now? why will a harmony-emphasizing communitarian discourse replace it? It holds a view of reality diametrically opposed to realism (for which constructing reality is pointless).", "mcq": {"stem": "A key contradiction Mearsheimer attributes to the critical theory approach is that it cannot explain…", "options": ["why realism dominated for so long yet should now be replaced", "how private and public goods are distributed", "why small coalitions buy loyalty", "how surplus funds industrialization"], "answer": 0, "why": "Critical theory can't coherently say why realism was dominant, why discard it now, and why communitarian discourse will replace it."}}, {"id": "g1", "topic": "concepts", "front": "Night-watchman State", "back": "Night-watchman state is a concept in political philosophy which indicates that the only responsibility and aim of the state is protecting individuals from any hazardous situation. So, state’s main goal is the security of its citizens through various organs like police, prison, military etc.", "mcq": {"stem": "Which term is defined as: \"____ is a concept in political philosophy which indicates that the only responsibility and aim of the ____ is protecting individuals from any hazardous situation. So, ____’s main goal is the security of its citiz\"", "options": ["Plurality voting system", "Night-watchman State", "Communitarianism", "Conservative nationalism"], "answer": 1, "why": "Night-watchman State — Night-watchman state is a concept in political philosophy which indicates that the only responsibility and aim of the state is protecting individuals from any hazardous situation. So, state’s main goa"}}, {"id": "g2", "topic": "concepts", "front": "Nanny state", "back": "A state with extensive social responsibilities.We can think about welfare states here.", "mcq": {"stem": "Which term is defined as: \"A ____ with extensive social responsibilities.We can think about welfare ____s here.\"", "options": ["Social contract", "Hegemony", "Nanny state", "Theocracy"], "answer": 2, "why": "Nanny state — A state with extensive social responsibilities.We can think about welfare states here."}}, {"id": "g3", "topic": "methods", "front": "Ontology", "back": "Philosophical study on things being, existence etc."}, {"id": "g4", "topic": "methods", "front": "Epistemology", "back": "Examination of the nature of knowledge and how to acquire it."}, {"id": "g5", "topic": "methods", "front": "Parochialism", "back": "Is a term that is coined by Giovanni Sartori who is a comparative politics scientist. Parochialism is one of the four common mistakes in comparing and it means that in parochialism one looks at a particular thing or subject but forgets the wider conception."}, {"id": "g6", "topic": "methods", "front": "Degreeism", "back": "Is a term that is coined by Giovanni Sartori who is a comparative politics scientist. Differences in degrees cannot be misconceived. For example, in studying democracy one has to also look at non-democracies, but there is no such thing as 80% non-democratic country."}, {"id": "g7", "topic": "methods", "front": "Conceptual stretching", "back": "Is a term that is coined by Giovanni Sartori who is a comparative politics scientist. Changing or extending the definition of something to fit into the category."}, {"id": "g8", "topic": "methods", "front": "Misclassification", "back": "Is a term that is coined by Giovanni Sartori who is a comparative politics scientist. And this mistake means that criterion of classification is made wrong. For example, creating pseudo-classes for including the concepts."}, {"id": "g9", "topic": "concepts", "front": "Class", "back": "Is a group of people which is categorized on the basis of their relations with the means of production. According to Karl Marx, there are 2 classes; bourgeoisie and proletariat."}, {"id": "g10", "topic": "concepts", "front": "Power", "back": "In social and political sciences, power is the ability to influence or control other people."}, {"id": "g11", "topic": "concepts", "front": "Authority", "back": "Can be defined as legitimate power. Weber distinguishes three kinds of authority. Firstly, traditional authority, its legitimacy is rooted in history. Charismatic authority stems from personality. Lastly, legal-rational authority is grounded in a set of impersonal rules."}, {"id": "g12", "topic": "concepts", "front": "State", "back": "State is the sole and ultimate political object. There are various definitions for it but Weber’s state definition is the most remembered which claims that state is an organ which have a monopoly of the legitimate use of physical force within a given territory."}, {"id": "g13", "topic": "concepts", "front": "Minimal state", "back": "Make sure its citizens ensure widest possible realm of freedom. Provide security for individual in domestic and international realm + ensures private contracts are not violated between individuals: UK&US"}, {"id": "g14", "topic": "concepts", "front": "Developmental state", "back": "Economic interventionism. More active state in terms of promoting economic development Japan&Germany"}, {"id": "g15", "topic": "concepts", "front": "Social-democratic state", "back": "Economic interventionism again but for the sake of social justice this time. Nordic countries -Collectivized state: entirety of economic life under the state control.USSR, planned economies."}, {"id": "g16", "topic": "concepts", "front": "Totalitarian state", "back": "The most extreme form. The state does not only intervene the economy but every aspect of life, religion, family, education etc. Abolishment of the private so to speak."}, {"id": "g17", "topic": "concepts", "front": "Statism", "back": "The belief that state intervention is the most appropriate means of resolving political problems or bringing about economic and social justice. Deep and unquestioning faith to the state.", "mcq": {"stem": "Which term is defined as: \"The belief that state intervention is the most appropriate means of resolving political problems or bringing about economic and social justice. Deep and unquestioning faith to the state.\"", "options": ["Statism", "Presidential government", "Liberalism", "Internationalism"], "answer": 0, "why": "Statism — The belief that state intervention is the most appropriate means of resolving political problems or bringing about economic and social justice. Deep and unquestioning faith to the state."}}, {"id": "g18", "topic": "concepts", "front": "Disciplinary power", "back": "This is a concept that is produced by Foucault. Disciplinary power is constituted through the discourses we have (discourse=knowledge=power). Further disciplinary power operationalized through a normalization process of certain ideas and ideologies. Thus, DP leads us to behave in a certain way, accept social hierarchies, be open to examination/observation. The tools of this power are schools, hospitals, military, office etc."}, {"id": "g19", "topic": "concepts", "front": "State of nature", "back": "Is a hypothetical concept in political philosophy about the conditions of the people before the existence of society."}, {"id": "g20", "topic": "concepts", "front": "Social contract", "back": "A concept in political philosophy. It is an endeavor to resolve two important questions in political philosophy: 1) How can we construct the legitimate authority in the society which would rule us all? 2) How we as the subjects of this legitimate authority will relate to this authority?"}, {"id": "g21", "topic": "concepts", "front": "Federalism", "back": "A system of governing in which there is mixed or compound government, where combination of general government and regional government is in the same political system.  •  Sharing of sovereignty between central and peripheral institutions. Neither central nor peripheral institutions can legally or politically subordinate the other. Separate identities or political communities in a nation state may enforce for federalism. Geographical size, cultural and ethnic diversity can be important reasons to adopt federalism.", "mcq": {"stem": "Which term is defined as: \"A system of governing in which there is mixed or compound government, where combination of general government and regional government is in the same political system.  •  Sharing of sovereignty between central and peripheral insti\"", "options": ["Expansionist nationalism", "Disciplinary power", "Federalism", "Authoritarianism"], "answer": 2, "why": "Federalism — A system of governing in which there is mixed or compound government, where combination of general government and regional government is in the same political system.  •  Sharing of sovereignty betwee"}}, {"id": "g22", "topic": "concepts", "front": "Deliberative democracy", "back": "Is a form of democracy in which deliberation is central in decision- making process."}, {"id": "g23", "topic": "ir", "front": "Short of war", "back": "A concept in international relations in which there is a situation where a state avoids war in all measures."}, {"id": "g24", "topic": "concepts", "front": "Class consciousness", "back": "Refers to beliefs of a person who holds their own social class and economic rank in their mind and knows that the structure of the society and their interest are shaped through. It is an awareness about the position of one about itself. So, their demands and actions as well shaped through this consciousness."}, {"id": "g25", "topic": "concepts", "front": "State of war", "back": "Is a hypothetical concept in morality and political philosophy which popularized by Hobbes where he claims that the state of nature is the state of war where there is constant war, distrust, and maleficence since human beings are selfish creatures. So, in the state of war there is a constant threat against your well-being, feeling of insecurity and fear."}, {"id": "g26", "topic": "concepts", "front": "Blank check", "back": "Or carte blanche is a term that is associated with political philosopher Hobbes. According to him, people sign a carte blanche with the Leviathan (the authority) in which Leviathan is able to get the consent of the people."}, {"id": "g27", "topic": "concepts", "front": "Separation of power", "back": "Is a concept in political science and law, and associated with Montesquieu, where legislation, judiciary and executive branches and their political power is separated."}, {"id": "g28", "topic": "concepts", "front": "Checks and balances", "back": "Like separation of power, this concept is created by Montesquieu and this system-based control allows one branch to limit another and control the boundaries of duties."}, {"id": "g29", "topic": "ir", "front": "Balance of Power", "back": "The balance of power theory in international relations suggests that national security is enhanced when military capability is distributed so that no one state is strong enough to dominate all others.  •  A pattern of interaction amongst states that tends to curb aggression and expansionism by rendering them impracticable.", "mcq": {"stem": "Which term is defined as: \"The ____ theory in international relations suggests that national security is enhanced when military capability is distributed so that no one state is strong enough to dominate all others.  •  A pattern of interaction \"", "options": ["Semi-presidential constitutional democracy", "Balance of Power", "Night-watchman State", "Communitarianism"], "answer": 1, "why": "Balance of Power — The balance of power theory in international relations suggests that national security is enhanced when military capability is distributed so that no one state is strong enough to dominate all others."}}, {"id": "g30", "topic": "concepts", "front": "Sovereignty", "back": "Is a concept in political philosophy in which one side has the full power and control over the others. Sovereign is considered to be an ultimate authority over the polity.", "mcq": {"stem": "Which term is defined as: \"Is a concept in political philosophy in which one side has the full power and control over the others. Sovereign is considered to be an ultimate authority over the polity.\"", "options": ["Sovereignty", "Class", "Social-democratic state", "Harm principle"], "answer": 0, "why": "Sovereignty — Is a concept in political philosophy in which one side has the full power and control over the others. Sovereign is considered to be an ultimate authority over the polity."}}, {"id": "g31", "topic": "concepts", "front": "Popular sovereignty", "back": "The principle that there is no higher authority than the will of the people.", "mcq": {"stem": "Which term is defined as: \"The principle that there is no higher authority than the will of the people.\"", "options": ["Popular sovereignty", "Dialectical change", "Structure and agency", "Statism"], "answer": 0, "why": "Popular sovereignty — The principle that there is no higher authority than the will of the people."}}, {"id": "g32", "topic": "concepts", "front": "Polity", "back": "A society organized through the exercise of political authority.", "mcq": {"stem": "Which term is defined as: \"A society organized through the exercise of political authority.\"", "options": ["Great Power", "Realpolitik", "Polity", "State socialism"], "answer": 2, "why": "Polity — A society organized through the exercise of political authority."}}, {"id": "g33", "topic": "concepts", "front": "Anti-politics", "back": "Because of the disappointment with formal and established political processes people start to retreat from the conventional means of participation in political field. This leads nonparticipation, support for antisystemic parties, and/or use of direct action.", "mcq": {"stem": "Which term is defined as: \"Because of the disappointment with formal and established political processes people start to retreat from the conventional means of participation in political field. This leads nonparticipation, support for antisystemic parties, \"", "options": ["Secular state", "Anti-politics", "Elective dictatorship", "Rogue state"], "answer": 1, "why": "Anti-politics — Because of the disappointment with formal and established political processes people start to retreat from the conventional means of participation in political field. This leads nonparticipation, supp"}}, {"id": "g34", "topic": "ir", "front": "Perpetual peace", "back": "Is a concept in political philosophy associated to Immanuel Kant and his book “perpetual peace”. This concept means that human race will be able to establish peace for the whole world through their reasons. Firstly, individuals in their localities will gain emancipation, secondly, states will gather together under a roof an organization with a collective action, and thirdly, cosmopolitan world government will be established. This idea very much influenced the establishment of international organizations such as UN."}, {"id": "g35", "topic": "concepts", "front": "Feudalism", "back": "Is a legal, political, economic and military system and was popular in the Medieval Europe during 9th and 15th century. There were serfdom, land lordship and etc. Decentralized, weak states in locals. Aristocrats had the means of production in the economic order. Most of the time, there was a divine king who enjoyed the authority in a given territory.", "mcq": {"stem": "Which term is defined as: \"Is a legal, political, economic and military system and was popular in the Medieval Europe during 9th and 15th century. There were serfdom, land lordship and etc. Decentralized, weak states in locals. Aristocrats had the means of \"", "options": ["Diplomacy", "Issue voting", "Propaganda", "Feudalism"], "answer": 3, "why": "Feudalism — Is a legal, political, economic and military system and was popular in the Medieval Europe during 9th and 15th century. There were serfdom, land lordship and etc. Decentralized, weak states in locals."}}, {"id": "g36", "topic": "concepts", "front": "Ideology", "back": "It is a system of beliefs and meanings which give a sense of world and motivation to organize and mobilize."}, {"id": "g37", "topic": "ir", "front": "Diplomacy", "back": "Used in a realism by Kissenger, this concept is the act and art of negotiation that is popularized by the Italian city-states during Renaissance. Raison d’état: means reason of the state or the national interest. A concept that is used in realism in international relations to explain the interests of the states."}, {"id": "g38", "topic": "ir", "front": "Realpolitik", "back": "Is a concept in international relations and realism field, where states make their mind by looking at the considerations of the given circumstances.", "mcq": {"stem": "Which term is defined as: \"Is a concept in international relations and realism field, where states make their mind by looking at the considerations of the given circumstances.\"", "options": ["Mutually assured destruction", "Semi-presidential constitutional democracy", "Parliamentary constitutional democracy", "Realpolitik"], "answer": 3, "why": "Realpolitik — Is a concept in international relations and realism field, where states make their mind by looking at the considerations of the given circumstances."}}, {"id": "g39", "topic": "ir", "front": "Collective security", "back": "Is a concept in international relations and favored during the League of Nations which claims that security of one is the concern of all and leads to collective response to threats and breaches.", "mcq": {"stem": "Which term is defined as: \"Is a concept in international relations and favored during the League of Nations which claims that ____ of one is the concern of all and leads to ____ response to threats and breaches.\"", "options": ["Monetarism", "Democratization", "Coalition", "Collective security"], "answer": 3, "why": "Collective security — Is a concept in international relations and favored during the League of Nations which claims that security of one is the concern of all and leads to collective response to threats and breaches."}}, {"id": "g40", "topic": "concepts", "front": "Presidential constitutional democracy", "back": "It is a system of government in which the head of state and the head of the government are the same and leads the executive branch."}, {"id": "g41", "topic": "concepts", "front": "Parliamentary constitutional democracy", "back": "It is a system of government in which the head of the state and the head of government are the different and executive branch derives its legitimacy from parliament."}, {"id": "g42", "topic": "concepts", "front": "Semi-presidential constitutional democracy", "back": "It is a system of government in which president exists along with the prime minister and a cabinet."}, {"id": "g43", "topic": "concepts", "front": "Plurality voting system", "back": "This is a voting system in which majority of the votes are taken into consideration and leads to misrepresentation and lack of interest in minorities. Plurality system, electoral process in which the candidate who polls more votes than any other candidate is elected. It is distinguished from the majority system, in which, to win, a candidate must receive more votes than all other candidates combined. Election by a plurality is the most common method of selecting candidates for public office."}, {"id": "g44", "topic": "concepts", "front": "Proportional representation", "back": "This is a voting system in which divisions in an electorate are reflected proportionally in the elected body.  •  The principle that parties should be represented in an assembly or parliament in direct proportion to their overall electoral strength (as opposed to majoritarian systems)"}, {"id": "g45", "topic": "concepts", "front": "Hegemony", "back": "Is a concept in political science in which ruling class has a manipulation power over the value systems and morals of the society, so that ruling class’ view becomes the dominant one. This concept is associated to Gramsci. He complicates the dichotomy of structure and superstructure in Marxist literature, and argues that who holds the power in the economic structure uses the means in superstructure, i.e. media, education etc, to reproduce the consent for the domination in society."}, {"id": "g46", "topic": "ir", "front": "Soft power", "back": "Is a concept in International Relations which is derived by Joseph Nye. This is an ability to solve the issues in IR through attracting the other side or co-opting on the basis of certain norms rather than using pure coercion (hard power)."}, {"id": "g47", "topic": "concepts", "front": "Base and superstructure", "back": "These are the concepts that are driven by Karl Marx. Base is the concentration of means and relations of production. Base is also known as infrastructure. Superstructure are accumulation of every part of society like culture, roles, rituals that are created and shaped by the base to determine society’s relation and ideas."}, {"id": "g48", "topic": "concepts", "front": "Estrangement", "back": "A concept associated by Karl Marx which is related to alienation. The alienation from the self is so strong that it leads to total estrangement of one’s self to itself. Capitalist mode of production reduced the labor to a mere commodity and work becomes depersonalized activity. In such a situation workers alienate from the products of their labor, the process, the fellow worker, themselves as creative social beings", "mcq": {"stem": "Which term is defined as: \"A concept associated by Karl Marx which is related to alienation. The alienation from the self is so strong that it leads to total ____ of one’s self to itself. Capitalist mode of production reduced the labor to a mere com\"", "options": ["Semi-presidential constitutional democracy", "Estrangement", "Centralization", "Libertarianism"], "answer": 1, "why": "Estrangement — A concept associated by Karl Marx which is related to alienation. The alienation from the self is so strong that it leads to total estrangement of one’s self to itself. Capitalist mode of production r"}}, {"id": "g49", "topic": "concepts", "front": "Nation-state", "back": "Is a concept where political entity of a state is also cultural entity of the state. Mostly, a 19th century phenomena where states are positioned themselves with the predominant culture that they own.", "mcq": {"stem": "Which term is defined as: \"Is a concept where political entity of a state is also cultural entity of the state. Mostly, a 19th century phenomena where states are positioned themselves with the predominant culture that they own.\"", "options": ["Social contract", "Collective security", "Balance of Power", "Nation-state"], "answer": 3, "why": "Nation-state — Is a concept where political entity of a state is also cultural entity of the state. Mostly, a 19th century phenomena where states are positioned themselves with the predominant culture that they own."}}, {"id": "g50", "topic": "ir", "front": "World-systems theory", "back": "A theory which is devised by Immanuel Wallerstein. According to this theory, contrasting to modernization theory, world is divided into core, semi-periphery and periphery countries. In capitalist order, periphery and semi-periphery countries provide necessary raw materials to core countries which process these raw materials and create a larger surplus value out of them. In this system, there is a dynamic relationship in which core countries can lost their hegemony while periphery can lead to being core."}, {"id": "g51", "topic": "methods", "front": "Institutionalism", "back": "Is a widely used concept in sociology, political economy and political science. It emphasizes the importance of the institutions in shaping and affecting the politics, economic order, culture and life. The institutions carry great importance to understand the political and social trends."}, {"id": "g52", "topic": "ir", "front": "New world order", "back": "A concept that is used to remark the changes in the history of the world order."}, {"id": "g53", "topic": "concepts", "front": "Utilitarianism", "back": "Is a concept that is popularized by Jeremy Bentham in which the individual’s best action and motive is the maximize the profit of each action. This is also applied to pain and pleasure by John Stuart Mill in which rational humans seek pleasure over pain."}, {"id": "g54", "topic": "ir", "front": "Imperialism", "back": "Is a concept that means the advocacy of the empire. This is a policy extended from a country to another country to exploit and colonize."}, {"id": "g55", "topic": "concepts", "front": "Iron cage", "back": "A concept derived by Max Weber, and related to rationalization process in the society. This iron cage traps us to our current situation by creating a pressure over ourselves and by others to act in a way that is strategic and beneficial. In sociology, the iron cage is a term coined by Max Weber for the increased rationalization inherent in social life, particularly in Western capitalist societies. The \"iron cage\" thus traps individuals in systems based purely on teleological efficiency, rational calculation and control. Weber also described the bureaucratization of social order as \"the polar night of icy darkness\"."}, {"id": "g56", "topic": "methods", "front": "Structure and agency", "back": "Structure is recurrent patterns of arrangement in society. Agency is the capacity of one’s to act independently to make their own free choices."}, {"id": "g57", "topic": "concepts", "front": "Creative destruction", "back": "By Schumpeter, this is a process in economics in which there is a constant mutation of the system. Where a system is revolutionized and topped down by one, it also destroyed and created a new system."}, {"id": "g58", "topic": "ir", "front": "Security dilemma", "back": "Is a concept in international relation in which means a process where one state’s pursue or act of increasing its security, leads to suspicion and similar behavior of the other states.", "mcq": {"stem": "Which term is defined as: \"Is a concept in international relation in which means a process where one state’s pursue or act of increasing its ____, leads to suspicion and similar behavior of the other states.\"", "options": ["Plebiscitary democracy", "Theocracy", "Elective dictatorship", "Security dilemma"], "answer": 3, "why": "Security dilemma — Is a concept in international relation in which means a process where one state’s pursue or act of increasing its security, leads to suspicion and similar behavior of the other states."}}, {"id": "g59", "topic": "concepts", "front": "Civil society", "back": "A concept used by Hegel, Aristotle and many more in which there is a aggregate of non-governmental organizations and institutions that shape and influence the politics and societal life. When we make a distinction between the state (public) and civil society (private), we can assert that civil society is composed of institutions that are independent from the state and organized by individuals in pursuit of their own ends.", "mcq": {"stem": "Which term is defined as: \"A concept used by Hegel, Aristotle and many more in which there is a aggregate of non-governmental organizations and institutions that shape and influence the politics and societal life. When we make a distinction between the stat\"", "options": ["Rule of law", "Plurality voting system", "Civil society", "Secular state"], "answer": 2, "why": "Civil society — A concept used by Hegel, Aristotle and many more in which there is a aggregate of non-governmental organizations and institutions that shape and influence the politics and societal life. When we make "}}, {"id": "g60", "topic": "concepts", "front": "Harm principle", "back": "A concept derived by Mill in “On Liberty”. Harm principle denotes that one’s freedom is limited to others freedom in which one’s action should not breach the freedom of others."}, {"id": "g61", "topic": "concepts", "front": "Governance", "back": "The various ways through which social life is organized. It is a broad term, the government can be seen as one of the institutions which involves in governance. So, there can be a type of governance without a government.", "mcq": {"stem": "Which term is defined as: \"The various ways through which social life is organized. It is a broad term, the government can be seen as one of the institutions which involves in ____. So, there can be a type of ____ without a government.\"", "options": ["Governance", "Historical materialism", "Pluralism", "Anticolonial nationalism"], "answer": 0, "why": "Governance — The various ways through which social life is organized. It is a broad term, the government can be seen as one of the institutions which involves in governance. So, there can be a type of governance w"}}, {"id": "g62", "topic": "concepts", "front": "Government gridlock", "back": "Paralysis resulting from institutional rivalry within government or the attempt to respond to conflicting public demands."}, {"id": "g63", "topic": "concepts", "front": "Totalitarianism", "back": "It is an all-encompassing political system. It can be established by pervasive ideological manipulation, open terror, and brutality. It differs from autocracy or authoritarianism because it seeks to “total power” through the politicization of every aspect of social and personal existence. So, the abolition of the private and civil society is the case.", "mcq": {"stem": "Which term is defined as: \"It is an all-encompassing political system. It can be established by pervasive ideological manipulation, open terror, and brutality. It differs from autocracy or authoritarianism because it seeks to “total power” through the polit\"", "options": ["Liberal democracy", "Security dilemma", "Popular sovereignty", "Totalitarianism"], "answer": 3, "why": "Totalitarianism — It is an all-encompassing political system. It can be established by pervasive ideological manipulation, open terror, and brutality. It differs from autocracy or authoritarianism because it seeks to “"}}, {"id": "g64", "topic": "concepts", "front": "Authoritarianism", "back": "Is a form of gov. characterized by strong central power and limited political freedom. Individual freedoms are subordinate to the state and there is no constitutional accountability under an authoritarian regime.Linz’'s influential 1964 description of authoritarianism characterized authoritarian systems by four qualities: 1. Limited pluralism, that is such regimes place constraints on political institutions and groups like legislature, parties and interest groups; 2. A basis for legitimacy based on emotion, especially the identification of the regime as a necessary evil to combat \"easily recognizable societal problems\" such as underdevelopment or insurgency; 3. Minimal social mobilization most often caused by constraints on the public such as suppression of political opponents and anti-regime activity; Informally defined executive power with often vague and shifting powers 4.", "mcq": {"stem": "Which term is defined as: \"Is a form of gov. characterized by strong central power and limited political freedom. Individual freedoms are subordinate to the state and there is no constitutional accountability under an authoritarian regime.Linz’'s influentia\"", "options": ["Libertarianism", "Civil society", "Creative destruction", "Authoritarianism"], "answer": 3, "why": "Authoritarianism — Is a form of gov. characterized by strong central power and limited political freedom. Individual freedoms are subordinate to the state and there is no constitutional accountability under an authorita"}}, {"id": "g65", "topic": "concepts", "front": "Liberal democracy", "back": "In a liberal democracy the government is formed through regular and competitive elections based on universal suffrage and political equality. In this regime type there are internal and external checks on government that are designed to guarantee the liberty of the citizens and these checks protect the citizens against the state. “Limited government” is a key concept here, politically and economically.", "mcq": {"stem": "Which term is defined as: \"In a ____ the government is formed through regular and competitive elections based on universal suffrage and political equality. In this regime type there are internal and external checks on government that are design\"", "options": ["Civil society", "Class", "Liberal democracy", "Disciplinary power"], "answer": 2, "why": "Liberal democracy — In a liberal democracy the government is formed through regular and competitive elections based on universal suffrage and political equality. In this regime type there are internal and external checks"}}, {"id": "g66", "topic": "concepts", "front": "Democratization", "back": "Democratization refers to the transition from authoritarianism to liberal democracy by granting of basic freedoms and particularly political rights, the establishment of popular and competitive elections, and introduction to market reforms.", "mcq": {"stem": "Which term is defined as: \"____ refers to the transition from authoritarianism to liberal democracy by granting of basic freedoms and particularly political rights, the establishment of popular and competitive elections, and introduction to marke\"", "options": ["Bipolarity", "Postmaterialism", "Democratization", "Totalitarianism"], "answer": 2, "why": "Democratization — Democratization refers to the transition from authoritarianism to liberal democracy by granting of basic freedoms and particularly political rights, the establishment of popular and competitive electi"}}, {"id": "g67", "topic": "concepts", "front": "Consociational democracy", "back": "A form of democracy that operates through power-sharing and a close association amongst a number of parties or political formations. It developed in societies that are divided by deep religious, ideological, regional, cultural or other differences such as Belgium, Austria and Switzerland.", "mcq": {"stem": "Which term is defined as: \"A form of ____ that operates through power-sharing and a close association amongst a number of parties or political formations. It developed in societies that are divided by deep religious, ideological, regional, cultural or \"", "options": ["Consociational democracy", "Iron cage", "Legitimacy", "Modern liberalism"], "answer": 0, "why": "Consociational democracy — A form of democracy that operates through power-sharing and a close association amongst a number of parties or political formations. It developed in societies that are divided by deep religious, ideol"}}, {"id": "g68", "topic": "concepts", "front": "Semi-democracy", "back": "A regime in which democratic and authoritarian features operate alongside one another in a stable combination."}, {"id": "g69", "topic": "concepts", "front": "Secular state", "back": "Political and religious positions are kept strictly separate.", "mcq": {"stem": "Which term is defined as: \"Political and religious positions are kept strictly separate.\"", "options": ["Constitutional government", "Secular state", "Preemptive attack", "Mutually assured destruction"], "answer": 1, "why": "Secular state — Political and religious positions are kept strictly separate."}}, {"id": "g70", "topic": "concepts", "front": "Theocracy", "back": "Religious authority should prevail over political authority.", "mcq": {"stem": "Which term is defined as: \"Religious authority should prevail over political authority.\"", "options": ["Blank check", "Marxism (in IR theory)", "Theocracy", "Totalitarian state"], "answer": 2, "why": "Theocracy — Religious authority should prevail over political authority."}}, {"id": "g71", "topic": "concepts", "front": "Liberalism", "back": "Main elements: individualism, freedom, reason, equality, toleration, consent and constitutionalism."}, {"id": "g72", "topic": "concepts", "front": "Classical liberalism", "back": "Hayek (atomistic individuals, negative freedoms and minimal state)"}, {"id": "g73", "topic": "concepts", "front": "Modern liberalism", "back": "Keynes (humans as social beings, positive freedoms and welfare states)"}, {"id": "g74", "topic": "concepts", "front": "Economic liberalism", "back": "The belief in self-regulating market and equal opportunities in market place."}, {"id": "g75", "topic": "concepts", "front": "Political liberalism", "back": "Preservation of individual rights and liberties in a given political system."}, {"id": "g76", "topic": "concepts", "front": "Conservatism", "back": "The key position is “change in order to preserve”. Edmund Burke. Respectful to tradition because it is accumulated through wisdom of the past, and institutions and practices. Strong sense of social and historical belonging. Human nature is imperfect, dependent, morally corrupt and security-seeking. So, there is always need for strong state, strict laws and stiff penalties. Society is organic whole based on hierarchies."}, {"id": "g77", "topic": "concepts", "front": "Neoliberalism", "back": "State retreat from the market again. Keynesian failure important here. Hayek & Friedman and their individual - market relation perspective is the basis. This can bring growth and efficiency.", "mcq": {"stem": "Which term is defined as: \"State retreat from the market again. Keynesian failure important here. Hayek & Friedman and their individual - market relation perspective is the basis. This can bring growth and efficiency.\"", "options": ["Nation-state", "World-systems theory", "Neoliberalism", "Elective dictatorship"], "answer": 2, "why": "Neoliberalism — State retreat from the market again. Keynesian failure important here. Hayek & Friedman and their individual - market relation perspective is the basis. This can bring growth and efficiency."}}, {"id": "g78", "topic": "concepts", "front": "Neoconservatism", "back": "The aim is to restore the conventional authorities and values linked to family, religion and nation. This is the way to create social cohesion.", "mcq": {"stem": "Which term is defined as: \"The aim is to restore the conventional authorities and values linked to family, religion and nation. This is the way to create social cohesion.\"", "options": ["Classical liberalism", "Social capital", "Neoconservatism", "Base and superstructure"], "answer": 2, "why": "Neoconservatism — The aim is to restore the conventional authorities and values linked to family, religion and nation. This is the way to create social cohesion."}}, {"id": "g79", "topic": "concepts", "front": "Socialism", "back": "Abolishment of capitalist market economy which is based on private property and usually want to replace it with common ownership and planning economy led by state. Humans are social creatures develop together. Fraternity against the individual interests and competition. Equality of outcome as opposed to equality of opportunity. Outcomes should be distributed on the basis of need, not merit."}, {"id": "g80", "topic": "concepts", "front": "Social democrats", "back": "Defined as who embrace socialist values and try to reform the constitution accordingly. A balance between market and the state, individual and the community. Market is accepted as mode of production however distribution will be based on values rather than mere market principles."}, {"id": "g81", "topic": "concepts", "front": "Historical materialism", "back": "Social and historical developments can be explained in terms of economic and class factors because of the active relations between base and superstructure."}, {"id": "g82", "topic": "concepts", "front": "Dialectical change", "back": "Internal forces or contradiction in a mode of production will result in class antagonism which will bring a change. -Alienation -Class struggle -Surplus value -Proletarian revolution"}, {"id": "g83", "topic": "concepts", "front": "Communism", "back": "Classless society, production for use and etc."}, {"id": "g84", "topic": "concepts", "front": "Fascism", "back": "It is an anticharacter of French Revolution and its values such as rationalism, progress, freedom, equality. As opposed to these, struggle,leadership,power, self-sacrifice, heroism and war were embraced. The core idea: the image of an organically unified national community."}, {"id": "g85", "topic": "concepts", "front": "Anarchism", "back": "Struggle against established political authorities."}, {"id": "g86", "topic": "concepts", "front": "Feminism", "back": "Struggle to end patriarchal social and political order in society."}, {"id": "g87", "topic": "concepts", "front": "Majority rule", "back": "The rule that the will of majority overrides the will of the minority."}, {"id": "g88", "topic": "concepts", "front": "Democracy", "back": "Government of the people, by the people for the people. If people directly govern themselves, direct democracy. If people choose someone on behalf of themselves to govern, representative democracy."}, {"id": "g89", "topic": "concepts", "front": "Plebiscitary democracy", "back": "Unmediated link between the ruler and ruled sustained by plebiscites/referendums."}, {"id": "g90", "topic": "concepts", "front": "Radical democracy", "back": "A form of democracy that favours decentralization and participation, the widest possible dispersion of power in political life."}, {"id": "g91", "topic": "concepts", "front": "Parliamentary democracy", "back": "Operates through a popularly elected deliberative assembly, which establishes indirect link between government and the governed. The government is responsible to not directly to the public but its representatives. By the virtues of their education and opportunity they discuss and deliberate o citizens’ best interests."}, {"id": "g92", "topic": "concepts", "front": "Constitutional government", "back": "A system of government that operates within a set of legal and institutional constraints that both limit its power and protect individual liberty."}, {"id": "g93", "topic": "concepts", "front": "Cultural nationalism", "back": "Primarily emphasizes the regeneration of the nation as a distinctive civilization rather than as a discrete political community. Thus, nation is unique, historical and organic whole. Political nationalism, on the other hand, is based on citizenship."}, {"id": "g94", "topic": "concepts", "front": "Liberal nationalism", "back": "Humankind is naturally divided into a collection of nations, each possessed of a separate identity. Nations are organic communities not artificial creation of political leaders or ruling class. And ever nation has the right to national self-determination."}, {"id": "g95", "topic": "concepts", "front": "Conservative nationalism", "back": "Concerned with less about national self-determination but more about its promise of social cohesion and public order in the sentiment of national patriotism."}, {"id": "g96", "topic": "concepts", "front": "Expansionist nationalism", "back": "This form of nationalism is associated with chauvinistic beliefs and doctrines, ie. belief in superiority of one’s own group. Militant, expansionist type."}, {"id": "g97", "topic": "concepts", "front": "Anticolonial nationalism", "back": "The emphasis is on national self-determination but it is very much a combination of economic and political liberation of the nation."}, {"id": "g98", "topic": "ir", "front": "Idealism", "back": "In this view, international relations should focus on the question of how “should” actors behave. So, the concern is about normative principles rather than empirical analysis of how international actors behave. Interdependence, free trade and collective security are keywords. Kantian. Diplomacy."}, {"id": "g99", "topic": "ir", "front": "Internationalism", "back": "This is a belief that human affairs should be organized according to not only national but also universal principles for harmony and transnational cooperation. This term is related to idealism."}, {"id": "g100", "topic": "ir", "front": "Realism", "back": "The emphasis is on power politics and competing national interests. Nation states as principal actors can act autonomously. Carr & Morgenthau here two important scholars. In this view idealism is simply naive. International politics is regarded as state of nature. Hobbesian. Military power."}, {"id": "g101", "topic": "ir", "front": "Neorealism", "back": "Basic principles are very much same with realism. However, here the emphasis on the structure of international politics, rather than individual power-seeking states. Waltz."}, {"id": "g102", "topic": "ir", "front": "Power Politics", "back": "An approach to the politics based on the assumption that the pursuit of power is the principal human goal."}, {"id": "g103", "topic": "ir", "front": "Great Power", "back": "A state deemed to rank amongst the most powerful in a hierarchical state system, reflected in its influence over minor states."}, {"id": "g104", "topic": "ir", "front": "Pluralism", "back": "This view react against realism’s assumption that only sovereign nation-states are the legit actors in IR. They suggest transnational companies or NGOs are important actors as well. So, the autonomy of the nation states in IR, should be revisited."}, {"id": "g105", "topic": "ir", "front": "Marxism (in IR theory)", "back": "The stress is on economic power and international capital. Transnational companies displaced nation states in world stage. Now, we talk about core and peripheral states in economic sense to understand world order."}, {"id": "g106", "topic": "ir", "front": "Bipolarity", "back": "The tendency of the international system to revolve around two poles. However, it also refers to a balance in world order.", "mcq": {"stem": "Which term is defined as: \"The tendency of the international system to revolve around two poles. However, it also refers to a balance in world order.\"", "options": ["Checks and balances", "Neoliberalism", "Bipolarity", "Class dealignment"], "answer": 2, "why": "Bipolarity — The tendency of the international system to revolve around two poles. However, it also refers to a balance in world order."}}, {"id": "g107", "topic": "ir", "front": "Unipolarity", "back": "An international system in which there is one preeminent state; the existence of single great power.", "mcq": {"stem": "Which term is defined as: \"An international system in which there is one preeminent state; the existence of single great power.\"", "options": ["Coalition", "Semi-presidential constitutional democracy", "Negative rights", "Unipolarity"], "answer": 3, "why": "Unipolarity — An international system in which there is one preeminent state; the existence of single great power."}}, {"id": "g108", "topic": "ir", "front": "Multipolarity", "back": "An international system in which there are three or more power centres, may cause instability.", "mcq": {"stem": "Which term is defined as: \"An international system in which there are three or more power centres, may cause instability.\"", "options": ["Balance of Power", "Multipolarity", "Systems theory", "Parochialism"], "answer": 1, "why": "Multipolarity — An international system in which there are three or more power centres, may cause instability."}}, {"id": "g109", "topic": "ir", "front": "Unilateralism", "back": "One-sidedness; a policy determined by the interests and objectives of a single state, unconstrained by other states or bodies."}, {"id": "g110", "topic": "ir", "front": "Mutually assured destruction", "back": "A condition in which two states each possess a sufficient nuclear capacity to destroy the other regardless of which one attacks first.", "mcq": {"stem": "Which term is defined as: \"A condition in which two states each possess a sufficient nuclear capacity to destroy the other regardless of which one attacks first.\"", "options": ["Federalism", "Social-democratic state", "Government gridlock", "Mutually assured destruction"], "answer": 3, "why": "Mutually assured destruction — A condition in which two states each possess a sufficient nuclear capacity to destroy the other regardless of which one attacks first."}}, {"id": "g111", "topic": "ir", "front": "Rogue state", "back": "A state whose foreign policy poses a threat to neighboring or other states, through its aggressive intent, build-up of weapons, or association with terrorism: Somalia, Afghanistan etc.", "mcq": {"stem": "Which term is defined as: \"A ____ whose foreign policy poses a threat to neighboring or other ____s, through its aggressive intent, build-up of weapons, or association with terrorism: Somalia, Afghanistan etc.\"", "options": ["Rogue state", "Anti-politics", "Constitution", "Disciplinary power"], "answer": 0, "why": "Rogue state — A state whose foreign policy poses a threat to neighboring or other states, through its aggressive intent, build-up of weapons, or association with terrorism: Somalia, Afghanistan etc."}}, {"id": "g112", "topic": "ir", "front": "Preemptive attack", "back": "A military action to forestall or prevent likely future aggression."}, {"id": "g113", "topic": "ir", "front": "Washington consensus", "back": "Is a set of 10 economic policy prescriptions considered to constitute the \"standard\" reform package promoted for crisis-wracked developing countries by Washington, D.C.–based institutions such as the International Monetary Fund (IMF), World Bank, and the US Treasury Department. The term was first used in 1989. It sought to reduce intervention in the market through measures of deregulation,privatization, fiscal constraints."}, {"id": "g114", "topic": "concepts", "front": "Decentralization", "back": "The expansion of local autonomy through the transfer of powers and responsibilities away from national bodies. You may remember participation, responsiveness, legitimacy and liberty as keywords to explain this phenomenon."}, {"id": "g115", "topic": "concepts", "front": "Centralization", "back": "Is associated with national unity, uniformity, equality (of regions and people within these regions), prosperity (sustainable growth and development)."}, {"id": "g116", "topic": "concepts", "front": "Confederation", "back": "A qualified union of states in which each state retains its independence, typically guaranteed by unanimous decision-making.", "mcq": {"stem": "Which term is defined as: \"A qualified union of states in which each state retains its independence, typically guaranteed by unanimous decision-making.\"", "options": ["Coalition", "Positive rights", "Neoconservatism", "Confederation"], "answer": 3, "why": "Confederation — A qualified union of states in which each state retains its independence, typically guaranteed by unanimous decision-making."}}, {"id": "g117", "topic": "concepts", "front": "Unitary systems", "back": "Which vest sovereign power in a single, national institution.", "mcq": {"stem": "Which term is defined as: \"Which vest sovereign power in a single, national institution.\"", "options": ["Separation of power", "Feudalism", "Semi-democracy", "Unitary systems"], "answer": 3, "why": "Unitary systems — Which vest sovereign power in a single, national institution."}}, {"id": "g118", "topic": "concepts", "front": "Communitarianism", "back": "The self or person is constituted through the community, in the sense that individuals are shaped by the communities to which they belong and thus owe them a debt of respect and consideration.", "mcq": {"stem": "Which term is defined as: \"The self or person is constituted through the community, in the sense that individuals are shaped by the communities to which they belong and thus owe them a debt of respect and consideration.\"", "options": ["Rule of law", "Blank check", "Minimal state", "Communitarianism"], "answer": 3, "why": "Communitarianism — The self or person is constituted through the community, in the sense that individuals are shaped by the communities to which they belong and thus owe them a debt of respect and consideration."}}, {"id": "g119", "topic": "concepts", "front": "State socialism", "back": "A form of socialism in which the state controls and directs economic life, acting, in theory, in the interests of the people."}, {"id": "g120", "topic": "concepts", "front": "Social capital", "back": "Capital refers to assets that are used in the production of goods and services. Social capital refers to cultural and moral resources that help to promote social cohesion, political stability and prosperity. We imply social connectiveness with this word and networks, norms and trust promote such a civic engagement in the society. Education and active citizenship affect social capital in a society.The rise of individualism and the increase in social and geographical mobility today argued as the cause of the decline of social capital.", "mcq": {"stem": "Which term is defined as: \"____ refers to assets that are used in the production of goods and services. ____ refers to cultural and moral resources that help to promote ____ cohesion, political stability and prosperity. We imply ____ connec\"", "options": ["Marxism (in IR theory)", "Plurality voting system", "Social capital", "Legitimacy"], "answer": 2, "why": "Social capital — Capital refers to assets that are used in the production of goods and services. Social capital refers to cultural and moral resources that help to promote social cohesion, political stability and pros"}}, {"id": "g121", "topic": "concepts", "front": "Monetarism", "back": "A shift in economic priorities from the reduction of unemployment to control of inflation. Government job is squeezing inflation out of the system and growth, employment, and productivity should be left to market.", "mcq": {"stem": "Which term is defined as: \"A shift in economic priorities from the reduction of unemployment to control of inflation. Government job is squeezing inflation out of the system and growth, employment, and productivity should be left to market.\"", "options": ["Idealism", "Plurality voting system", "Totalitarian state", "Monetarism"], "answer": 3, "why": "Monetarism — A shift in economic priorities from the reduction of unemployment to control of inflation. Government job is squeezing inflation out of the system and growth, employment, and productivity should be le"}}, {"id": "g122", "topic": "concepts", "front": "Fordism and post-Fordism", "back": "Are terms that are used to explain the economic, political and cultural transformation of modern society by reference to the changing form and organization of production. Fordism refers to large-scale mass production which relies on mechanization and highly specialized production-line. So, standardized and relatively cheap products can be produced. Post-Fordism: the idea that modern industrial production has moved away from mass production in huge factories, as pioneered by Henry Ford, towards specialized markets based on small flexible manufacturing units"}, {"id": "g123", "topic": "concepts", "front": "Postmaterialism", "back": "From a materialistic perception of world economy (which conceives the world as scarcity of resources) the realm of economy start to rule the sphere of politics. Postmaterialism implies that in the conditions of widespread prosperity individuals express more interest in quality of life issues which can be associated with morality, political justice, and personal fulfilment.", "mcq": {"stem": "Which term is defined as: \"From a materialistic perception of world economy (which conceives the world as scarcity of resources) the realm of economy start to rule the sphere of politics. ____ implies that in the conditions of widespread prosperi\"", "options": ["Unitary systems", "Economic liberalism", "Postmaterialism", "Unilateralism"], "answer": 2, "why": "Postmaterialism — From a materialistic perception of world economy (which conceives the world as scarcity of resources) the realm of economy start to rule the sphere of politics. Postmaterialism implies that in the con"}}, {"id": "g124", "topic": "concepts", "front": "Identity", "back": "A sense of separate and unique selfhoof, but it also acknowledges that how people see themselves is shaped by a web of social and other relationships that distinguish them from other people."}, {"id": "g125", "topic": "concepts", "front": "Multiculturalism", "back": "A positive endorsement of communal diversity, based on the right of different cultural groups to respect and recognition. In addition to that it can be seen as a moral position in the society.", "mcq": {"stem": "Which term is defined as: \"A positive endorsement of communal diversity, based on the right of different cultural groups to respect and recognition. In addition to that it can be seen as a moral position in the society.\"", "options": ["Social-democratic state", "Conservatism", "Structure and agency", "Multiculturalism"], "answer": 3, "why": "Multiculturalism — A positive endorsement of communal diversity, based on the right of different cultural groups to respect and recognition. In addition to that it can be seen as a moral position in the society."}}, {"id": "g126", "topic": "concepts", "front": "Legitimacy", "back": "Rightfulness. For instance transforming power to authority in a society. It gives binding and authoritative character.", "mcq": {"stem": "Which term is defined as: \"Rightfulness. For instance transforming power to authority in a society. It gives binding and authoritative character.\"", "options": ["Postmaterialism", "Minimal state", "Legitimacy", "Social-democratic state"], "answer": 2, "why": "Legitimacy — Rightfulness. For instance transforming power to authority in a society. It gives binding and authoritative character."}}, {"id": "g127", "topic": "methods", "front": "Systems theory", "back": "The theory that treats the political system as a self-regulating mechanism responding to inputs (demands&supports) by issuing authoritative decisions or outputs (policies)."}, {"id": "g128", "topic": "concepts", "front": "Propaganda", "back": "Disseminated in a deliberate and systematic attempt to shape opinions and possibly stimulate political action."}, {"id": "g129", "topic": "concepts", "front": "Public interest", "back": "The general or collective interests of a community: that is, which is good for society as a whole."}, {"id": "g130", "topic": "concepts", "front": "Partisan dealignment", "back": "Decline in the extent to which people align themselves with a party identifying with it. May lead decline of old parties and rise of new ones.", "mcq": {"stem": "Which term is defined as: \"Decline in the extent to which people align themselves with a party identifying with it. May lead decline of old parties and rise of new ones.\"", "options": ["Imperialism", "Theocracy", "Partisan dealignment", "Modern liberalism"], "answer": 2, "why": "Partisan dealignment — Decline in the extent to which people align themselves with a party identifying with it. May lead decline of old parties and rise of new ones."}}, {"id": "g131", "topic": "concepts", "front": "Class dealignment", "back": "The weakening of the relationship between social class and party support."}, {"id": "g132", "topic": "concepts", "front": "Issue voting", "back": "Voting behavior that is shaped by party policies and a calculation of personal self-interest.", "mcq": {"stem": "Which term is defined as: \"____ behavior that is shaped by party policies and a calculation of personal self-interest.\"", "options": ["Legitimacy", "Partisan dealignment", "Liberal democracy", "Issue voting"], "answer": 3, "why": "Issue voting — Voting behavior that is shaped by party policies and a calculation of personal self-interest."}}, {"id": "g133", "topic": "concepts", "front": "Political party", "back": "Is a group of people that is organized for the purpose of winning government power, by electoral or other means."}, {"id": "g134", "topic": "concepts", "front": "Party democracy", "back": "Is a form of popular rule that operates through the agency of a party as a democratic institution."}, {"id": "g135", "topic": "concepts", "front": "One-party systems", "back": "This system has been found in state socialist regimes where “ruling” communist parties have directed and controlled virtually all the institutions and aspects of the society. Strict ideological discipline, structured internal organizations, well-paid party officials, supervision over both the state machine and social institutions."}, {"id": "g136", "topic": "concepts", "front": "Two-party systems", "back": "A duopolistic system. It is dominated by two major parties that have a roughly equal prospect of winning government power."}, {"id": "g137", "topic": "concepts", "front": "Coalition", "back": "A grouping of rival political actors brought together either through the perception of a common threat, or through the recognition that their goals cannot be achieved by working separately.", "mcq": {"stem": "Which term is defined as: \"A grouping of rival political actors brought together either through the perception of a common threat, or through the recognition that their goals cannot be achieved by working separately.\"", "options": ["Night-watchman State", "Liberalism", "Coalition", "State"], "answer": 2, "why": "Coalition — A grouping of rival political actors brought together either through the perception of a common threat, or through the recognition that their goals cannot be achieved by working separately."}}, {"id": "g138", "topic": "concepts", "front": "Constitution", "back": "A set of rules, written and unwritten, that seek to establish the duties, powers and functions of the various institutions of government, regulate the relationships between them, and define the relationship between the state and the individual."}, {"id": "g139", "topic": "concepts", "front": "Elective dictatorship", "back": "A constitutional imbalance in which executive power is checked only by the need to win subsequent elections.", "mcq": {"stem": "Which term is defined as: \"A constitutional imbalance in which executive power is checked only by the need to win subsequent elections.\"", "options": ["Estrangement", "Disciplinary power", "Elective dictatorship", "Governance"], "answer": 2, "why": "Elective dictatorship — A constitutional imbalance in which executive power is checked only by the need to win subsequent elections."}}, {"id": "g140", "topic": "concepts", "front": "Negative rights", "back": "Mark out realm of unconstrained action, and thus check the responsibilities of government (freedom of expression, freedom of religious worship, freedom of movement etc)", "mcq": {"stem": "Which term is defined as: \"Mark out realm of unconstrained action, and thus check the responsibilities of government (freedom of expression, freedom of religious worship, freedom of movement etc)\"", "options": ["Multipolarity", "Negative rights", "Authority", "Federalism"], "answer": 1, "why": "Negative rights — Mark out realm of unconstrained action, and thus check the responsibilities of government (freedom of expression, freedom of religious worship, freedom of movement etc)"}}, {"id": "g141", "topic": "concepts", "front": "Positive rights", "back": "Rights that make demands of government in terms of provision of resources and support and thus extend its responsibilities (right to healthcare, right to education, social and cultural rights etc)", "mcq": {"stem": "Which term is defined as: \"____ that make demands of government in terms of provision of resources and support and thus extend its responsibilities (right to healthcare, right to education, social and cultural ____ etc)\"", "options": ["Government gridlock", "Historical materialism", "Positive rights", "Semi-democracy"], "answer": 2, "why": "Positive rights — Rights that make demands of government in terms of provision of resources and support and thus extend its responsibilities (right to healthcare, right to education, social and cultural rights etc)"}}, {"id": "g142", "topic": "concepts", "front": "Rule of law", "back": "The principle that the law should “rule” in the sense that it establishes a framework to which all conduct and behavior conform, applying equally to all the members of society, be they private citizens or government officials. To implement this idea you need limited government and constitutionalism in your country.", "mcq": {"stem": "Which term is defined as: \"The principle that the law should “____” in the sense that it establishes a framework to which all conduct and behavior conform, applying equally to all the members of society, be they private citizens or government officials. To \"", "options": ["Historical materialism", "State of nature", "Communitarianism", "Rule of law"], "answer": 3, "why": "Rule of law — The principle that the law should “rule” in the sense that it establishes a framework to which all conduct and behavior conform, applying equally to all the members of society, be they private citizen"}}, {"id": "g143", "topic": "concepts", "front": "Libertarianism", "back": "The belief that the realm of individual liberty should be maximized, usually associated with attempts to minimize the scope of public authority."}, {"id": "g144", "topic": "concepts", "front": "Presidential government", "back": "Is characterized by a constitutional and political separation of powers between the legislative and executive branches of government. Executive power is thus vested in an independently elected president who is not directly accountable to or removable by the assembly."}, {"id": "hc1", "topic": "summaries", "front": "Heywood Ch.1 — What is political theory?", "back": "The book takes a problem-focused, conceptual approach: concepts are treated as responses to the political debates and problems of their contexts. Each chapter is organized around a structuring problem, and chapters follow a roughly chronological logic from early modern to contemporary, with new issues arising atop older, often unresolved ones. The material is organized into three parts: the foundations of modern Western political theory; modern political problems; and twentieth/twenty-first-century problems of exclusion. Each chapter is standalone; cross-references and boxed features support independent learning, which the authors call the true task of every political theorist.\n\nKey points:\n• Problem-focused, conceptual approach — concepts as responses to their contexts\n• Chapters ordered chronologically, each built around a structuring problem\n• Three parts: foundations, modern problems, problems of exclusion\n• Standalone chapters; boxes support independent learning"}, {"id": "hc2", "topic": "summaries", "front": "Heywood Ch.2 — Political change: progress, tradition and utopia", "back": "Political change is central to modern thought because in modernity human argument and action become the grounds of political justification. Theorists face descriptive tasks (understanding change), normative tasks (justifying or critiquing it) and a methodological question of self-positioning. Progress is the dominant theme, supplying criteria of rationality and development but not prescribing reform versus revolution. Tradition locates authority in the past and leans toward critique, appearing beyond conservatism in liberalism, socialism, postcolonialism and multiculturalism. Utopia grounds critique in an imagined future; in practice the three are blended as tools, not blueprints.\n\nKey points:\n• Modernity makes human argument/action the ground of justification\n• Progress = dominant theme (rationality, development), silent on reform vs revolution\n• Tradition = authority in the past, beyond just conservatism\n• Utopia = critique via an imagined future; the three blend in practice"}, {"id": "hc3", "topic": "summaries", "front": "Heywood Ch.3 — Human nature: the individual and society", "back": "Human nature is widely criticized yet unavoidable: every political theory presupposes some view of humanity, individuals and groups. Conceptions concern the drives that motivate us (reason, emotion, instinct), how far we change (essence vs evolution) and the dynamics of group life (competition, cooperation, conflict). Contemporary debates repackage human nature under headings like moral psychology, ontology, capacities, rational actors and affect. Parekh notes views range across thick/formal, teleological/mechanistic, determining/disposing and inclusive/distinctive. Debates remain unavoidable and often at cross purposes.\n\nKey points:\n• Criticized but unavoidable — all theory presupposes a view of humanity\n• Covers drives, the extent of change, and group dynamics\n• Repackaged as moral psychology, ontology, capacities, rational actors\n• Parekh: thick/formal, teleological/mechanistic, determining/disposing"}, {"id": "hc4", "topic": "summaries", "front": "Heywood Ch.4 — Power: authority and legitimacy", "back": "Anglo-American political science favours one- and two-dimensional views of power (decision-making, agenda-setting) that can be operationalized empirically, casting power as relational domination. The liberal tradition treats power as coercive and institutionally localized, assuming rather than investigating it — exceptions are critical and post-structuralist thinkers using the third (preference manipulation) and fourth (productive) dimensions. Authority debates repeat this model, with Weber's typology influential, and theorists focus on when authority is justified. Legitimacy is the most central concept for contemporary debate; whether grounded in consent or manufactured by ideology, it is essential to maintaining any system of rule.\n\nKey points:\n• 1st/2nd dimensions (decision, agenda) dominate because they are measurable\n• 3rd (preference manipulation) and 4th (productive) come from critical/post-structuralist thought\n• Weber's typology frames the authority debate\n• Legitimacy — by consent or ideology — is essential to any rule"}, {"id": "hc5", "topic": "summaries", "front": "Heywood Ch.5 — Politics: the state and sovereignty", "back": "How to define 'politics' is itself contested: usages span government, public affairs, and power/conflict, each reflecting a different tradition. From these flow competing theories of the state — classical (absolutist, liberal constitutional, Marxist, anarchist) and twentieth-century (elitist, pluralist, neoliberal, governance). These in turn produce contested views of sovereignty, focused overwhelmingly on the nature and shape of legitimate sovereignty. This persistent contestation, then and now, reveals something important about political theory itself.\n\nKey points:\n• 'Politics' = government / public affairs / power & conflict\n• State theory: classical (absolutist, liberal, Marxist, anarchist) → 20th-c (elitist, pluralist, neoliberal, governance)\n• Sovereignty debates centre on legitimate sovereignty\n• Persistent contestation is itself revealing"}, {"id": "hc6", "topic": "summaries", "front": "Heywood Ch.6 — Law: order and obligation", "back": "Law, order and obligation are foundational, interconnected issues that pull political thought into dialogue with legal theory and rest ultimately on assumptions about human nature (Rawls's 'basic institutions'). Law has become less central in modern normative theory, as the rule of law is relatively settled and debates over law's nature migrated into legal theory. Two concerns persist: critical/post-structuralist accounts (Derrida — law's unstable relation to justice), and normative justification of particular frameworks (intellectual property, environmental regulation, women's rights). Since Rawls's A Theory of Justice, justice has become central to liberal thought, though challenged by critics and by liberal 'realists' such as Williams and Geuss.\n\nKey points:\n• Foundational, circular debates resting on human-nature assumptions\n• Law less central; rule of law settled, debates moved to legal theory\n• Derrida: law's unstable relation to justice\n• Since Rawls, justice is central — contested by Williams, Geuss"}, {"id": "hc7", "topic": "summaries", "front": "Heywood Ch.7 — Citizenship: freedom and rights", "back": "Citizenship — the proper relationship between individual and state — has been shaped by the liberal and republican traditions, making citizenship theory individualistic and formal, taking freedom as its ideal and centring on the nature and extent of rights. Freedom is itself contested even within liberalism, and these divisions recur in debates over rights. New contexts — expanded entitlements, the impact of rights on diversity and minorities, animals as members of political communities — further complicate matters. Contemporary debates remain live and connect to democracy, political community and exclusion.\n\nKey points:\n• Liberal/republican roots → individualistic, formal, freedom-centred citizenship\n• Freedom is contested within liberalism; recurs in rights debates\n• New contexts: entitlements, minorities, animals\n• Links to democracy, community and exclusion"}, {"id": "hc8", "topic": "summaries", "front": "Heywood Ch.8 — Democracy: representation and participation", "back": "Representation and the possibility of a public good have generated a rich field tightly linked to empirical political science. Recent decades are dominated by deliberative theory and, less so, radical democratic critiques of it, alongside ongoing liberal-democratic debate. Instability in Western liberal democracies has made populism a live (and definitionally contested) topic, and 'democratic scepticism' has revived classical worries about voter competence and willingness. Over the long run Western democratic theory is cyclical, swinging between advocates of fuller direct participation and sceptics favouring elite, expert government.\n\nKey points:\n• Deliberative theory dominates; radical democracy critiques it\n• Populism is live but its meaning is disputed\n• 'Democratic scepticism' revives doubts about voter competence\n• Theory is cyclical: participation vs elite/expert rule"}, {"id": "hc9", "topic": "summaries", "front": "Heywood Ch.9 — Political community: toleration, nationalism, cosmopolitanism", "back": "The problem of political community concerns how political institutions constitute a community and relate its members. The debate has passed through phases but not as progressive replacement — toleration, nationalism and cosmopolitanism all persist as live positions. Toleration was an early, individualistic liberal framing that confined the political community to non-private affairs. The nation later dominated, raising questions about what a nation is and whether it is compatible with liberalism, diversity and the international world. Globalization and transnationalism raise the possibility of a global, cosmopolitan community beyond the nation.\n\nKey points:\n• Toleration, nationalism, cosmopolitanism coexist (not stages)\n• Toleration: early individualistic liberal framing\n• Nation: compatibility with liberalism, diversity, the international order\n• Cosmopolitanism: community beyond the nation"}, {"id": "hc10", "topic": "summaries", "front": "Heywood Ch.10 — Property: planning and the market", "back": "The problem of property concerns how ownership is organized and extends to exchange, production and consumption within an economic system. Though rooted in early modern thought, property debates remained central through the nineteenth–twenty-first centuries, and deep concerns about inequality persist even amid globally dominant capitalism. Agreement tends to hold within traditions; the deepest disputes are between traditions — liberalism and conservatism versus Marxism, anarchism and socialism. Within traditions, Marxists/socialists analyzed changing global capitalism and engaged Frankfurt critical theory and post-structuralism, while twentieth-century liberalism split classical from modern liberals over limiting market tendencies — divisions between neo-liberals and egalitarian liberals that continue today.\n\nKey points:\n• Property = ownership + exchange/production/consumption\n• Deepest disputes are between traditions (liberal/conservative vs Marxist/anarchist/socialist)\n• Marxists engage Frankfurt theory and post-structuralism\n• Neo-liberal vs egalitarian-liberal divide persists"}, {"id": "hc11", "topic": "summaries", "front": "Heywood Ch.11 — Equality: social justice and welfare", "back": "Equality is central to modern thought. Many thinkers (Rousseau, socialists, Marxists, critical theorists) locate inequality in private property, revealing a divide: critical thinkers tie property to inequality to justify deep equality of outcome and demanding theories of social justice, while liberal and conservative traditions favour forms of equality requiring little redistribution. Egalitarianism became central to late-nineteenth/twentieth-century thought despite ideological divisions — social democrats and modern liberals justified the welfare state, classical liberals and conservatives resisted it, socialists and Marxists critiqued capitalism, often in parallel. Welfare's centrality has declined, but debates over conceiving and distributing equality remain central (e.g. Scanlon), and critical attention has shifted since the 1970s toward identity and recognition (e.g. Piketty on new inequalities).\n\nKey points:\n• Critical thinkers link property to inequality → equality of outcome\n• Liberals/conservatives favour low-redistribution equality\n• Welfare state: justified by social democrats/modern liberals, resisted by classical liberals/conservatives\n• Since the 1970s, shift toward identity and recognition"}, {"id": "hc12", "topic": "summaries", "front": "Heywood Ch.12 — Exclusion I: recognition and gender", "back": "This chapter frames sociopolitical exclusion through recognition and identity, applied to gender and culture (race/colonialism go to Ch.13). Since the 1970s a politics of recognition has emerged that treats the exclusion of identity as a deep harm and challenges universal liberal-democratic citizenship — Taylor's politics of equal respect — drawing critique from rights-based and redistributive theory that sees recognition as inhibiting egalitarianism. In gender debates, feminist theory used 'gender' to expose the sociocultural dimensions of women's oppression, while the sex/gender distinction raised questions of strategy (equality vs difference) and of the concept of woman. In culture, the exclusion of minorities by the supposedly neutral liberal state prompted liberal multiculturalism (fair integration, self-government), itself deeply criticized, including by feminism.\n\nKey points:\n• Politics of recognition: exclusion of identity as deep harm (Taylor)\n• Critique: recognition may inhibit egalitarian redistribution\n• Gender exposes sociocultural oppression; equality-vs-difference strategy\n• Liberal multiculturalism prescribes integration/self-government, but is criticized"}, {"id": "hc13", "topic": "summaries", "front": "Heywood Ch.13 — Exclusion II: race and colonialism", "back": "Race and colonialism pose among the most fundamental challenges to political theory and to Western liberal-democratic states, which legitimized themselves through gradual inclusion while struggling to unite a diverse citizenry. Race raises the prospect of an exclusion so systematic that the present system may be incapable of sufficient change — perhaps explaining the discipline's continuing neglect of it — while colonialism, intersecting with racialization, challenges the very legitimacy of the Western community through the refusal of Indigenous peoples. Recurring tensions: whether recognition is adequate for group difference, and how to weigh past and ongoing structural oppression for present forms of inclusion we value. The chapter scrutinizes liberalism and Western thought itself, asking whether modernity has a fundamental problem with difference, and calls for a reappraisal of the modern Western project.\n\nKey points:\n• Race: exclusion possibly too systematic for the system to fix\n• Colonialism + Indigenous refusal challenge Western legitimacy\n• Is 'recognition' adequate for group difference?\n• Deep scrutiny of liberalism and the modern Western project"}, {"front": "IR theory as 'lenses' — the three-part spectrum", "back": "Theories of IR are different lenses on the same world. McGlinchey & Gold map them on a spectrum: TRADITIONAL (realism, liberalism), MIDDLE-GROUND (English School, constructivism) and CRITICAL (Marxism, postcolonialism, feminism, poststructuralism). Kuhn's 'paradigm shift' explains how dominant theories are replaced when they stop fitting the world.", "id": "p1", "topic": "ir"}, {"front": "Liberalism (IR)", "back": "Optimistic, once called 'utopian'. Views humans as innately good; peace and harmony between nations are achievable and desirable. Kant: states sharing liberal values have no reason to war, and citizens (unlike kings) rarely want war → the more liberal states, the more peace → democratic peace theory. Wilson's Fourteen Points → the League of Nations. State is the dominant actor but international organisations matter and help formalise cooperation.", "mcq": {"stem": "Which best captures the liberal view of international organisations?", "options": ["They help states cooperate and find alternatives to war through trade and diplomacy", "They matter only when they serve the interests of powerful states", "They are band-aids legitimising state-led exploitation", "They are arbitrary power structures to be deconstructed"], "answer": 0, "why": "Liberals have faith in IOs (UN, IMF, WHO, World Bank) to uphold global governance. The other options are the realist, Marxist and poststructuralist views respectively."}, "id": "p2", "topic": "ir"}, {"front": "Realism (IR)", "back": "Pessimistic; claims to reflect the 'reality' of world politics. Humans are self-interested and selfish; with no world sovereign and no international social contract, the system is one of 'international anarchy' → fear and disorder, so war is common and even inevitable. Morgenthau: 'all politics is a struggle for power' — politics is about domination, not cooperation. State-centric; security and survival are paramount; states join international organisations only when it serves their self-interest. (Hobbes's 'state of nature' is the backdrop.)", "mcq": {"stem": "Why are realists pessimistic about international relations?", "options": ["In an anarchic system with no world sovereign, a state can ultimately rely only on itself for security", "Because shared norms bind states into an international society", "Because language constructs the 'truths' states take for granted", "Because the bourgeoisie controls all international institutions"], "answer": 0, "why": "Realists stress anarchy and the state's need for self-reliant security; periods of peace are just preparation for future conflict."}, "id": "p3", "topic": "ir"}, {"front": "Realism vs Liberalism — the core contrast", "back": "Human nature: realists see people as selfish, liberals as innately good. Mood: realists pessimistic (domination), liberals optimistic (cooperation, progress). Both treat the state as the dominant actor, but liberalism adds a role for non-state actors/IOs. There is no single realist or liberal theory; both have modern updates — neorealism and neoliberalism — that shift emphasis from their traditional roots.", "mcq": {"stem": "A key difference between realism and liberalism is their view of…", "options": ["human nature — selfish (realism) vs innately good (liberalism)", "whether the state exists at all", "whether anarchy is socially constructed", "whether class is the basis of world politics"], "answer": 0, "why": "The human-nature contrast (selfish vs good) underlies the optimism/pessimism and domination/cooperation split."}, "id": "p4", "topic": "ir"}, {"front": "English School (middle ground)", "back": "A middle ground between realism and liberalism: the idea of a 'society of states' at the international level. Hedley Bull agreed the system is anarchic but insisted this does NOT mean there are no norms — states form an 'Anarchical Society' (1977) where order exists through shared norms and behaviours. Hence the 'international society' approach: not quite realist, not quite liberal.", "mcq": {"stem": "The English School describes the international system as…", "options": ["anarchic but bound by shared norms — an 'anarchical society'", "a pure struggle for power with no order", "a class system run by the bourgeoisie", "a social construction with no fixed features"], "answer": 0, "why": "Bull: anarchy + norms = an anarchical society; order without a world government."}, "id": "p5", "topic": "ir"}, {"front": "Constructivism (middle ground)", "back": "Sits between mainstream and critical theories. Ideas and 'norms' have power. Wendt: 'anarchy is what states make of it' — agents and structures co-constitute each other (structures don't just constrain agents, they construct their identities and interests). States don't interact; their agents (politicians, diplomats) do. Because anarchy is accepted, it became our reality — but if enough actors accepted a different idea, anarchy's qualities could change or be replaced.", "mcq": {"stem": "Which phrase captures the core of constructivism?", "options": ["'Anarchy is what states make of it'", "'All politics is a struggle for power'", "'The highest stage of capitalism'", "'A war of all against all'"], "answer": 0, "why": "Wendt's phrase encapsulates that anarchy is socially constructed and changeable, not a fixed fact."}, "id": "p6", "topic": "ir"}, {"front": "Critical theories (overview)", "back": "A wide spectrum (Marxism, postcolonialism, feminism, poststructuralism) established in response to the mainstream (realism, liberalism). Their shared trait: they OPPOSE assumptions that have been central to IR since its founding, and they give voice to positions and people typically ignored — especially women and those from the Global South.", "id": "p7", "topic": "ir"}, {"front": "Marxism (IR critical theory)", "back": "Based on Marx: society is split into the bourgeoisie (business class) and the proletariat (workers), who are at the mercy of those controlling their wages. In IR, the internationalisation of the state has divided and alienated ordinary people instead of uniting them as a global proletariat. To change this, the legitimacy of the state must be questioned and ultimately dissolved — emancipation from the state is part of the critical agenda.", "mcq": {"stem": "How would a Marxist read an international body like the UN?", "options": ["As an institution that ultimately serves the interests of the business class / imperial powers", "As a neutral forum where new norms emerge", "As a guarantor of global governance and peace", "As a society of states bound by shared norms"], "answer": 0, "why": "Marxists see the UN as built by and for capitalist/imperial states — humanitarian acts are band-aids over state-led exploitation."}, "id": "p8", "topic": "ir"}, {"front": "Postcolonialism (IR critical theory)", "back": "Focuses on inequality between NATIONS or regions (rather than classes). The effects of colonialism and European imperialism persist; its origins trace to Cold War decolonisation. Said's 'Orientalism' (1978) showed how the Middle East and Asia were inaccurately depicted by the West. Postcolonialism insists on including Global South voices so Western scholars no longer speak on their behalf.", "mcq": {"stem": "What distinguishes postcolonialism from Marxism in IR?", "options": ["It centres inequality between nations/regions rather than between classes", "It denies that colonialism still matters", "It treats the state as a social construction", "It focuses on gender as the prime object of analysis"], "answer": 0, "why": "Postcolonialism = inequality among nations/regions and the legacies of imperialism; Marxism = class."}, "id": "p9", "topic": "ir"}, {"front": "Feminism (IR critical theory)", "back": "Entered IR in the 1980s. Asks why so few women hold power and what that implies for how global politics is structured — a 'gendered' reading that makes gender the prime object of focus. Gender is a social construction permeating all of society; once recognised, its challenges can be confronted. (Spike Peterson: as long as gender stays 'invisible', it is unclear what 'taking gender seriously' means.) Overlaps with constructivism.", "mcq": {"stem": "A feminist analysis of the UN would emphasise…", "options": ["how decision-making perpetuates a masculine discourse and under-represents women", "the absence of African and Latin American permanent members", "that the UN serves the global business class", "that anarchy is what states make of it"], "answer": 0, "why": "Feminists highlight male-dominated decision-making and the marginalised feminine voice (the postcolonial point about permanent members is a different lens)."}, "id": "p10", "topic": "ir"}, {"front": "Poststructuralism (IR critical theory)", "back": "The most controversial critical approach: it questions the very 'truths' we take as real — above all the state, and the nature of power. Realists and liberals both take the state for granted as a 'structure'; poststructuralism asks why the state exists and for whom. Derrida's deconstruction of language exposes hidden meanings and the power within texts — apply it to ideas like the state and you can move beyond them.", "mcq": {"stem": "Poststructuralism is best described as an approach that…", "options": ["questions taken-for-granted 'truths' (like the state) by deconstructing language and power", "builds world order on shared liberal values", "explains war through human selfishness and anarchy", "analyses inequality between core and peripheral nations"], "answer": 0, "why": "Poststructuralism destabilises foundational assumptions and exposes the power in language/discourse."}, "id": "p11", "topic": "ir"}, {"front": "Democratic peace theory", "back": "The (Kantian) claim that democracies do not go to war with one another — because liberal states are ruled by their citizens, who are rarely disposed to want war. A modern development of liberalism in IR.", "mcq": {"stem": "Democratic peace theory holds that…", "options": ["democracies do not go to war with one another", "democracies are more warlike than autocracies", "anarchy forces all states toward war", "international organisations cause conflict"], "answer": 0, "why": "Democratic peace theory: shared liberal/democratic values remove the reason for war between democracies."}, "id": "p12", "topic": "ir"}, {"front": "The UN Security Council — structure & critique", "back": "The UN's General Assembly gives every state a seat, but real power sits in the Security Council: 5 permanent members (US, Russia, China, France, UK — the WWII victors of 1945) each with a VETO, plus 10 elected non-permanent members. The UN is often called a 'peacekeeper' not a 'peacemaker' (peacekeepers usually use force only in self-defence). Postcolonial critique: no African or Latin American permanent member, and former colonial powers' veto perpetuates indirect domination of the Global South.", "mcq": {"stem": "A postcolonial critique of the UN Security Council points to…", "options": ["the lack of African or Latin American permanent members and former colonial powers holding the veto", "its inability to enforce free trade", "that anarchy is socially constructed", "the masculine discourse of its officials"], "answer": 0, "why": "Postcolonialists stress unequal representation and continued colonial-power dominance (the masculine-discourse point is the feminist lens)."}, "id": "p13", "topic": "ir"}, {"front": "The UN through each lens (application)", "back": "Liberals: faith in IOs (UN, IMF, WHO, World Bank) to uphold global governance — better than chaos. Realists: anarchy rules, IOs have little authority and succeed only when serving powerful states (used to explain the League's failure over Germany/Japan, and the US ignoring the Council to invade Iraq in 2003). Constructivists: the UN is where new norms emerge — even un-punished norm violations (Iraq 2003) carry consequences. Marxists: it serves the business/imperial class. Feminists: it perpetuates masculine discourse. Postcolonialists: its make-up privileges former colonial powers.", "id": "p14", "topic": "ir"}, {"id": "hk1", "topic": "keyconcepts", "front": "Authority", "back": "Authority can most simply be defined as ‘legitimate power’. Whereas power is the ability to influence the behaviour of others, authority is the right to do so. Authority is therefore based on an acknowledged duty to obey rather than on any form of coercion or manipulation. In this sense, authority is power cloaked in legitimacy or rightfulness. Weber (see p. 81) distinguished between three kinds of authority, based on the different grounds on which obedience can be established: traditional authority is rooted in history; charismatic authority stems from personality; and legal–rational authority is grounded in a set of impersonal rules."}, {"id": "hk2", "topic": "keyconcepts", "front": "Power", "back": "Power, in its broadest sense, is the ability to achieve a desired outcome, sometimes seen as the ‘power to’ do something. This includes everything from the ability to keep oneself alive to the ability of government to promote economic growth. In politics, however, power is usually thought of as a relationship; that is, as the ability to influence the behaviour of others in a manner not of their choosing. This implies having ‘power over’ people. More narrowly, power may be associated with the ability to punish or reward, bringing it close to force or manipulation, in contrast to ‘influence’. (See ‘faces’ of power, p. 9 and dimensions of global"}, {"id": "hk3", "topic": "keyconcepts", "front": "Civil society", "back": "Civil society originally meant a ‘political community’. The term is now more commonly distinguished from the state, and is used to describe institutions that are ‘private’, in that they are independent from government and organized by individuals in pursuit of their own ends. Civil society therefore refers to a realm of autonomous groups and associations: businesses, interest groups, clubs, families and so on. The term ‘global civil society’ (see p. 107) has become fashionable as a means of referring to non-governmental organizations (NGOs) (see p. 273) and transnational social movements (see p. 286)."}, {"id": "hk4", "topic": "keyconcepts", "front": "Consensus", "back": "Consensus means agreement, but it refers to an agreement of a particular kind. It implies, first, a broad agreement, the terms of which are accepted by a wide range of individuals or groups. Second, it implies an agreement about fundamental or underlying principles, as opposed to a precise or exact agreement. In other words, a consensus permits disagreement on matters of emphasis or detail. A procedural consensus is a willingness to make decisions through a process of consultation and bargaining. A substantive consensus is an overlap of ideological positions that reflect agreement about broad policy goals."}, {"id": "hk5", "topic": "keyconcepts", "front": "Science", "back": "Science is a field of study that aims to develop reliable explanations of phenomena through repeatable experiments, observation and deduction. The ‘scientific method’, by which hypotheses are verified (proved true) by testing them against the available evidence, is therefore seen as a means of disclosing value-free and objective truth. Karl Popper (1902–94), however, suggested that science can only falsify hypotheses, since ‘facts’ may always be disproved by later experiments."}, {"id": "hk6", "topic": "keyconcepts", "front": "Comparative politics", "back": "Comparative politics refers to both a disciplinary subfield and a method of analysis. As a disciplinary subfield, it is often taken, especially in the USA, to mean simply ‘the politics of foreign countries’. As a method of analysis, comparative politics involves identifying and exploring similarities and differences between political units (usually states) in order to develop ‘grounded theories’, test hypotheses, infer causal relationships, and produce reliable generalizations. The comparative method is sometimes seen as the most feasible technique for developing scientific knowledge of politics, in view of the practical difficulties of applying experimental techniques."}, {"id": "hk7", "topic": "keyconcepts", "front": "Constructivism", "back": "Constructivism (or social constructivism) is an approach to analysis that is based on the belief that there is no objective social or political reality independent of our understanding of it. Constructivists do not, therefore, regard the social world as something ‘out there’, in the sense of an external world of concrete objects; instead, it exists only ‘inside’, as a kind of intersubjective awareness. In the final analysis, people, whether acting as individuals or as social groups, ‘construct’ the world according to those constructions."}, {"id": "hk8", "topic": "keyconcepts", "front": "Postmodernism", "back": "Postmodernism is a term that was first used to describe experimental movements in Western arts, architecture and cultural development in general. As a tool of social and political analysis, postmodernism highlights the shift away from societies structured by industrialization and class solidarity to increasingly fragmented and pluralistic ‘information’ societies. In these, individuals are transformed from producers to consumers, and individualism replaces class, religious and ethnic loyalties. Postmodernists argue that there is no such thing as certainty; the idea of absolute and universal truth must be discarded as an arrogant pretence."}, {"id": "hk9", "topic": "keyconcepts", "front": "Ideal type", "back": "An ideal type (sometimes ‘pure type’) is a mental construct in which an attempt is made to draw out meaning from an otherwise almost infinitely complex reality through the presentation of a logical extreme. Ideal types were first used in economics, for instance, in the notion of perfect competition. Championed in the social sciences by Max Weber, ideal types are explanatory tools, not approximations of reality; they neither ‘exhaust reality’ nor offer an ethical ideal. Weberian examples include types of authority (see p. 4) and bureaucracy (see p. 374)."}, {"id": "hk10", "topic": "keyconcepts", "front": "Paradigm", "back": "A paradigm is, in a general sense, a pattern or model that highlights relevant features of a particular phenomenon. As used by Kuhn (1962), however, it refers to an intellectual framework comprising interrelated values, theories and assumptions, within which the search for knowledge is conducted. ‘Normal’ science is therefore conducted within the established paradigm, while ‘revolutionary’ science attempts to replace an old paradigm with a new one. The radical implication of this theory is that ‘truth’ and ‘falsehood’ are only provisional judgements.", "mcq": {"stem": "Which concept does Heywood define as: \"A ____ is, in a general sense, a pattern or model that highlights relevant features of a particular phenomenon. As used by Kuhn (1962), however, it refers to an intellectual framework comprising interrelated values, theories and assumpt\"", "options": ["New public management", "Social market", "Paradigm", "The state"], "answer": 2, "why": "Paradigm — A paradigm is, in a general sense, a pattern or model that highlights relevant features of a particular phenomenon. As used by Kuhn (1962), however, it refers to an intellectual framework comprising i"}}, {"id": "hk11", "topic": "keyconcepts", "front": "Ideology", "back": "From a social-scientific viewpoint, an ideology is a more or less coherent set of ideas that provides a basis for organized political action, whether this is intended to preserve, modify or overthrow the existing system of power relationships. All ideologies therefore (1) offer an account of the existing order, usually in the form of a ‘world-view’, (2) provide a model of a desired future, a vision of the Good Society, and (3) outline how political change can and should be brought about. Ideologies are not, however, hermetically sealed systems of thought; rather, they are fluid sets of ideas that overlap with one another at a number of points."}, {"id": "hk12", "topic": "keyconcepts", "front": "Third way", "back": "The term the third way encapsulates the idea of an alternative to both capitalism and socialism. Initially used by fascists, the term is now firmly linked to ‘new’ or modernized social democracy. In this context the third way is an alternative to old-style social democracy and neoliberalism. The former is rejected because it is wedded to statist structures that are inappropriate to the modern knowledge-based and market-orientated economy. The latter is rejected because it generates a free-for-all that undermines the moral foundations of society.", "mcq": {"stem": "Which concept does Heywood define as: \"The term the ____ encapsulates the idea of an alternative to both capitalism and socialism. Initially used by fascists, the term is now firmly linked to ‘new’ or modernized social democracy. In this context the ____ is an alternat\"", "options": ["Theocracy", "Policy network", "Devolution", "Third way"], "answer": 3, "why": "Third way — The term the third way encapsulates the idea of an alternative to both capitalism and socialism. Initially used by fascists, the term is now firmly linked to ‘new’ or modernized social democracy. In t"}}, {"id": "hk13", "topic": "keyconcepts", "front": "Sustainable development", "back": "Sustainable development refers to ‘development that meets the needs of the present without compromising the ability of future generations to meet their own needs’ (Brundtland Report (1987)). However, there are contrasting models of sustainable development. So-called ‘weak sustainability’ takes economic growth to be desirable but simply insists that growth levels must be limited to ensure that environmental costs do not threaten the prosperity of future generations. Strong sustainability rejects the pro-growth implications of weak sustainability, and focuses on the need to preserve ‘natural capital’.", "mcq": {"stem": "Which concept does Heywood define as: \"____ refers to ‘____ that meets the needs of the present without compromising the ability of future generations to meet their own needs’ (Brundtland Report (1987)). However, there are contrasting models of sustaina\"", "options": ["Sustainable development", "Multilateralism", "Failed state", "Postmaterialism"], "answer": 0, "why": "Sustainable development — Sustainable development refers to ‘development that meets the needs of the present without compromising the ability of future generations to meet their own needs’ (Brundtland Report (1987)). However, "}}, {"id": "hk14", "topic": "keyconcepts", "front": "Ecologism", "back": "Ecology (a term first used by Ernst Haeckel in 1873) is the study of the relationship between living organisms and their environment. It thus draws attention to the network of relationships that sustain all forms of life. Ecologism is a political doctrine or ideology that is constructed on the basis of ecological", "mcq": {"stem": "Which concept does Heywood define as: \"Ecology (a term first used by Ernst Haeckel in 1873) is the study of the relationship between living organisms and their environment. It thus draws attention to the network of relationships that sustain all forms of life. ____ is a pol\"", "options": ["Consensus", "Ecologism", "Athenian democracy", "Comparative politics"], "answer": 1, "why": "Ecologism — Ecology (a term first used by Ernst Haeckel in 1873) is the study of the relationship between living organisms and their environment. It thus draws attention to the network of relationships that susta"}}, {"id": "hk15", "topic": "keyconcepts", "front": "Fundamentalism", "back": "Fundamentalism refers to a style of thought in which certain principles are recognized as essential ‘truths’ which have authority. Substantive overriding and unchallengeable fundamentalisms have little or nothing in common, except that their supporters tend to evince an earnestness or fervour born out of doctrinal certainty. Although it is usually associated with religion and the literal truth of sacred texts, fundamentalism can also be found in political creeds. The term is controversial because it is often used pejoratively, to imply inflexibility, dogmatism and authoritarianism.", "mcq": {"stem": "Which concept does Heywood define as: \"____ refers to a style of thought in which certain principles are recognized as essential ‘truths’ which have authority. Substantive overriding and unchallengeable ____s have little or nothing in common, except that thei\"", "options": ["Neopluralism", "Interculturalism", "Ethnocentrism", "Fundamentalism"], "answer": 3, "why": "Fundamentalism — Fundamentalism refers to a style of thought in which certain principles are recognized as essential ‘truths’ which have authority. Substantive overriding and unchallengeable fundamentalisms have littl"}}, {"id": "hk16", "topic": "keyconcepts", "front": "Populism", "back": "Populism (from the Latin populus, meaning ‘the people’) has been used to describe both distinctive political movements and a particular tradition of political thought. Movements or parties described as populist have been characterized by their claim to support the common people in the face of ‘corrupt’ economic or political elites. As a political tradition, populism reflects the belief that the instincts and wishes of the people provide the principal legitimate guide to political action. Populist politicians, therefore, make a direct appeal to the people, and claim to give expression to their deepest hopes and fears.", "mcq": {"stem": "Which concept does Heywood define as: \"____ (from the Latin populus, meaning ‘the people’) has been used to describe both distinctive political movements and a particular tradition of political thought. Movements or parties described as populist have been characterized by th\"", "options": ["Athenian democracy", "Bureaucracy", "Parliamentary sovereignty", "Populism"], "answer": 3, "why": "Populism — Populism (from the Latin populus, meaning ‘the people’) has been used to describe both distinctive political movements and a particular tradition of political thought. Movements or parties described a"}}, {"id": "hk17", "topic": "keyconcepts", "front": "The state", "back": "The state is a political association that establishes sovereign jurisdiction within defined territorial borders, and exercises authority through a set of permanent institutions. These institutions are those that are recognizably ‘public’, in that they are responsible for the collective organization of communal life, and are funded at the public’s expense. The state thus embraces the various institutions of government, but it also extends to the courts, nationalized industries, social security system, and so forth; it can be identified with the entire ‘body politic’."}, {"id": "hk18", "topic": "keyconcepts", "front": "Neopluralism", "back": "Neopluralism is a style of social theorizing that remains faithful to pluralist values while recognizing the need to revise or update classical pluralism in the light of, for example, elite, Marxist and New Right theories. Although neopluralism embraces a broad range of perspectives and positions, certain central themes can be identified. First, it takes account of modernizing trends, such as the emergence of postindustrial society. Second, while capitalism is preferred to socialism, free-market economic doctrines are usually regarded as obsolete. Third, Western democracies are seen as ‘deformed polyarchies’, in which major corporations exert disproportionate influence.", "mcq": {"stem": "Which concept does Heywood define as: \"____ is a style of social theorizing that remains faithful to pluralist values while recognizing the need to revise or update classical pluralism in the light of, for example, elite, Marxist and New Right theories. Although neoplura\"", "options": ["Authoritarianism", "Transnational corporations", "Neopluralism", "Racialism, racism"], "answer": 2, "why": "Neopluralism — Neopluralism is a style of social theorizing that remains faithful to pluralist values while recognizing the need to revise or update classical pluralism in the light of, for example, elite, Marxist a"}}, {"id": "hk19", "topic": "keyconcepts", "front": "Neo-Marxism", "back": "Neo-Marxism (sometimes termed ‘modern’ or ‘Western’ Marxism) refers to attempts to revise or recast the classical ideas of Marx while remaining faithful to certain Marxist principles or aspects of Marxist methodology. Neo-Marxists typically refuse to accept that Marxism enjoys a monopoly of the truth, and have thus looked to Hegelian philosophy, anarchism, liberalism, feminism and even rational-choice theory. Although still concerned about social injustice, neo-Marxists reject the primacy of economics over other factors and, with it, the notion that history has a predictable character.", "mcq": {"stem": "Which concept does Heywood define as: \"____ (sometimes termed ‘modern’ or ‘Western’ Marxism) refers to attempts to revise or recast the classical ideas of Marx while remaining faithful to certain Marxist principles or aspects of Marxist methodology. Neo-Marxists typically\"", "options": ["Patriarchy", "Hegemony", "Neo-Marxism", "Elitism"], "answer": 2, "why": "Neo-Marxism — Neo-Marxism (sometimes termed ‘modern’ or ‘Western’ Marxism) refers to attempts to revise or recast the classical ideas of Marx while remaining faithful to certain Marxist principles or aspects of Mar"}}, {"id": "hk20", "topic": "keyconcepts", "front": "Patriarchy", "back": "Patriarchy literally means ‘rule by the father’, the domination of the husband–father within the family, and the subordination of his wife and his children. However, the term is usually used in the more general sense of ‘rule by men’, drawing attention to the totality of oppression and exploitation to which women are subject. Patriarchy thus implies that the system of male power in society at large both reflects and stems from the dominance of the father in the family. Patriarchy is a key concept in radical feminist analysis, in that it emphasizes that gender inequality is systematic, institutionalized and pervasive."}, {"id": "hk21", "topic": "keyconcepts", "front": "Statism", "back": "that state Statism (or, intervention is the most appropriate means of resolving political problems, or bringing about economic and social development. This view is underpinned by a deep, and perhaps unquestioning, faith in the state as a mechanism through which collective action can be organized and common goals can be achieved. The state is thus seen as an ethical ideal (Hegel), or as serving the ‘general will’ or public interest. Statism is most clearly reflected in government policies that regulate and control economic life, possibly extending to Soviet-style state collectivization."}, {"id": "hk22", "topic": "keyconcepts", "front": "Failed state", "back": "A failed state is a state that is unable to perform its key role of ensuring domestic order by monopolizing the use of force within its territory. Examples of failed states in recent years include Cambodia, Haiti, Rwanda, Liberia and Somalia. Failed states are no longer able to operate as viable political units, in that they lack a credible system of law and order. They are no longer able to operate as viable economic units, in that they are incapable of providing for their citizens and have no functioning infrastructure. Although relatively few states collapse altogether, a much larger number barely function and are dangerously close to collapse."}, {"id": "hk23", "topic": "keyconcepts", "front": "Legitimacy", "back": "Legitimacy (from the Latin legitimare, meaning ‘to declare lawful’) broadly means ‘rightfulness’. Legitimacy therefore confers on an order or command an authoritative or binding character, thus transforming power (see p. 5) into authority (see p. 4). Political philosophers treat legitimacy as a moral or rational principle; that is, as the grounds on which governments may demand obedience from citizens. The claim to legitimacy is thus more important than the fact of obedience. Political scientists, however, usually see legitimacy in sociological terms; that is, as a willingness to comply with a system of rule regardless of how this is achieved.", "mcq": {"stem": "Which concept does Heywood define as: \"____ (from the Latin legitimare, meaning ‘to declare lawful’) broadly means ‘rightfulness’. ____ therefore confers on an order or command an authoritative or binding character, thus transforming power (see p. 5) into authority (\"", "options": ["New Left", "Constitution", "Departmentalism", "Legitimacy"], "answer": 3, "why": "Legitimacy — Legitimacy (from the Latin legitimare, meaning ‘to declare lawful’) broadly means ‘rightfulness’. Legitimacy therefore confers on an order or command an authoritative or binding character, thus transf"}}, {"id": "hk24", "topic": "keyconcepts", "front": "Tradition", "back": "Tradition may refer to anything that is handed down or transmitted from the past to the present (long-standing customs and practices, institutions, social or political systems, values and beliefs, and so on). Tradition thus denotes continuity with the past. This continuity is usually understood to link the generations, although the line between the traditional and the merely fashionable is often indistinct. ‘Traditional’ societies are often contrasted with‘modern’ ones, the former being structured on the basis of status (see p. 173) and by supposedly organic hierarchies, and the latter on the basis of contractual agreement and by democratic processes.", "mcq": {"stem": "Which concept does Heywood define as: \"____ may refer to anything that is handed down or transmitted from the past to the present (long-standing customs and practices, institutions, social or political systems, values and beliefs, and so on). ____ thus denotes continui\"", "options": ["Rule of law", "Non-governmental organization", "Tradition", "Crime"], "answer": 2, "why": "Tradition — Tradition may refer to anything that is handed down or transmitted from the past to the present (long-standing customs and practices, institutions, social or political systems, values and beliefs, and"}}, {"id": "hk25", "topic": "keyconcepts", "front": "Charisma", "back": "Charisma was originally a theological term meaning the ‘gift of grace’. This was supposedly the source of the power that Jesus", "mcq": {"stem": "Which concept does Heywood define as: \"____ was originally a theological term meaning the ‘gift of grace’. This was supposedly the source of the power that Jesus\"", "options": ["Charisma", "Human security", "Propaganda", "Interdependence"], "answer": 0, "why": "Charisma — Charisma was originally a theological term meaning the ‘gift of grace’. This was supposedly the source of the power that Jesus"}}, {"id": "hk26", "topic": "keyconcepts", "front": "Liberal democracy", "back": "A liberal democracy is a political regime in which a ‘liberal’"}, {"id": "hk27", "topic": "keyconcepts", "front": "Plebiscitary democracy", "back": "Plebiscitary democracy is a form of democratic rule that operates through an unmediated link between the rulers and the ruled, established by plebiscites (or referendums). These allow the public to express their views on political issues directly. However, this type of democracy is often criticized because of the scope it offers for demagoguery (rule by political leaders who manipulate the masses through oratory, and appeal to their prejudices and passions). This type of democracy may amount to little more than a system of mass acclamation that gives dictatorship a populist (see p. 53) gloss."}, {"id": "hk28", "topic": "keyconcepts", "front": "Athenian democracy", "back": "Athenian democracy is characterized by the high level of citizen involvement in the affairs of the city-state. Major decisions were made by the Assembly, or Ecclesia, to which all citizens belonged. When full-time public officials were needed, they were chosen on a basis of lot or rota to ensure that they constituted a microcosm of the larger citizenry. A Council, consisting of 500 citizens, acted as the executive or steering committee of the Assembly, and a 50-strong Committee, in turn, made proposals to the Council. The President of the Committee held office for only a single day, and no Athenian could hold this honour more than once in his lifetime."}, {"id": "hk29", "topic": "keyconcepts", "front": "Parliamentary democracy", "back": "Parliamentary democracy is a form of democratic rule that operates through a popularly elected deliberative assembly, which mediates between government and the people. Democracy, in this sense, means responsible and representative government. Parliamentary democracy thus balances popular participation against elite rule: government is accountable not directly to the public but to the public’s elected representatives. The alleged strength of such a system is that representatives are, by virtue of their education and experience, better able than citizens themselves to define their best interests."}, {"id": "hk30", "topic": "keyconcepts", "front": "Pluralism", "back": "In its broad sense, pluralism is a belief in, or a commitment to, diversity or multiplicity (the existence of many things). As a descriptive term, pluralism may be used to denote the existence of party competition (political pluralism), a multiplicity of moral values (ethical pluralism), or a variety of cultural norms (cultural pluralism). As a normative term, it suggests that diversity is healthy and desirable, usually because it safeguards individual liberty and promotes debate, argument and understanding. More narrowly, pluralism is a theory of the distribution of political power. It holds that power is widely and evenly dispersed in society."}, {"id": "hk31", "topic": "keyconcepts", "front": "Pluralist democracy", "back": "The term pluralist democracy is sometimes used interchangeably with liberal democracy. More specifically, it refers to a form of democracy that operates through the capacity of organized groups and interests to articulate popular demands and ensure responsive government. The conditions for a healthy pluralist democracy include: (1) a wide dispersal of political power amongst competing groups; (2) a high degree of internal responsiveness, group leaders being accountable to members; and (3) a neutral governmental machine that is sufficiently fragmented to offer groups a number of points of access."}, {"id": "hk32", "topic": "keyconcepts", "front": "Elitism", "back": "Elite originally meant, and can still mean, ‘the highest’, ‘the best’ or ‘the excellent’. Used in an empirical sense, it refers to a is minority concentrated. Elitism is a belief in, or practice of, rule by an elite or minority. Normative elitism suggests that political power should be vested in the hands of a wise or enlightened minority. Classical elitism claims to be empirical (although normative beliefs often intrudes), and sees elite rule as an unchangeable fact of social existence. Modern elitism is also empirical, but it is more critical and discriminating about the causes of elite rule.", "mcq": {"stem": "Which concept does Heywood define as: \"Elite originally meant, and can still mean, ‘the highest’, ‘the best’ or ‘the excellent’. Used in an empirical sense, it refers to a is minority concentrated. ____ is a belief in, or practice of, rule by an elite or minority. Normative e\"", "options": ["Presidential government", "Theocracy", "Capitalism", "Elitism"], "answer": 3, "why": "Elitism — Elite originally meant, and can still mean, ‘the highest’, ‘the best’ or ‘the excellent’. Used in an empirical sense, it refers to a is minority concentrated. Elitism is a belief in, or practice of, r"}}, {"id": "hk33", "topic": "keyconcepts", "front": "Government", "back": "Government, in its broadest sense, refers to any mechanism through which ordered rule is maintained, its central features being the ability to make collective decisions and the capacity to enforce them. However, the term is more commonly understood to describe the formal and institutional processes that operate at the national level to maintain public order and facilitate collective action. The core functions of government are, thus, to make law law (legislation), (adjudication). In some cases, the political executive (see p. 316)"}, {"id": "hk34", "topic": "keyconcepts", "front": "Absolutism", "back": "Absolutism is the theory or practice of absolute government, most commonly associated with an absolute monarchy (see p. 324). Government is ‘absolute’, in the sense that it possesses unfettered power: government cannot be constrained by a body external to itself. The absolutist principle, nevertheless, resides in the claim to an unlimited right to rule (as in divine right), rather than the exercise of unchallengeable power. As it is based on a principled claim, whether religious or rational, absolutism does not invest government with arbitrary power, unlike dictatorship (see p. 127)."}, {"id": "hk35", "topic": "keyconcepts", "front": "Totalitarianism", "back": "Totalitarianism is an all-encompassing system of political rule,", "mcq": {"stem": "Which concept does Heywood define as: \"____ is an all-encompassing system of political rule,\"", "options": ["Democratization", "Totalitarianism", "Constructivism", "Collective security"], "answer": 1, "why": "Totalitarianism — Totalitarianism is an all-encompassing system of political rule,"}}, {"id": "hk36", "topic": "keyconcepts", "front": "Polyarchy", "back": "Polyarchy (literally, ‘rule by many’) refers, generally, to the institutions and political processes of modern representative democracy. Polyarchy can be understood as a rough or crude approximation of democracy, in that it operates through institutions that force rulers to take account of the public’s wishes. Its central features are (Dahl, 1971): (1) government is based on election; (2) elections are free and fair; (3) practically all adults have the right to vote; (4) the right to run for office is unrestricted; (5) there is free expression and a right to criticize and protest; (6) citizens have access to alternative sources of information; and (7) groups and associations enjoy at least relative independence from government."}, {"id": "hk37", "topic": "keyconcepts", "front": "The West", "back": "The term ‘the West’ has two overlapping meanings. In a general sense, it refers to the cultural and philosophical inheritance of"}, {"id": "hk38", "topic": "keyconcepts", "front": "Communism", "back": "Communism, in its simplest sense, is the communal organization of social existence on the basis of the collective ownership of", "mcq": {"stem": "Which concept does Heywood define as: \"____, in its simplest sense, is the communal organization of social existence on the basis of the collective ownership of\"", "options": ["Devolution", "Communism", "Interest group", "Relativism"], "answer": 1, "why": "Communism — Communism, in its simplest sense, is the communal organization of social existence on the basis of the collective ownership of"}}, {"id": "hk39", "topic": "keyconcepts", "front": "Democratization", "back": "from Democratization authoritarianism democracy. Democratization encompasses three, sometimes overlapping, processes. (1) The break-down of the old regime; this usually involves a loss of legitimacy (see p. 80) and the faltering loyalty of the police and military. (2) ‘Democratic transition’ witnesses the construction of new liberal-democratic structures and processes. (3) ‘Democratic consolidation’ sees these new structures and processes becoming so embedded in the minds of elites and the masses that democracy becomes ‘the only game in town’ (Przeworski, 1991).", "mcq": {"stem": "Which concept does Heywood define as: \"from ____ authoritarianism democracy. ____ encompasses three, sometimes overlapping, processes. (1) The break-down of the old regime; this usually involves a loss of legitimacy (see p. 80) and the faltering loyalty of \"", "options": ["Democratization", "Judicial review", "Departmentalism", "Crime"], "answer": 0, "why": "Democratization — from Democratization authoritarianism democracy. Democratization encompasses three, sometimes overlapping, processes. (1) The break-down of the old regime; this usually involves a loss of legitimacy ("}}, {"id": "hk40", "topic": "keyconcepts", "front": "Authoritarianism", "back": "Authoritarianism is a belief in, or practice of, government ‘from above’, in which authority is exercised regardless of popular consent. Authoritarianism thus differs from authority, as the latter rests on legitimacy, and so arises ‘from below’. Authoritarian regimes emphasize the claims of authority over those of individual liberty. However, authoritarianism is usually distinguished from totalitarianism. Authoritarianism, associated with monarchical absolutism, traditional dictatorships and most forms of military rule, seeks to exclude the masses from politics rather than abolish civil society.", "mcq": {"stem": "Which concept does Heywood define as: \"____ is a belief in, or practice of, government ‘from above’, in which authority is exercised regardless of popular consent. ____ thus differs from authority, as the latter rests on legitimacy, and so arises ‘from be\"", "options": ["Bureaucracy", "Authoritarianism", "Policy network", "Authority"], "answer": 1, "why": "Authoritarianism — Authoritarianism is a belief in, or practice of, government ‘from above’, in which authority is exercised regardless of popular consent. Authoritarianism thus differs from authority, as the latter res"}}, {"id": "hk41", "topic": "keyconcepts", "front": "Majoritarianism", "back": "As a descriptive concept, majoritarianism refers to a rule of decision-making in which the preferences of the majority overrule those of the minority, although it is unclear whether this refers to an ‘absolute’ or ‘simple’ majority. As a normative concept, majoritarianism refers to the belief that majority views should prevail over minority views, with the possible implication that the"}, {"id": "hk42", "topic": "keyconcepts", "front": "Confucianism", "back": "Confucianism is a system of ethics formulated by Confucius (551–479 BCE) and his disciples that was primarily outlined in The Analects. Confucian thought has concerned itself with the twin themes of human relations and the cultivation of the self. The emphasis on ren (humanity or love) has usually been interpreted"}, {"id": "hk43", "topic": "keyconcepts", "front": "Theocracy", "back": "Theocracy (literally ‘rule by God’) is the principle that religious authority should prevail over political authority. A theocracy is therefore a regime in which government posts are filled on the basis of the person’s position in the religious hierarchy. Theocratic rule is illiberal in two senses. First, it violates the public/private divide, in that it takes religious rules and precepts to be the guiding principles of both personal life and political conduct. Second, it invests political authority with potentially unlimited power, because, as temporal power is derived from"}, {"id": "hk44", "topic": "keyconcepts", "front": "Dictatorship", "back": "A dictatorship is, strictly, a form of rule in which absolute power is vested in one individual; in this sense, dictatorship is synonymous with autocracy. Dictators are thus seen as being above the law and as acting beyond constitutional constraints. Early examples of dictators were Sulla, Julius Caesar and Augustus Caesar in Rome, more recent ones are Hitler, Mussolini and Saddam Hussein. More generally, dictatorship is characterized by the arbitrary and unchecked exercise of power, as ‘class ‘military dictatorship’ and dictatorship’, ‘personal dictatorship’."}, {"id": "hk45", "topic": "keyconcepts", "front": "Nation", "back": "Nations (from the Latin nasci, meaning ‘to be born’) are complex phenomena that are shaped by a collection of factors. Culturally, a nation is a group of people bound together by a common language, religion, history and traditions, although nations exhibit various levels of cultural heterogeneity. Politically, a nation is a group of people who regard themselves as a natural political community, classically expressed through the quest for sovereign statehood. Psychologically, a nation is a group of people distinguished by a shared loyalty or affection in the form of patriotism (see p. 140)."}, {"id": "hk46", "topic": "keyconcepts", "front": "Cultural nationalism", "back": "Cultural nationalism is a form of nationalism that places primary emphasis on the regeneration of the nation as a distinctive civilization, rather than as a discrete political community. Whereas political nationalism is ‘rational’, and usually principled, cultural nationalism is ‘mystical’, in that it is based on a romantic belief in the nation as a unique, historical and organic whole, animated by its own ‘spirit’. Typically, it is a ‘bottom-up’ form of nationalism that draws more on ‘popular’ rituals, traditions and legends than on elite, or ‘higher’, culture."}, {"id": "hk47", "topic": "keyconcepts", "front": "Racialism, racism", "back": "The terms racialism and racism tend to be used interchangeably. Racialism refers to any belief or doctrine that draws political or social conclusions from the idea that humankind is divided into biologically distinct races (a notion that has no, or little, scientific basis). Racialist theories are thus based on the assumption that cultural, intellectual and moral differences amongst humankind derive from supposedly more fundamental genetic differences. In political terms, racialism is manifest in calls for racial segregation (apartheid), and in doctrines of ‘blood’ superiority and inferiority (Aryanism and anti-Semitism)."}, {"id": "hk48", "topic": "keyconcepts", "front": "Internationalism", "back": "Internationalism is the theory or practice of politics based on transnational or global cooperation. It is rooted in universalist assumptions about human nature that put it at odds with political nationalism. The major internationalist traditions are drawn from liberalism and socialism. Liberal internationalism is based on individualism reflected in the assumption that human rights have a ‘higher’ status than claims based on national sovereignty. Socialist internationalism is grounded in a belief in international class solidarity (proletarian internationalism), underpinned by assumptions about a common humanity.", "mcq": {"stem": "Which concept does Heywood define as: \"____ is the theory or practice of politics based on transnational or global cooperation. It is rooted in universalist assumptions about human nature that put it at odds with political nationalism. The major internationalist trad\"", "options": ["Democratization", "Internationalism", "Nation", "Power"], "answer": 1, "why": "Internationalism — Internationalism is the theory or practice of politics based on transnational or global cooperation. It is rooted in universalist assumptions about human nature that put it at odds with political nati"}}, {"id": "hk49", "topic": "keyconcepts", "front": "Patriotism", "back": "Patriotism (from the Latin patria, meaning ‘fatherland’) is a sentiment, a psychological attachment to one’s nation (a ‘love of"}, {"id": "hk50", "topic": "keyconcepts", "front": "Race", "back": "Race refers to physical or genetic differences amongst humankind that supposedly distinguish one group of people from another on biological grounds such as skin and hair colour, physique and facial features. A race is thus a group of people who share a common ancestry and ‘one blood’. The term is, however, controversial, both scientifically and politically. Scientific evidence suggests that there is no such thing as ‘race’ in the sense of a species-type difference between peoples. Politically, racial categorization is commonly based on cultural stereotypes, and is simplistic at best and pernicious at worst."}, {"id": "hk51", "topic": "keyconcepts", "front": "Anti-Semitism", "back": "‘Semites’ are by tradition the descendants of Shem, son of Noah. They include most of the peoples of the Middle East. Anti- Semitism is prejudice or hatred specifically towards Jews. In its earliest form, religious anti-Semitism reflected the hostility of the Christians towards the Jews, based on their alleged complicity in the murder of Jesus and their refusal to acknowledge him as the son of God. Economic anti-Semitism developed from the Middle Ages onwards, and expressed distaste for Jews in their capacity as moneylenders and traders. Racial anti-Semitism developed from the late nineteenth century onwards, and condemned the Jewish peoples as fundamentally evil and destructive."}, {"id": "hk52", "topic": "keyconcepts", "front": "Colonialism", "back": "Colonialism is the theory or practice of establishing control over a foreign territory and turning it into a ‘colony’. Colonialism is thus a particular form of imperialism (see p. 442). Colonialism is usually distinguished by settlement and by economic domination. As typically practised in Africa and Southeast Asia, colonial government was exercised by a settler community from a ‘mother country’. In contrast, neocolonialism is essentially an economic phenomenon based on the export of capital from an advanced country to a less developed one (for example, so-called US ‘dollar imperialism’ in Latin America)."}, {"id": "hk53", "topic": "keyconcepts", "front": "Nation-state", "back": "The nation-state is a form of political organization and a political ideal. In the first case, it is an autonomous political community bound together by the overlapping bonds of citizenship and nationality. In the latter, it is a principle, or ideal type (see p. 18), reflected in Mazzini’s goal: ‘every nation a state, only one state for the entire nation’. As such, the nation-state principle embodies the belief that nations are ‘natural’ political communities. For liberals and most socialists, the nation-state is largely fashioned out of civic loyalties and allegiances. For conservatives and integral nationalists, it is based on ethnic or organic unity."}, {"id": "hk54", "topic": "keyconcepts", "front": "Political economy", "back": "Political economy, broadly, is the study of the interaction of politics and economics. As a topic, political economy focuses on the relationship between states and markets. Although political economy, in this sense, encompasses a variety of approaches, the term has a long association with Marxism, reflecting the tendency within Marxist analysis to link power to the ownership of wealth. As a method, political economy refers to the use of theories and approaches developed within economics to analyse politics, and includes rational-choice, public-choice, social-choice and games theories.", "mcq": {"stem": "Which concept does Heywood define as: \"____, broadly, is the study of the interaction of politics and economics. As a topic, ____ focuses on the relationship between states and markets. Although ____, in this sense, encompasses a variety of\"", "options": ["Crime", "Political economy", "Ministerial responsibility", "Realism"], "answer": 1, "why": "Political economy — Political economy, broadly, is the study of the interaction of politics and economics. As a topic, political economy focuses on the relationship between states and markets. Although political economy,"}}, {"id": "hk55", "topic": "keyconcepts", "front": "Capitalism", "back": "Capitalism can be viewed as either an economic system or as an ideology. As an economic system, capitalism is a system of generalized commodity production. Its key features are: (1) productive wealth is predominantly privately owned; (2) economic life is organized according to market principles, resources being", "mcq": {"stem": "Which concept does Heywood define as: \"____ can be viewed as either an economic system or as an ideology. As an economic system, ____ is a system of generalized commodity production. Its key features are: (1) productive wealth is predominantly privately owned; (2) ec\"", "options": ["Party democracy", "Capitalism", "Policy", "Comparative politics"], "answer": 1, "why": "Capitalism — Capitalism can be viewed as either an economic system or as an ideology. As an economic system, capitalism is a system of generalized commodity production. Its key features are: (1) productive wealth "}}, {"id": "hk56", "topic": "keyconcepts", "front": "Laissez-faire", "back": "Laissez-faire (in French, meaning literally ‘leave to do’) is the principle of non-intervention of government in economic affairs. It"}, {"id": "hk57", "topic": "keyconcepts", "front": "Social market", "back": "The idea of a social-market economy emerged in Germany in the 1950s. A social market is an economy that is structured by", "mcq": {"stem": "Which concept does Heywood define as: \"The idea of a ____-____ economy emerged in Germany in the 1950s. A ____ is an economy that is structured by\"", "options": ["Social market", "Failed state", "Plebiscitary democracy", "The West"], "answer": 0, "why": "Social market — The idea of a social-market economy emerged in Germany in the 1950s. A social market is an economy that is structured by"}}, {"id": "hk58", "topic": "keyconcepts", "front": "Globalization", "back": "Globalization is the emergence of a complex web of interconnectedness that means that our lives are increasingly shaped by events that occur, and decisions that are made, at a great distance from us. The central feature of globalization is therefore that geographical distance and territorial boundaries, such as those between nation-states, are of declining relevance. By no means, however, does globalization imply that ‘the local’ and ‘the national’ are subordinate to ‘the global’. Rather, it highlights the deepening, as well as the broadening, of the political process, in the sense that local, national and global events constantly interact.", "mcq": {"stem": "Which concept does Heywood define as: \"____ is the emergence of a complex web of interconnectedness that means that our lives are increasingly shaped by events that occur, and decisions that are made, at a great distance from us. The central feature of ____ is \"", "options": ["Global governance", "Globalization", "Authority", "Plebiscitary democracy"], "answer": 1, "why": "Globalization — Globalization is the emergence of a complex web of interconnectedness that means that our lives are increasingly shaped by events that occur, and decisions that are made, at a great distance from us. "}}, {"id": "hk59", "topic": "keyconcepts", "front": "Neoliberalism", "back": "Neoliberalism (sometimes called ‘neoclassical liberalism’) is an"}, {"id": "hk60", "topic": "keyconcepts", "front": "The Washington consensus", "back": "The term the Washington consensus was coined by John Williamson to describe the policies that the international institutions based in Washington, the IMF, the World Bank and US Treasury Department had come to favour for the reconstruction of economies in the developing world. Based on the ‘orthodox’ model of development as growth, and drawing on the ideas of neoliberalism, the essence of the Washington consensus can be summed up as ‘stabilize, privatize and liberalize’."}, {"id": "hk61", "topic": "keyconcepts", "front": "Transnational corporations", "back": "A transnational corporation (TNC) is a company that controls economic activity in two or more countries. The term transnational corporation is now generally preferred to multinational corporation (MNC) because it captures the extent to which corporate strategies and processes transcend national borders, rather than merely crossing them. Integration across economic sectors and the growth of intra-firm trade has allowed TNCs to become economies in their own right, benefiting from geographical flexibility, advantages in product innovation, and the ability to pursue global marketing strategies."}, {"id": "hk62", "topic": "keyconcepts", "front": "Status", "back": "Status is a person’s position within a hierarchical order. It is characterized by the person’s role, rights and duties in relation to the other members of that order. As status is a compound of factors such as honour, prestige, standing and power, it is more difficult to determine than an essentially economic category such as class. Also, because it is a measure of whether someone is", "mcq": {"stem": "Which concept does Heywood define as: \"____ is a person’s position within a hierarchical order. It is characterized by the person’s role, rights and duties in relation to the other members of that order. As ____ is a compound of factors such as honour, prestige, standing and\"", "options": ["Political participation", "Multiculturalism", "Status", "Racialism, racism"], "answer": 2, "why": "Status — Status is a person’s position within a hierarchical order. It is characterized by the person’s role, rights and duties in relation to the other members of that order. As status is a compound of factor"}}, {"id": "hk63", "topic": "keyconcepts", "front": "Fordism, post-Fordism", "back": "Fordism refers to the large-scale mass-production methods pioneered by Henry Ford in Detroit in the USA. These used mechanization and highly regimented production-line labour"}, {"id": "hk64", "topic": "keyconcepts", "front": "Information society", "back": "An information society is a society in which the creation, distribution and manipulation of information are core economic and cultural activities, underpinned, in particular, by the wider use"}, {"id": "hk65", "topic": "keyconcepts", "front": "Individualism", "back": "Individualism is the belief in the supreme importance of the individual over any social group or collective body. As such, individualism has two key implications. First, each individual has a separate, indeed unique, identity, reflecting his or her ‘inner’ or personal qualities. This is evident in the idea of individuality, and is linked to the notion of people as self-interested, and largely self-reliant, creatures. Second, all individuals share the same moral status as ‘persons’, irrespective of factors such as race, religion, nationality, sex and social position. This is reflected in the idea of rights, and especially in the doctrine of human rights (see p. 304)."}, {"id": "hk66", "topic": "keyconcepts", "front": "Consumerism", "back": "Consumerism is a psychic and social phenomenon whereby personal happiness is equated with the acquisition and consumption of material possessions. Its growth has been shaped by the development of new advertising and marketing techniques that took advantage of the emergence of the mass media and the spread of mass affluence. Rising consumerism has important socio-economic and cultural implications. Whereas ‘productionist’ societies emphasize the values of discipline, duty and hard work (the Protestant work ethic, for example), consumer societies emphasize materialism, hedonism and immediate, rather than delayed, gratification."}, {"id": "hk67", "topic": "keyconcepts", "front": "Postcolonialism", "back": "Postcolonialism is a trend in literary, cultural and political studies that seeks to expose and overturn the cultural and psychological dimensions of colonial rule. As such, it recognizes that ‘inner’ subjugation can persist long after the political structures of colonialism have been removed. A major thrust of postcolonialism has been to establish the legitimacy of non-Western, and sometimes anti-Western, political ideas and traditions. Postcolonialism has nevertheless taken a variety of forms. These range from Gandhi’s attempt to fuse Indian nationalism with ideas rooted in Hinduism to forms of religious fundamentalism."}, {"id": "hk68", "topic": "keyconcepts", "front": "Relativism", "back": "Relativism is a position that denies the existence of objective or ‘absolute’ standards, and so holds that statements can be judged only in relation to their contexts. Cultural relativism is the belief that moral codes can only be understood in the context of the societies in which they operate. Moral, or normative, relativism refers to the belief that there are no authoritative ethical principles (usually because each individual is a morally autonomous being). Cognitive, or epistemological, relativism holds that different modes of knowing are equally valid, and thus dismisses the universalist pretensions of, say, science (see p. 12)."}, {"id": "hk69", "topic": "keyconcepts", "front": "Multiculturalism", "back": "Multiculturalism is used as both a descriptive and a normative term. As a descriptive term, it refers to cultural diversity arising from the existence within a society of two or more groups whose beliefs and practices generate a distinctive sense of collective identity. As a normative term, multiculturalism implies a positive endorsement of communal diversity, based on either the right of cultural groups to respect and recognition, or the alleged benefits to the larger society of moral and cultural diversity. Multiculturalism, in this sense, acknowledges the importance of beliefs, values and ways of life in establishing a sense of selfworth for individuals and groups alike."}, {"id": "hk70", "topic": "keyconcepts", "front": "Gender", "back": "Gender refers to social and cultural distinctions between males and females (as opposed to ‘sex’ which highlights biological, and therefore ineradicable, differences between men and women). Gender is therefore a social construct, usually based on stereotypes of ‘feminine’ and ‘masculine’ behaviour. Feminists typically emphasize the distinction in order to demonstrate that physical or biological differences (sexual differences) need not mean that women and men must have different social roles and positions (gender differences). In short, gender equality is based on the belief that sexual differences have no social or political significance.", "mcq": {"stem": "Which concept does Heywood define as: \"____ refers to social and cultural distinctions between males and females (as opposed to ‘sex’ which highlights biological, and therefore ineradicable, differences between men and women). ____ is therefore a social construct, usually ba\"", "options": ["Postmodernism", "Gender", "Party government", "Islamism"], "answer": 1, "why": "Gender — Gender refers to social and cultural distinctions between males and females (as opposed to ‘sex’ which highlights biological, and therefore ineradicable, differences between men and women). Gender is "}}, {"id": "hk71", "topic": "keyconcepts", "front": "Interculturalism", "back": "Interculturalism is an approach to diversity which strongly emphasises the benefits of dialogue and interaction between cultures. As such, it has been seen as a response to the question how to live in, rather than with, diversity. The intercultural approach is based on three key assumption. First, it rejects the idea that cultures are fixed and unchanging, instead emphasizing that they are fluid and internally differentiated. Dialogue thus takes place within cultures as well as between them. Second, contest, debate and argument are seen to be intrinsically worthwhile, reflecting an underlying faith in reason. Third, cultures are taken to be distinguished more by what they have in common than by what divides them."}, {"id": "hk72", "topic": "keyconcepts", "front": "Intersectionality", "back": "Intersectionality is a framework for the analysis of injustice and social equality that emphasizes the multidimensional or multifaceted nature of personal identity and of related systems of domination. In this view, women do not just have a straightforward gender-based identity but rather one in which, for instance, race, social class, ethnicity, age, religion, nationality and sexual orientation can overlap, or ‘intersect’, with gender. This implies that women may be subject to interlocking systems of oppression and discrimination, as sexism becomes entangled with racism, xenophobia, homophobia, and so on.", "mcq": {"stem": "Which concept does Heywood define as: \"____ is a framework for the analysis of injustice and social equality that emphasizes the multidimensional or multifaceted nature of personal identity and of related systems of domination. In this view, women do not just have a\"", "options": ["Social movement", "Pluralist democracy", "Intersectionality", "Colonialism"], "answer": 2, "why": "Intersectionality — Intersectionality is a framework for the analysis of injustice and social equality that emphasizes the multidimensional or multifaceted nature of personal identity and of related systems of domination"}}, {"id": "hk73", "topic": "keyconcepts", "front": "Islamism", "back": "Islamism (also called ‘political Islam’ or ‘radical Islam’) is a politico-religious ideology, as opposed to a simple belief in Islam. Although Islamist ideology has no single creed or political manifestation, certain common beliefs can be identified, as follows. (1) Society should be reconstructed in line with the ideals of Islam. (2) The modern secular state should be replaced by an ‘Islamic state’. (3) The West and Western values are viewed as corrupt and corrupting, justifying, for some, the notion of a jihad against them. However, distinct Sunni and Shi’a versions of Islamism have been developed, the former linked to Wahhabism, the latter to Iran’s ‘Islamic Revolution’."}, {"id": "hk74", "topic": "keyconcepts", "front": "Political culture", "back": "Culture, in its broadest sense, is the way of life of a people. Sociologists and anthropologists tend to distinguish between ‘culture’ and ‘nature’, the former encompassing that which is passed on from one generation to the next by learning, rather than through biological inheritance. Political scientists, however, use the term in a narrower sense to refer to a people’s psychological orientation, political culture being the ‘pattern of orientations’ to political objects such as parties, government, and the constitution, expressed in beliefs, symbols and values.", "mcq": {"stem": "Which concept does Heywood define as: \"____, in its broadest sense, is the way of life of a people. Sociologists and anthropologists tend to distinguish between ‘____’ and ‘nature’, the former encompassing that which is passed on from one generation to the next by learning\"", "options": ["Neoliberalism", "Political culture", "Utilitarianism", "Plebiscitary democracy"], "answer": 1, "why": "Political culture — Culture, in its broadest sense, is the way of life of a people. Sociologists and anthropologists tend to distinguish between ‘culture’ and ‘nature’, the former encompassing that which is passed on fro"}}, {"id": "hk75", "topic": "keyconcepts", "front": "Hegemony", "back": "Hegemony (from the Greek hegemonia, meaning ‘leader’) is, in its simplest sense, the ascendancy or domination of one element of a system over others. In Marxist theory, the term is used in a more specific sense. In the writings of Gramsci (see p. 198), hegemony refers to the ability of a dominant class to exercise", "mcq": {"stem": "Which concept does Heywood define as: \"____ (from the Greek hegemonia, meaning ‘leader’) is, in its simplest sense, the ascendancy or domination of one element of a system over others. In Marxist theory, the term is used in a more specific sense. In the writings of Gramsci (\"", "options": ["Postmodernism", "Hegemony", "Individualism", "Capitalism"], "answer": 1, "why": "Hegemony — Hegemony (from the Greek hegemonia, meaning ‘leader’) is, in its simplest sense, the ascendancy or domination of one element of a system over others. In Marxist theory, the term is used in a more spec"}}, {"id": "hk76", "topic": "keyconcepts", "front": "Social capital", "back": "The concept of social capital was developed in the 1970s to highlight the social and cultural factors that underpin wealth creation. The term has since been used to refer to social connectiveness, as represented by networks, norms and trust that promote civic engagement. In common with economic assets, social capital can decline or rise, usually through education and a stress on active citizenship. The alleged decline in social capital in modern society has been linked, variously, to the ‘parenting deficit’, the rise of individualism, and the increase in social and geographical mobility."}, {"id": "hk77", "topic": "keyconcepts", "front": "Communitarianism", "back": "Communitarianism is the belief that the self or person is constituted through the community, in the sense that individuals are shaped by the communities to which they belong and thus owe them a debt of respect and consideration. Left-wing communitarians hold that community demands unrestricted freedom and social equality. Centrist communitarians hold that community is grounded in reciprocal rights and responsibilities. Right-wing communitarians hold that community requires respect for authority and established values."}, {"id": "hk78", "topic": "keyconcepts", "front": "Postmaterialism", "back": "Postmaterialism is a theory that explains the nature of political concerns and values in terms of levels of economic development. It is loosely based on Abraham Maslow’s (1908–70) ‘hierarchy of needs’, which places esteem and self-actualization above material or economic needs. Postmaterialism assumes that conditions of material scarcity breed egoistical and acquisitive values, meaning that politics is dominated by economic issues. However, in conditions of widespread prosperity, individuals express more interest in ‘postmaterial’ or ‘quality of life’ issues, typically concerned with morality, political justice and personal fulfilment."}, {"id": "hk79", "topic": "keyconcepts", "front": "Political socialization", "back": "Political socialization is the process through which individuals acquire political beliefs and values, and by which these are transmitted from one generation to the next. Families and schools"}, {"id": "hk80", "topic": "keyconcepts", "front": "Mass media", "back": "The media comprise those societal institutions that are concerned with the production and distribution of all forms of knowledge, information and entertainment. The ‘mass’ media channel communication towards a large and undifferentiated audience using relatively advanced technology. The clearest examples are the ‘broadcast’ media (television and radio) and the ‘print’ media (newspapers and magazines). The ‘new’ media (cable and satellite telecommunications, the internet, and so on) has subverted the notion of mass media by dramatically increasing audience fragmentation."}, {"id": "hk81", "topic": "keyconcepts", "front": "Political bias", "back": "Political bias refers to political views that systematically favour the values or interests of one group over another as opposed to ‘balanced’ or ‘objective’ beliefs. Bias, however, may take various forms (McQuail, 1992). Partisan bias is explicit and deliberately promoted (newspaper editorials). Propaganda bias is deliberate"}, {"id": "hk82", "topic": "keyconcepts", "front": "Propaganda", "back": "Propaganda is information (or disinformation) disseminated in a deliberate attempt to shape opinions and, possibly, stimulate political action. Propaganda is a pejorative term, implying both untruth or distortion, and a (usually crude) desire to manipulate and control public opinion. Propaganda differs from political bias in that it is systematic and deliberate, whereas the latter may be partial and unintentional. A distinction is sometimes drawn between ‘black’ propaganda (blatant lies), ‘grey’ propaganda (distortions and half truths) and ‘white’ propaganda (the truth).", "mcq": {"stem": "Which concept does Heywood define as: \"____ is information (or disinformation) disseminated in a deliberate attempt to shape opinions and, possibly, stimulate political action. ____ is a pejorative term, implying both untruth or distortion, and a (usually crude) desi\"", "options": ["Party democracy", "Propaganda", "Responsibility", "Anti-politics"], "answer": 1, "why": "Propaganda — Propaganda is information (or disinformation) disseminated in a deliberate attempt to shape opinions and, possibly, stimulate political action. Propaganda is a pejorative term, implying both untruth o"}}, {"id": "hk83", "topic": "keyconcepts", "front": "Representation", "back": "Representation is, broadly, a relationship through which an individual or group stands for, or acts on behalf of, a larger body of people. Representation differs from democracy in that, while the former acknowledges a distinction between government and the governed, the latter, at least in its classical form, aspires to abolish this distinction and establish popular self-government. Representative democracy (see p. 93) may nevertheless constitute a limited and indirect form of democratic rule, provided that the representation links government and the governed in such a way that the people’s views are articulated, or their interests secured.", "mcq": {"stem": "Which concept does Heywood define as: \"____ is, broadly, a relationship through which an individual or group stands for, or acts on behalf of, a larger body of people. ____ differs from democracy in that, while the former acknowledges a distinction between go\"", "options": ["Charisma", "The state", "War", "Representation"], "answer": 3, "why": "Representation — Representation is, broadly, a relationship through which an individual or group stands for, or acts on behalf of, a larger body of people. Representation differs from democracy in that, while the form"}}, {"id": "hk84", "topic": "keyconcepts", "front": "Mandate", "back": "A mandate is an instruction or command from a higher body that demands compliance. The idea of a policy mandate arises from the claim on behalf of a winning party in an election that its manifesto promises have been endorsed, giving it authority to translate these into a programme of government. The doctrine of the mandate thus implies that the party in power can only act within the mandate it has received. The more flexible notion of a governing mandate, or, for an individual leader, a personal mandate, has sometimes been advanced, but it is difficult to see how this in any way restricts politicians once they are in power."}, {"id": "hk85", "topic": "keyconcepts", "front": "Proportional representation", "back": "Proportional representation is the principle that parties should be represented in an assembly or parliament in direct proportion to their overall electoral strength, their percentage of seats equalling their percentage of votes. The term is generally used to refer not to a single method of election but to a variety of electoral mechanisms, those able to secure proportional outcomes, or at least a high and reliable degree of proportionality. The best known PR systems are the party-list system, the singletransferable-vote system and the additional member system."}, {"id": "hk86", "topic": "keyconcepts", "front": "Public interest", "back": "The public interest consists of the general or collective interests of a community; that is, that which is good for society as a whole. Two contrasting notions of the public interest can be identified. Strong versions distinguish clearly between the interests of the public as a collective body and the selfish or personal interests of each individual. In the view of Rousseau and many socialists, the"}, {"id": "hk87", "topic": "keyconcepts", "front": "Partisan dealignment", "back": "Partisan dealignment is a decline in the extent to which people align themselves with a party by identifying with it. This implies that the ‘normal’ support of parties falls, and a growing number of electors become ‘floating’ or ‘swing’ voters. As party loyalties weaken, electoral behaviour becomes more volatile, leading to greater uncertainty and, perhaps, the rise of new parties, or the decline of old ones. The principal reasons for partisan dealignment are the expansion of education, increased social mobility, and growing reliance on television as a source of political information."}, {"id": "hk88", "topic": "keyconcepts", "front": "Class dealignment", "back": "Class dealignment is the weakening of the relationship between social class and party support. Social class may nevertheless remain a significant (even the most significant) factor influencing electoral choice. The impact of dealignment has been to undermine traditional class-based parties (notably, working-class parties of the left), often bringing about a realignment of the party system. Explanations of class dealignment usually focus on changes in the social structure that have weakened the solidaristic character of class identity, such as postindustrialism.", "mcq": {"stem": "Which concept does Heywood define as: \"____ is the weakening of the relationship between social ____ and party support. Social ____ may nevertheless remain a significant (even the most significant) factor influencing electoral choice. The impact of ____ has\"", "options": ["Dictatorship", "Majoritarianism", "Government", "Class dealignment"], "answer": 3, "why": "Class dealignment — Class dealignment is the weakening of the relationship between social class and party support. Social class may nevertheless remain a significant (even the most significant) factor influencing elector"}}, {"id": "hk89", "topic": "keyconcepts", "front": "Political party", "back": "A political party is a group of people that is organized for the purpose of winning government power, by electoral or other"}, {"id": "hk90", "topic": "keyconcepts", "front": "Faction, factionalism", "back": "A faction is a section or group within a larger formation, usually a political party. Its aims and organizational status must therefore be compatible with those of its host party; otherwise the group is a ‘party within a party’. A distinction is sometimes drawn between ‘factions’ and ‘tendencies’, the latter being looser and more informal groups, distinguished only by a common policy or ideological disposition. Factionalism refers either to the proliferation of factions, or to the bitterness of factional rivalry. The term faction is often used pejoratively; the term factionalism is always pejorative, implying debilitating infighting."}, {"id": "hk91", "topic": "keyconcepts", "front": "Primary election", "back": "A primary election is an intraparty election in which candidates are selected to contest a subsequent ‘official’ election. During the twentieth century, primaries became the principal nominating device used in the USA, also being used to choose convention delegates and party leaders. Most US states hold ‘closed’ primaries, in which participation is restricted to registered supporters of the party; ‘open’ primaries allow all voters to participate, regardless of party affiliation. Primary elections give rank-and-file voters more of a voice in party affairs and lead to a more candidate-orientated and less party-orientated style of politics."}, {"id": "hk92", "topic": "keyconcepts", "front": "Party democracy", "back": "Party democracy is a form of popular rule that operates through the agency of a party. There are two models of party democracy. In the first (intra-party democracy), parties are democratic agents, in that power within them is widely and evenly dispersed. This implies, for instance, that there should be broad participation in the election of leaders and selection of candidates. In the second model, democracy dictates that policy-making power should be concentrated in the hands of party members who are elected and, therefore, publicly accountable. In this view, the first model may lead to the tyranny of non-elected constituency activists."}, {"id": "hk93", "topic": "keyconcepts", "front": "Party government", "back": "Party government is a system through which single parties are able to form governments and carry through policy programmes. Its key features are as follows. (1) Major parties possess a clear programmic character and thus offer the electorate a meaningful"}, {"id": "hk94", "topic": "keyconcepts", "front": "Coalition", "back": "A coalition is a grouping of rival political actors brought together either through the perception of a common threat, or through a recognition that their goals cannot be achieved by working separately. Electoral coalitions are alliances through which parties agree not to compete against one another, with a view to maximizing their representation. Legislative coalitions are agreements between two or more parties to support a particular bill or programme. Governing coalitions are formal agreements between two or more parties that involve a cross-party distribution of ministerial portfolios. A ‘grand coalition’ or ‘national government’ comprises all major parties.", "mcq": {"stem": "Which concept does Heywood define as: \"A ____ is a grouping of rival political actors brought together either through the perception of a common threat, or through a recognition that their goals cannot be achieved by working separately. Electoral ____s are alliances th\"", "options": ["Citizenship", "Departmentalism", "Coalition", "Free trade"], "answer": 2, "why": "Coalition — A coalition is a grouping of rival political actors brought together either through the perception of a common threat, or through a recognition that their goals cannot be achieved by working separatel"}}, {"id": "hk95", "topic": "keyconcepts", "front": "Interest group", "back": "An interest group (or pressure group) is an organized association that aims to influence the policies or actions of government. Interest groups differ from political parties in the following ways. (1) They seek to exert influence from outside, rather than to win or exercise government power. (2) They typically have a narrow issue focus, in that they are usually concerned with a specific cause or the interests of a particular group. (3) They seldom have the broader programmic or ideological features that are generally associated with political parties. Interest groups are distinguished"}, {"id": "hk96", "topic": "keyconcepts", "front": "Non-governmental organization", "back": "A non-governmental organization (NGO) is a private, noncommercial group or body which seeks to achieve its ends through non-violent means. NGOs are usually active in international politics and may be accorded formal consultation rights by bodies such as the UN or EU. Operational NGOs are those whose primary purpose is the design and implementation of projects that are usually either development-related or reliefrelated. Advocacy NGOs exist to promote or defend a particular cause, and are more concerned with expertise and specialist knowledge than with operational capacity."}, {"id": "hk97", "topic": "keyconcepts", "front": "Corporatism", "back": "Corporatism, in its broadest sense, is a means of incorporating organized interests into the processes of government. There are two faces of corporatism. Authoritarian corporatism (‘state’ corporatism) is an ideology or economic form closely associated with Italian Fascism. It was characterized by the political intimidation of industry and the destruction of independent trade unions. Liberal corporatism (‘societal’ corporatism or ‘neocorporatism’) refers to the tendency found in mature liberal democracies for organized interests to be granted privileged and institutional access to the process of policy formulation."}, {"id": "hk98", "topic": "keyconcepts", "front": "Public choice", "back": "Public-choice theory is a subfield of rational-choice theory (see p. 14) The ‘public’ character of public-choice theory stems from its concern with the provision of so-called ‘public goods’. These are goods that are delivered by government rather than the market, because (as with clean air) their benefit cannot be withheld from individuals who choose not to contribute to their provision. Publicchoice theorists have generally highlighted the failures and defects of government in this respect, focusing on issues such as the policy impact of self-serving bureaucrats, and the consequences of interest-group politics."}, {"id": "hk99", "topic": "keyconcepts", "front": "Lobby", "back": "The term lobby is derived from the areas in parliaments or assemblies where the public may petition legislators, or politicians meet to discuss political business. In modern usage, the term is both a verb and a noun. The verb ‘to lobby’ means to make direct representations to a policy-maker, using argument or persuasion. Broadly, ‘a lobby’ (noun) is equivalent to an interest group, in that both aim to influence public policy, as in the case of the farm lobby, the environmental lobby and the roads lobby. Narrowly, following US practice, a lobbyist is a ‘professional persuader’: that is, a person hired to represent the arguments of interest group clients."}, {"id": "hk100", "topic": "keyconcepts", "front": "Civil disobedience", "back": "Civil disobedience is law-breaking that is justified by reference to ‘higher’ religious, moral or political principles. Civil disobedience is an overt and public act; it aims to break a law in order to ‘make a point’, not to get away with it. Indeed, its moral force is based largely on the willing acceptance of the penalties that follow from law-breaking. This both emphasizes the conscientious or principled nature of the act and provides evidence of the depth of feeling or commitment that lies behind it. The moral character of civil disobedience is normally demonstrated by the strict avoidance of violence."}, {"id": "hk101", "topic": "keyconcepts", "front": "Social movement", "back": "A social movement is a particular form of collective behaviour in which the motive to act springs largely from the attitudes and aspirations of members, typically acting within a loose organizational framework. Being part of a social movement requires a level of commitment and political activism, rather than formal or card-carrying membership: above all, movements move. A movement is different from spontaneous mass action (such as an uprising or rebellion), in that it implies a level of intended and planned action in pursuit of a recognized social goal."}, {"id": "hk102", "topic": "keyconcepts", "front": "New Left", "back": "The New Left comprises the thinkers and intellectual movements (prominent in the 1960s and early 1970s) that sought to revitalize socialist thought by developing a radical critique of advanced industrial society. The New Left rejected both ‘old’ left alternatives: Soviet-style state socialism and de-radicalized Western social democracy. Common themes within the New Left include a fundamental rejection of conventional society (‘the system’) as oppressive, disillusionment with the role of the working class as the revolutionary agent, and a preference for decentralization and participatory democracy.", "mcq": {"stem": "Which concept does Heywood define as: \"The ____ comprises the thinkers and intellectual movements (prominent in the 1960s and early 1970s) that sought to revitalize socialist thought by developing a radical critique of advanced industrial society. The ____ rejected both \"", "options": ["Information society", "New Left", "Communitarianism", "Party government"], "answer": 1, "why": "New Left — The New Left comprises the thinkers and intellectual movements (prominent in the 1960s and early 1970s) that sought to revitalize socialist thought by developing a radical critique of advanced industr"}}, {"id": "hk103", "topic": "keyconcepts", "front": "Constitution", "back": "A constitution is, broadly, a set of rules, written and unwritten, that seek to establish the duties, powers and functions of the various"}, {"id": "hk104", "topic": "keyconcepts", "front": "Parliamentary sovereignty", "back": "Parliamentary sovereignty refers to the absolute and unlimited authority of a parliament or legislature, reflected in its ability to make, amend or repeal any law it wishes. Parliamentary sovereignty is usually seen as the central principle of the UK constitution, and results from (1) the absence of a codified constitution, (2) the supremacy of statute law over other forms of law, (3) the absence of rival legislatures, and (4) the convention that no parliament can bind its successors. Parliamentary sovereignty is a strictly legal, and not political, form of sovereignty (see p. 59)."}, {"id": "hk105", "topic": "keyconcepts", "front": "Constitutionalism", "back": "Constitutionalism, in a narrow sense, is the practice of limited government ensured by the existence of a constitution. Constitutionalism can, thus, be said to exist when government institutions and political processes are effectively constrained by constitutional rules. More broadly, constitutionalism is a set of political values and devices that fragment power, thereby creating a network of checks and balances. Examples of such devices include codified constitutions, bills of rights, the separation of powers, bicameralism and federalism.", "mcq": {"stem": "Which concept does Heywood define as: \"____, in a narrow sense, is the practice of limited government ensured by the existence of a constitution. ____ can, thus, be said to exist when government institutions and political processes are effectively const\"", "options": ["Legitimacy", "Constitutionalism", "Public interest", "New Left"], "answer": 1, "why": "Constitutionalism — Constitutionalism, in a narrow sense, is the practice of limited government ensured by the existence of a constitution. Constitutionalism can, thus, be said to exist when government institutions and p"}}, {"id": "hk106", "topic": "keyconcepts", "front": "Freedom", "back": "The term ‘freedom’ (or liberty) means, in its broadest sense, the ability to think or act as one wishes. A distinction is nevertheless often made between ‘negative’ and ‘positive’ liberty (Berlin, 1958). Negative freedom means non-interference: the absence of external constraints on the individual. Freedom, in this sense, is a private sphere within which individuals are ‘at liberty’ to act as they wish. Positive freedom is linked to the achievement of some identifiable goal or benefit, usually in the sense of personal development, self-realization or self-mastery."}, {"id": "hk107", "topic": "keyconcepts", "front": "Bill of rights", "back": "A bill of rights is a constitutional document that specifies the rights and freedoms of the individual, and so defines the legal extent of civil liberty (see p. 419). Entrenched bills of rights can be distinguished from statutory ones. An entrenched bill of rights is enshrined in ‘higher’ law and, thus, provides the basis for constitutional judicial review (see p. 312). A statutory bill of rights, or statute of rights, can be amended or repealed through the same processes as other statute laws. Unlike an entrenched bill of rights, it does not breach parliamentary sovereignty (see p. 298)."}, {"id": "hk108", "topic": "keyconcepts", "front": "Human rights", "back": "Human rights are rights to which people are entitled by virtue of being human; they are a modern and secular version of ‘natural rights’. Human rights are universal (in the sense that they belong to human beings everywhere, regardless of race, religion, gender and other differences), fundamental (in that a human being’s entitlement to them cannot be removed), indivisible (in that civic and political rights, and economic, social and cultural rights are interrelated and co-equal in importance) and absolute (in that, as the basic grounds for living a genuinely human life, they cannot be qualified).", "mcq": {"stem": "Which concept does Heywood define as: \"____ are ____ to which people are entitled by virtue of being ____; they are a modern and secular version of ‘natural ____’. ____ are universal (in the sense that they belong to ____ beings everywhere, regardless of ra\"", "options": ["Public choice", "Party democracy", "Human rights", "Bill of rights"], "answer": 2, "why": "Human rights — Human rights are rights to which people are entitled by virtue of being human; they are a modern and secular version of ‘natural rights’. Human rights are universal (in the sense that they belong to h"}}, {"id": "hk109", "topic": "keyconcepts", "front": "Rule of law", "back": "The rule of law is the principle that the law should ‘rule’, in the sense that it establishes a framework to which all conduct and behaviour must conform. This requirement applies equally to all the members of society, be they private citizens or government officials. As such, rule of law is a core liberal-democratic principle. In continental Europe, it has often been enshrined in the German concept of the Rechtsstaat, a state based on law. In the USA, the rule of law is closely linked to the status of the constitution as ‘higher’ law and the doctrine of ‘due process’. In the UK, it is grounded in common law and implies that a codified constitution is not needed.", "mcq": {"stem": "Which concept does Heywood define as: \"The ____ is the principle that the law should ‘____’, in the sense that it establishes a framework to which all conduct and behaviour must conform. This requirement applies equally to all the members of society, be they private citiz\"", "options": ["Rule of law", "Pre-emptive attack", "Separation of powers", "Social movement"], "answer": 0, "why": "Rule of law — The rule of law is the principle that the law should ‘rule’, in the sense that it establishes a framework to which all conduct and behaviour must conform. This requirement applies equally to all the m"}}, {"id": "hk110", "topic": "keyconcepts", "front": "Neutrality", "back": "Neutrality is the absence of any form of partisanship or commitment; it consists of a refusal to ‘take sides’. In international relations, neutrality is a legal condition through which a state declares its non-involvement in a conflict or war. As a"}, {"id": "hk111", "topic": "keyconcepts", "front": "Judicial review", "back": "The power of judicial review is the power of the judiciary to ‘review’, and possibly invalidate, the laws, decrees and the actions of other branches of government. In its classical sense, the principle stems from the existence of a codified constitution and allows the courts to strike down as ‘unconstitutional’ actions that are deemed to be incompatible with the constitution. A more modest form of judicial review, found in uncodified systems, is restricted to the review of executive actions in the light of ordinary law using the principle of ultra vires (beyond the powers) to determine whether a body has acted outside its powers."}, {"id": "hk112", "topic": "keyconcepts", "front": "Executive", "back": "In its broadest sense, the executive is the branch of government that is responsible for the implementation of laws and policies. More commonly, the term is now used in a narrower sense to describe the smaller body of decision-makers who take overall responsibility for the direction and coordination of government policy. This group of senior figures is often called the political executive (roughly equivalent to ‘the government of the day’, or ‘the administration’), as opposed to the official executive, or bureaucracy (p. 376). For ‘core’ executive, see p. 332.", "mcq": {"stem": "Which concept does Heywood define as: \"In its broadest sense, the ____ is the branch of government that is responsible for the implementation of laws and policies. More commonly, the term is now used in a narrower sense to describe the smaller body of decision-makers who ta\"", "options": ["Executive", "War", "Intersectionality", "Constitution"], "answer": 0, "why": "Executive — In its broadest sense, the executive is the branch of government that is responsible for the implementation of laws and policies. More commonly, the term is now used in a narrower sense to describe th"}}, {"id": "hk113", "topic": "keyconcepts", "front": "Heads of state", "back": "The head of state is the personal embodiment of the state’s power and authority. As the leading representative of the state, the head of state enjoys the highest status in the land. However, he or she is often a figure of essentially symbolic or formal significance, with real power residing in the hands of the head of government (a post that may or may not be held by the same person). Heads of state exercise a range of ceremonial powers and responsibilities, such as awarding honours, assenting to legislation and treaties, and receiving visiting heads of state. The head of state is usually either a president or monarch (see p. 324)."}, {"id": "hk114", "topic": "keyconcepts", "front": "Presidential government", "back": "A presidential system of government is characterized by a constitutional and political separation of powers between the legislative and executive branches of government. The principal features of a presidential system are: (1) the executive and the legislature are separately elected; (2) there is a formal separation of the personnel between the legislative and the executive branches; (3) the executive cannot be removed by the legislature (except, possibly, through impeachment); (4) the president or executive cannot ‘dissolve’ the legislature; and (5) executive authority is concentrated in the hands of the president."}, {"id": "hk115", "topic": "keyconcepts", "front": "Leadership", "back": "Leadership can be understood either as a pattern of behaviour, or as a personal quality. As a pattern of behaviour, leadership is the influence exerted by an individual or group over a larger body to"}, {"id": "hk116", "topic": "keyconcepts", "front": "Cult of personality", "back": "A cult of personality (or cult of leadership) is a propaganda device through which a political leader is portrayed as a heroic or Godlike figure. By treating the leader as the source of all political wisdom and an unfailing judge of the national interest, the cult implies that any form of criticism or opposition amounts to treachery or lunacy. Cults of personality have typically been"}, {"id": "hk117", "topic": "keyconcepts", "front": "Parliamentary government", "back": "A parliamentary system of government is one in which the government governs in and through the assembly or parliament, thereby ‘fusing’ the legislative and executive branches. The chief"}, {"id": "hk118", "topic": "keyconcepts", "front": "Separation of powers", "back": "The separation of powers is the principle that each of the three functions of government (legislation, execution and adjudication) should be entrusted to a separate branch of government (the legislature, the executive and the judiciary) (see Figure 15.2). Its purpose is to fragment government power in such a way as to defend liberty and keep tyranny at bay. In its formal sense, it demands independence, in that there should be no overlap of personnel between the branches. However, it also implies interdependence, in the form of shared powers to create a network of checks and balances."}, {"id": "hk119", "topic": "keyconcepts", "front": "Responsibility", "back": "Responsibility can be understood in two contrasting ways. First, it means to act in a sensible, reasonable, or morally correct fashion. A government may, thus, claim to be ‘responsible’ when it resists electoral pressures and risks unpopularity by pursuing policies designed interests. Second, long-term public responsibility means accountability or answerability. This implies the existence of a higher authority to which an individual or body is subject, and by which it can be controlled. Government is ‘responsible’ in this sense, if its actions are open to scrutiny and criticism, particularly by the assembly."}, {"id": "hk120", "topic": "keyconcepts", "front": "Policy", "back": "A policy, in a general sense, is a plan of action. To designate something as a ‘policy’ implies that a formal decision has been made, giving official sanction to a particular course of action. Public policy can therefore be seen as the formal or stated decisions of government bodies. However, policy is better understood as the linkage between intentions, actions and"}, {"id": "hk121", "topic": "keyconcepts", "front": "Ombudsman", "back": "Ombudsman is a Scandinavian word that has no exact English equivalent. An ombudsman is an officer of the state who is appointed to safeguard citizens’ rights in a particular sector and investigate allegations of maladministration (ranging from the improper use of powers to the failure to follow procedures) and simple incompetence. The role of an ombudsman is to supplement, not replace, normal avenues of complaints such as administrative courts or elected representatives. However, ombudsmen’s investigations and findings seldom have the force of law."}, {"id": "hk122", "topic": "keyconcepts", "front": "Utilitarianism", "back": "Utilitarianism is a moral philosophy that was developed by Jeremy Bentham (see p. 97) and James Mill (1773–1836). It claimed to propound a reliable, even scientific, ethical theory by equating ‘good’ with pleasure or happiness, and ‘evil’ with pain or unhappiness. Individuals are thus assumed to act so as to maximize pleasure and minimize pain, these being calculated in terms of utility, or use value. A principle of general or social utility can be used to evaluate laws, institutions and political systems in the form of ‘the greatest happiness for the greatest number’.", "mcq": {"stem": "Which concept does Heywood define as: \"____ is a moral philosophy that was developed by Jeremy Bentham (see p. 97) and James Mill (1773–1836). It claimed to propound a reliable, even scientific, ethical theory by equating ‘good’ with pleasure or happiness, and ‘evil’ w\"", "options": ["Political participation", "Mandate", "Utilitarianism", "Postcolonialism"], "answer": 2, "why": "Utilitarianism — Utilitarianism is a moral philosophy that was developed by Jeremy Bentham (see p. 97) and James Mill (1773–1836). It claimed to propound a reliable, even scientific, ethical theory by equating ‘good’ "}}, {"id": "hk123", "topic": "keyconcepts", "front": "Ethnocentrism", "back": "Ethnocentrism has two related meanings. First, it refers to a personality type characterized by a rigid, implicitly authoritarian belief in the superiority of his or her own group or people. Ethnocentrism in this sense overlaps with racialism (see p. 137). Second, it refers to a mode of understanding in which the actions and intentions of other groups or peoples are understood through the application of values and theories drawn from the observer’s own culture. In this sense, ethnocentrism is a (typically unconscious) bias that results from a failure to appreciate the significance of cultural differentiation."}, {"id": "hk124", "topic": "keyconcepts", "front": "Policy network", "back": "A policy network (or policy community) is a systematic set of relationships between political actors who share a common"}, {"id": "hk125", "topic": "keyconcepts", "front": "Bureaucracy", "back": "Bureaucracy (literally, ‘rule by officials’) is, in everyday language, a pejorative term meaning pointless administrative routine, or ‘red tape’. In the social sciences, the concept of bureaucracy refers to phenomena as different as rule by non-elected officials, the process of public administration and a rational mode of organization. According to Max Weber (see p. 81), bureaucracy is characterized by rationality, rule-governed behaviour and impersonal authority. In the field of comparative government, the"}, {"id": "hk126", "topic": "keyconcepts", "front": "Administration", "back": "The term administration is used in a number of ways. It can be used to refer collectively to the senior personnel in the executive branch, as in the ‘Obama administration’. More generally, it"}, {"id": "hk127", "topic": "keyconcepts", "front": "Corruption", "back": "Corruption, in a general sense, is a condition of depravity or moral defilement. Power is thus said to corrupt, in that it breeds an appetite for domination and insensitivity to the sufferings of others. More specifically, corruption is a quasi-legal term meaning a person’s failure to carry out his or her ‘proper’ or public responsibilities due to the pursuit of private gain. In most cases, corruption has a material or narrowly financial character, its most common political manifestations being bribery or ‘sleaze’. Political corruption can, broadly, be associated with the abuse of office."}, {"id": "hk128", "topic": "keyconcepts", "front": "New public management", "back": "New public management (NPM) stands broadly for the use of private sector management techniques in government and for the transfer of government functions to private bodies. The philosophy of NPM is that government should ‘steer’ (decide policy) while private bodies should ‘row’ (deliver services), and that public bodies should be imbued with the ‘entrepreneurial spirit’. Examples of the latter include the use of performancerelated pay, short-term contracts and open recruitment strategies. NPM is based on assumptions about the inherent inefficiency and unresponsiveness of public bodies."}, {"id": "hk129", "topic": "keyconcepts", "front": "Departmentalism", "back": "Departmentalism to centrifugal pressures within a governmental structure that strengthen the identity of individual departments and agencies. Agencies are thus able to pursue their own separate interests, and resist both political control and broader administrative disciplines. The distinctive culture of a government agency is shaped by factors such as its policy responsibilities, the collective interests of its body of officials, and the interests of the client groups that it serves. Departmentalism also operates through the tendency of ministers and senior officials to ‘go native’, by being absorbed into the department’s"}, {"id": "hk130", "topic": "keyconcepts", "front": "Ministerial responsibility", "back": "The doctrine of ministerial responsibility (‘individual’ responsibility) defines the relationship between ministers and their departments. The doctrine is observed in most parliamentary systems, and has two key features. First, ministers are responsible for the acts and omissions of their departments, maintaining the fiction that ministers themselves make all the decisions taken in their name. Second, ministers are accountable to the assembly, in the sense that they are answerable for anything that goes on in their departments, and are removable in the event of mistakes made", "mcq": {"stem": "Which concept does Heywood define as: \"The doctrine of ____ (‘individual’ ____) defines the relationship between ministers and their departments. The doctrine is observed in most parliamentary systems, and has two key features. First, ministers ar\"", "options": ["Ministerial responsibility", "Multilateralism", "Leadership", "Islamism"], "answer": 0, "why": "Ministerial responsibility — The doctrine of ministerial responsibility (‘individual’ responsibility) defines the relationship between ministers and their departments. The doctrine is observed in most parliamentary systems, and h"}}, {"id": "hk131", "topic": "keyconcepts", "front": "Geopolitics", "back": "Geopolitics is an approach to foreign policy analysis that understands the actions, relationships and significance of states in terms of geographical factors such as location, climate, natural resources, physical terrain and population. Key exponents of geopolitics include Alfred Mahan (1840–1914), who argued that the state that controls the seas would control world politics, and Halford Mackinder (1861–1947), who suggested that control of the land mass between Germany and central Siberia is the key to controlling world politics. The advance of globalization is sometimes seen to have made geopolitics obsolete."}, {"id": "hk132", "topic": "keyconcepts", "front": "Multilevel governance", "back": "Multilevel governance is a complex policy process in which political authority is distributed at different levels of territorial aggregation. The ‘vertical’ conception of multilevel governance takes account of the interdependence of actors in the policy process at subnational, national and transnational levels, creating a fluid process of negotiation. Much of the complexity of multilevel governance derives from ‘horizontal’ developments such as the growth of relationships between states and non-state actors, and the emergence of new forms of public-private partnership."}, {"id": "hk133", "topic": "keyconcepts", "front": "Federalism", "back": "Federalism (from the Latin foedus, meaning ‘pact’, or ‘covenant’) usually refers to legal and political structures that distribute power territorially within a state. Nevertheless, in accordance with its original meaning, it has been taken to imply reciprocity or mutuality (Proudhon), or, in the writings of Alexander Hamilton and James Madison (see p. 351), to be part of a broader ideology of pluralism. As a political form, however, federalism requires the existence of two distinct levels of government, neither of which is legally or politically subordinate to the other. Its central feature is therefore shared sovereignty.", "mcq": {"stem": "Which concept does Heywood define as: \"____ (from the Latin foedus, meaning ‘pact’, or ‘covenant’) usually refers to legal and political structures that distribute power territorially within a state. Nevertheless, in accordance with its original meaning, it has been taken \"", "options": ["Political party", "Faction, factionalism", "Federalism", "Leadership"], "answer": 2, "why": "Federalism — Federalism (from the Latin foedus, meaning ‘pact’, or ‘covenant’) usually refers to legal and political structures that distribute power territorially within a state. Nevertheless, in accordance with "}}, {"id": "hk134", "topic": "keyconcepts", "front": "Devolution", "back": "Devolution is the transfer of power from central government to subordinate regional institutions. Devolved bodies thus constitute an intermediate tier of government between central and local government. However, devolution differs from federalism in that devolved bodies have no share in sovereignty. In administrative devolution, regional institutions implement policies that are decided elsewhere. In legislative devolution (sometimes called ‘home rule’), devolution involves the establishment of elected regional assemblies that have policy-making responsibilities."}, {"id": "hk135", "topic": "keyconcepts", "front": "Regionalism", "back": "Regionalism is the theory or practice of coordinating social, economic and political activities within a geographical region, which may either be part of a state (subnational regionalism) or comprise a number of states (transnational regionalism). On an institutional level, regionalism involves the growth of norms, rules and formal structures through which coordination is brought about. On an affective level, regionalism implies a realignment of political identities and loyalties from the state to the region."}, {"id": "hk136", "topic": "keyconcepts", "front": "Inter-governmentalism, supranationalism", "back": "Intergovernmentalism refers to any form of interaction between states that takes place on the basis of sovereign independence. This includes treaties and alliances as well as leagues and confederations. Sovereignty is preserved through a process of unanimous decision-making that gives each state a veto over vital national issues.", "mcq": {"stem": "Which concept does Heywood define as: \"Intergovernmentalism refers to any form of interaction between states that takes place on the basis of sovereign independence. This includes treaties and alliances as well as leagues and confederations. Sovereignty is preserved through a pr\"", "options": ["Inter-governmentalism, supranationalism", "Neo-Marxism", "Constructivism", "Coalition"], "answer": 0, "why": "Inter-governmentalism, supranationalism — Intergovernmentalism refers to any form of interaction between states that takes place on the basis of sovereign independence. This includes treaties and alliances as well as leagues and confederation"}}, {"id": "hk137", "topic": "keyconcepts", "front": "Order", "back": "As a political principle, order refers to stable and predictable forms of behaviour and, above all, to those that safeguard personal security. Nevertheless, order has two very different political associations. Most commonly, it is linked with political authority and is thought to be achievable only if imposed ‘from above’ through a system of law. ‘Law and order’ thus become a"}, {"id": "hk138", "topic": "keyconcepts", "front": "Crime", "back": "A crime is a breach of criminal law, which is law that establishes the relationship between the state and the individual. Criminals (persons convicted of a crime) are usually seen as being motivated by self-gain of some kind, rather than broader political or moral considerations, as in the case of civil disobedience (see p. 285). However, the causes of, and remedies for, crime are hotly contested. The general divide is between those who blame individual corruption and place their faith in punishment, and those who blame deprivation and thus look to reduce crime through social reform.", "mcq": {"stem": "Which concept does Heywood define as: \"A ____ is a breach of criminal law, which is law that establishes the relationship between the state and the individual. Criminals (persons convicted of a ____) are usually seen as being motivated by self-gain of some kind, rather than br\"", "options": ["Democratization", "Human rights", "Administration", "Crime"], "answer": 3, "why": "Crime — A crime is a breach of criminal law, which is law that establishes the relationship between the state and the individual. Criminals (persons convicted of a crime) are usually seen as being motivated b"}}, {"id": "hk139", "topic": "keyconcepts", "front": "Civil liberty", "back": "Civil liberty refers to a private sphere of existence that belongs to the citizen, not the state. Civil liberty therefore encompasses a range of ‘negative’ rights, usually rooted in the doctrine of human rights, which demand non-interference on the part of government. The classic civil liberties are usually thought to include the rights to freedom of speech, freedom of the press, freedom of religion and conscience, freedom of movement and freedom of association. These key freedoms are generally seen as vital to the functioning of liberal-democratic societies."}, {"id": "hk140", "topic": "keyconcepts", "front": "Realism", "back": "Realism is a theory of international politics whose core theme can be summed up as: egoism plus anarchy equals power politics. Some, nevertheless, argue that this formulation betrays a basic theoretical fault line within realism, dividing it into two schools of thought. Classical realism explains power politics largely in terms of human selfishness or egoism, suggesting that, as states prioritize self-interest and survival, the international realm tends towards unending conflict. Neorealism (or structural realism) explains power politics in terms of the structural dynamics of an"}, {"id": "hk141", "topic": "keyconcepts", "front": "Collective security", "back": "The idea of collective security, simply stated, is that aggression can best be resisted by united action taken by a number of states. It suggests that states, as long as they pledge themselves to"}, {"id": "hk142", "topic": "keyconcepts", "front": "War", "back": "War is a condition of armed conflict between two or more parties (usually states). The emergence of the modern form of war as an organized and goal-directed activity stems from the development of the European state-system in the early modern period. War has a formal or quasi-legal character, in that the declaration of a state of war need not necessarily be accompanied by the outbreak of hostilities. In the post-Cold War era it has been common to refer to ‘new’ wars. These have been characterized, variously, by intra-state ethnic conflict, the use of advanced military technology, and the use of terrorist and guerrilla strategies."}, {"id": "hk143", "topic": "keyconcepts", "front": "Terrorism", "back": "Terrorism, in its broadest sense, is a form of political violence that aims to achieve its objectives by creating a climate of fear, apprehension and uncertainty. The most common forms of terrorist action include assassinations, bombings, hostage seizures and plane hijacks, although 9/11 and the advent of terrorism with a global reach has threatened to redefine the phenomenon. The term is highly pejorative and tends to be used selectively (one person’s terrorist is another’s freedom fighter). Often portrayed as a specifically anti-government activity, some portray the use by governments of terror against their own or other populations as ‘state terrorism’."}, {"id": "hk144", "topic": "keyconcepts", "front": "Human security", "back": "Human security refers to the security of individuals, rather than of states. As such, it embraces the notions of both ‘freedom from fear’ and ‘freedom from want’. Human security, nevertheless, has a variety of dimensions. These include economic security (having an assured basic income), food security (access to basic food), health security (protection from disease and unhealthy lifestyles), environmental security (protection from human-induced"}, {"id": "hk145", "topic": "keyconcepts", "front": "Pre-emptive attack", "back": "A pre-emptive attack (or preventative war) is military action that is designed to forestall or prevent likely future aggression – ‘getting your retaliation in first’. The attractions of pre-emptive attack include that greater destruction may be avoided and that military action is taken before a potential aggressor becomes too strong to be challenged. Its drawbacks include that calculations about future actions or threats may be flawed and that the notion may simply be a cloak for aggression. Pre-emptive attack is almost certainly illegal under the UN Charter, which authorizes war only in the case of self-defence."}, {"id": "hk146", "topic": "keyconcepts", "front": "Imperialism", "back": "Imperialism is, broadly, the policy of extending the power or rule of a state beyond its borders. In its earliest usage, imperialism was an ideology of conquest and expansion, designed either to extend dynastic authority or to further nationalist ambitions. The term is now more commonly used to describe any form of external domination, and includes both the imposition of direct political control through colonialism (see p. 144) and economic exploitation in the absence of political rule, or neocolonialism. Marxists and realists disagree over whether imperialism is essentially an economic or a political phenomenon."}, {"id": "hk147", "topic": "keyconcepts", "front": "Global governance", "back": "Global governance refers to a broad, dynamic and complex process of interactive decision-making at the global level, informal mechanisms, as well as involving governmental and non-governmental bodies. Global governance is institutional frameworks and decision-making mechanisms operate in different issue areas), (states and national governments retain considerable influence within the global governance system) and mixed actor (the public/private divide is blurred through the involvement of NGOs, TNCs, and the like)."}, {"id": "hk148", "topic": "keyconcepts", "front": "Interdependence", "back": "Interdependence refers to a relationship between two parties in which each is affected by decisions that are taken by the other. Interdependence implies mutual influence, even a rough equality between the parties in question, usually arising from a sense of mutual vulnerability. Keohane and Nye (1977) advanced the idea of ‘complex interdependence’ as an alternative to the realist model of international politics. This highlights the extent to which (1) states have ceased to be autonomous international actors; (2) economic and other issues have become more prominent in world affairs; and (3) military force has become a less reliable and less important policy option."}, {"id": "hk149", "topic": "keyconcepts", "front": "Multilateralism", "back": "Multilateralism can broadly be defined as a process that coordinates behaviour amongst three or more countries on the basis of generalized principles of conduct (Ruggie, 1992). For a process to be genuinely multilateral, it must conform to three principles. These principles are non-discrimination (all participating countries must be treated alike), indivisibility (participating countries must behave as if they were a single entity, as in collective security (see p. 426)) and diffuse reciprocity (obligations amongst countries must have a general and enduring character, rather than being examples of one-off cooperation).", "mcq": {"stem": "Which concept does Heywood define as: \"____ can broadly be defined as a process that coordinates behaviour amongst three or more countries on the basis of generalized principles of conduct (Ruggie, 1992). For a process to be genuinely multilateral, it must conform to \"", "options": ["Democratization", "Regionalism", "Order", "Multilateralism"], "answer": 3, "why": "Multilateralism — Multilateralism can broadly be defined as a process that coordinates behaviour amongst three or more countries on the basis of generalized principles of conduct (Ruggie, 1992). For a process to be gen"}}, {"id": "hk150", "topic": "keyconcepts", "front": "Free trade", "back": "Free trade is a system of trading between states that is not restricted by tariffs or other forms of protectionism. In line with the theory of ‘comparative advantage’, liberals argue that international trade benefits all countries that participate in it, not least through greater specialization. The political case for free trade is that, in deepening economic interdependence and fostering international exchange, it makes war less likely and, perhaps, impossible. Critics point out that free trade widens economic inequalities by giving dominant powers access to the markets of weak states, while having little to fear themselves from foreign competition.", "mcq": {"stem": "Which concept does Heywood define as: \"____ is a system of trading between states that is not restricted by tariffs or other forms of protectionism. In line with the theory of ‘comparative advantage’, liberals argue that international ____ benefits all countries that part\"", "options": ["Communism", "Utilitarianism", "Free trade", "Citizenship"], "answer": 2, "why": "Free trade — Free trade is a system of trading between states that is not restricted by tariffs or other forms of protectionism. In line with the theory of ‘comparative advantage’, liberals argue that internationa"}}, {"id": "hk151", "topic": "keyconcepts", "front": "Anti-politics", "back": "‘Anti-politics’ refers to a rejection of, and/or alienation from, conventional politicians and political processes, especially ‘mainstream’ political parties and established representative mechanisms. One manifestation of anti-politics is a decline in political engagement, as citizens turn away from politics and seemingly retreat into private existence. However, anti-politics has also spawned new forms of politics, which, in various ways, articulate disillusionment with established political structures and offer more ‘authentic’ alternatives.", "mcq": {"stem": "Which concept does Heywood define as: \"‘____’ refers to a rejection of, and/or alienation from, conventional politicians and political processes, especially ‘mainstream’ political parties and established representative mechanisms. One manifestation of ____ is a\"", "options": ["Status", "Constitution", "Anti-politics", "Race"], "answer": 2, "why": "Anti-politics — ‘Anti-politics’ refers to a rejection of, and/or alienation from, conventional politicians and political processes, especially ‘mainstream’ political parties and established representative mechanisms."}}, {"id": "hk152", "topic": "keyconcepts", "front": "Political participation", "back": "Political participation is the act of taking part in the formulation, passage or implementation of public policies. However, political participation takes place at very different levels. Citizens have been divided into ‘apathetics’ (who do not engage in formal politics), ‘spectators’ (who rarely participate beyond voting) and ‘gladiators’ (who fight political battles) (Milbrath and Goel, 1977). Conventional participation comprises a number of ‘modes’, notably voting, party campaigning, communal activity and contacting a representative or official about a particular personal matter.", "mcq": {"stem": "Which concept does Heywood define as: \"____ is the act of taking part in the formulation, passage or implementation of public policies. However, ____ takes place at very different levels. Citizens have been divided into ‘apathetics’ (who do \"", "options": ["Political participation", "Bureaucracy", "Pluralism", "Policy"], "answer": 0, "why": "Political participation — Political participation is the act of taking part in the formulation, passage or implementation of public policies. However, political participation takes place at very different levels. Citizens have"}}, {"id": "hk153", "topic": "keyconcepts", "front": "Trust", "back": "Trust means faith, a reliance on, or confidence in, the honesty, worth and reliability of another person. It is therefore based on expectations of others’ future actions. Political trust consists in the level of confidence people have in one another in discharging their civic responsibilities and, crucially, the confidence citizens have that politicians generally, and leaders in particular, will keep their promises and carry out their public duties honestly and fairly. In liberal theory, trust arises through voluntary contracts that we uphold through mutual self-interest. In communitarian theory, trust is grounded in a sense of social duty and a common morality.", "mcq": {"stem": "Which concept does Heywood define as: \"____ means faith, a reliance on, or confidence in, the honesty, worth and reliability of another person. It is therefore based on expectations of others’ future actions. Political ____ consists in the level of confidence people have in on\"", "options": ["Political party", "Trust", "Democratization", "Individualism"], "answer": 1, "why": "Trust — Trust means faith, a reliance on, or confidence in, the honesty, worth and reliability of another person. It is therefore based on expectations of others’ future actions. Political trust consists in t"}}, {"id": "hk154", "topic": "keyconcepts", "front": "Citizenship", "back": "Citizenship is a relationship between the individual and the state in which the two are bound together by reciprocal rights and duties. Citizens differ from subjects and aliens in that they are full members of their political community or state by virtue of their possession of basic rights. Liberals advance the principle of a ‘citizenship of rights’ that stresses private entitlement and the status of the individual as an autonomous actor. Communitarians, in contrast, advance the principle of a ‘citizenship of duty’ that highlights the role of the state as a moral agency and the importance of community or social existence."}, {"id": "hk155", "topic": "keyconcepts", "front": "Equality", "back": "Equality is the principle of uniform apportionment, but does not imply sameness. The term ‘equality’ has differing implications, depending on what is being apportioned. Formal equality means the equal distribution of legal and political rights, and is usually based on the assumption that human beings are ‘born’ equal. Equality of opportunity means that everyone has the same starting-point, or equal life chances, but may justify social inequality because talent and the capacity for hard work are unequally distributed. Equality of outcome refers to an equal distribution of income, wealth and other social goods."}, {"id": "hps1", "topic": "polsum", "front": "Politics Ch.1 — What is Politics?", "back": "• Politics is the activity through which people make, preserve and amend the general rules under which they live. As such, it is an essentially social activity, in extric ably linked, on the one hand, to the existence of diversity and conflict, and, on the other, to a willingness to cooperate and act collectively. Politics is better seen as a search for conflict resolution than as its achievement, as not all conflicts are, or can be, resolved.\n• Politics has been understood differently by different thinkers and within different traditions. Politics has been viewed as the art of government or as ‘what concerns the state’; as the conduct and management of public affairs; as the resolution of conflict through debate and compromise; and as the production, distribution and use of resources in the course of social existence.\n• There is considerable debate about the realm of ‘the political’. Conventionally, politics has narrowly been seen as embracing institutions and actors operating in a ‘public’ sphere concerned with the collective organization of social existence. However, when politics is understood in terms of power-structured relationships, it may be seen to operate in the ‘private’ sphere as well.\n• A variety of approaches has been adopted in the study of politics as an academic discipline. These include political philosophy, or the analysis of normative theory, and an empirical tradition particularly concerned with the study of institutions and structures, as well as behavioural analysis, rational-choice theory, so-called ‘new’ institutionalism and a variety of critical approaches.\n• Concepts, models and theories are the tools of political analysis, providing the building blocks of knowledge. However, they are only analytical devices. Although they help to advance understanding, they are more rounded and coherent than the unshapely and complex realities they seek to describe. Ultimately, all political and social enquiry is conducted within a particular intellectual framework or ideological paradigm.\n• A distinction has traditionally been drawn between the domestic and international realms of politics, reflecting differences between what happens within the state and what occurs in relations between states. This domestic/international divide has helped to sustain a disciplinary distinction between political science and international relations. However, globalization and the advent of an interdependent world has cast significant doubt upon the viability of these distinctions."}, {"id": "hps2", "topic": "polsum", "front": "Politics Ch.2 — Political Ideas and Ideologies", "back": "• Ideology is a controversial political term that has often carried pejorative implications. In the social-scientific sense, a political ideology is a more or less coherent set of ideas that provides a basis for organized political action. Its central features are an account of existing power relationships, a model of a desired future, and an outline of how political change can and should be brought about.\n• Ideologies link political theory with political practice. On one level, ideologies resemble political philosophies, in that they constitute a collection of values, theories and doctrines; that is, a distinctive world-view. On another level, however, they take the form of broad political movements, and are articulated through the activities of political leaders, parties and groups.\n• Every ideology can be associated with a characteristic set of principles and ideas. Although these ideas ‘hang together’, in the sense that they interlock in distinctive ways, they are systematic or coherent only in a relative sense. All ideologies thus embody a range of rival traditions and internal tensions. Conflict within ideologies is thus sometimes more passionate than that between ideologies.\n• Ideologies are by no means hermetically sealed and unchanging systems of thought. They overlap with one another at a number of points, and they sometimes have shared concerns and a common vocabulary. They are also always subject to political or intellectual renewal, both because they interact with, and influence the development of, other ideologies, and because they change over time as they are applied to changing historical circumstances.\n• The significance of particular ideologies rises and falls in relation to the ideology’s relevance to political, social and economic circumstances, and its capacity for theoretical innovation. Development during the twentieth century and beyond have forced major ideo logies such as liberalism, conservatism and socialism to re-examine their traditional principles. Since around the 1960s, the ideological landscape has been transformed by the emergence of so-called ‘new’ ideologies, such as feminism, green politics and cosmopolitanism, and by a growing recognition of the ideological significance of a range of non-western ideas and theories."}, {"id": "hps3", "topic": "polsum", "front": "Politics Ch.3 — Politics and the State", "back": "• The state is a political association that exercises sovereign jurisdiction within defined territorial borders. As a system of centralized rule that emerged in Europe between the seventeenth and nineteenth centuries, and succeeded in subordinating all other institutions and groups, the state came to dominate political life in all its forms. The spread of the European model of the state to other lands and continents has seen the state become the universal form of political organization around the world\n• There are a number of rival theories of the state. Pluralists hold that the state is a neutral body that arbitrates between the competing interests of society. Marxists argue that the state maintains the class system by either oppressing subordinate classes or ameliorating class conflict. The New Right portrays the state as a self-serving monster that is intent on expansion and aggrandizement. Radical feminists point to patriarchal biases within the state that support a system of male power.\n• Those who support the state see it either as a means of defending the individual from the encroachments of fellow citizens, or as a mechanism through which collect ive action can be organized. Critics, however, tend to suggest that the state reflects either the interests of dominant social groups, or interests that are separate from, and antithetical to, society.\n• States have fulfilled very different roles. Minimal states merely lay down the conditions for orderly existence. Developmental states attempt to promote growth and economic development. Social-democratic states aim to rectify the imbalances and injustices of a market economy. Collectivized states exert control over the entir ety of economic life. Totalitarian states bring about all-encompassing politiciz ation and, in effect, extinguish civil society. Religious states are used as instruments of moral and spiritual renewal.\n• Modern debate about the state is dominated by talk of retreat, decline and even collapse. The decline of the state is often explained in terms of the impact of globalization, the rise of non-state actors and the growing importance of international organizations. Most dramatically, some postcolonial states have collapsed, or barely function as states, having a negligible capacity to maintain order. However, the retreat of the state may have been exaggerated and, in relation to security and economic development in particular, the state may be reviving in importance."}, {"id": "hps4", "topic": "polsum", "front": "Politics Ch.4 — Democracy and Legitimacy", "back": "• Legitimacy maintains political stability because it establishes a regime’s right to rule, and so underpins the regime’s authority over its people. Legitimacy may be based on traditional, charismatic or legal–rational authority. Nevertheless, structural imbalances in modern society may make it increasingly difficult to maintain legitimacy. Legitimation crises may arise from the conflict between the pressure for social and economic interventionism generated by democracy on the one hand, and the pressure generated by market economy on the other.\n• Democratic legitimacy is now widely accepted as the only meaningful form of legitimacy. However, it has been suggested that economic and other factors may be more effective than democracy in maintaining legitimacy, that evidence of growing political disengagement in mature democracies indicates that democracy’s capacity to deliver legitimacy is declining, and that non-democratic regimes may enjoy at least a measure of legitimacy.\n• There are a number of rival models of democracy, each offering its own version of popular rule. Classical democracy, which is based on the political system of Ancient Athens, is defended on the grounds that it alone guarantees government by the people. Protective democracy gives citizens the greatest scope to live their lives as they choose. Developmental democracy has the virtue that, in extending participation, it widens liberty and fosters personal growth. People’s democracy aims to achieve economic emancipation, rather than merely the extension of political rights.\n• There is considerable controversy about how liberal-democratic systems work in practice. Pluralists praise the system’s capacity to guarantee popular responsiveness and public accountability. Elitists highlight the tendency for political power to be concentrated in the hands of a privileged minority. Corporatists draw attention to the incorporation of groups into government. The New Right focuses on the dangers of ‘democratic overload’. And Marxists point to tensions between democracy and capitalism.\n• Growing global interdependence has stimulated interest in whether democracy can, and should, operate at a global or cosmopolitan level, either through the construction of some kind of world parliament, or through a global civil society. However, major obstacles stand in the way of cosmopolitan democracy, with many rejecting the idea as unfeasible in principle."}, {"id": "hps5", "topic": "polsum", "front": "Politics Ch.5 — Nations and Nationalism", "back": "• Nations are defined by a combination of cultural and political factors. Culturally, they are groups of people who are bound together by a common language, religion, history and traditions. Ultimately, however, nations define themselves through the existence of a shared civic consciousness, classically expressed as the desire to achieve or maintain statehood.\n• Distinctive cultural and political forms of nationalism can be identified. Cultural nationalism emphasizes the regeneration of the nation as a distinctive civilization on the basis of a belief in the nation as a unique, historical and organic whole. Political nationalism, on the other hand, recognizes the nation as a discrete political com munity, and is thus linked with ideas such as sovereignty and self-determination.\n• Some political thinkers portray nationalism as a modern phenomenon associated with industrialization and the rise of democracy, while others trace it back to premodern ethnic loyalties and identities. The character of nationalism has varied considerably, and has been influenced by both the historical circumstances in which it has arisen and the political causes to which it has been attached.\n• There have been a number of contrasting manifestations of political nationalism. Liberal nationalism is based on a belief in a universal right to self-determination. Conservative nationalism values the capacity of national patriotism to deliver social cohesion and political unity. Expansionist nationalism is a vehicle for aggression and imperial conquest. Anticolonial nationalism is associated with the struggle for national liberation, often fused with the quest for social development.\n• The most widely recognized form of political organization worldwide is the nation-state, which is often seen as the sole legitimate unit of political rule. Its strength is that it offers the prospect of both cultural cohesion and political unity, thus allowing those who share a common cultural or ethnic identity to exercise the right to independence and self-government.\n• The nation-state now confronts a number of challenges. Nation-states have been subject to centrifugal pressures generated by the growth in ethnic politics. Extern ally, they have confronted challenges from the growing power of supranational bodies, the advance of economic and cultural globalization, and the need to find international solutions to the environmental crisis."}, {"id": "hps6", "topic": "polsum", "front": "Politics Ch.6 — Political Economy and Globalization", "back": "• Political economy, in its broadest sense, refers to the interplay between politics and economics. As a topic, political economy encompasses a range of thinking about the relationship between states and markets. As a method, it stands for the use of approaches developed within economics to analyse politics. Distinctive statecentric, classical/neoclassical and Marxist approaches to political economy can be identified.\n• Capitalism is a system of generalized commodity production in which wealth is owned privately and economic life is organized according to market principles. Enterprise capitalism, social capitalism and state capitalism nevertheless differ in relation to the balance within them between the market and the state.\n• State socialism, or communism, was the major twentieth-century alternative to capitalism, but it ultimately failed to rival capitalism in terms of producing modern consumer goods and delivering widespread prosperity, so leading to experiments in market socialism. Green economics calls for the economy to be restructured around the principles of ecological balance and sustainability.\n• Globalization is a complex web of interconnectedness that means that our lives are increasingly shaped by decisions and actions taken at a distance from ourselves. Economic globalization reflects the increase in transnational flows of capital and goods, destroying the idea of economic sovereignty. Cultural globalization is a homogenizing force, whereas political globalization is linked to the growing importance of international organizations.\n• Economic globalization has gone hand-in-hand with neoliberalism, so much so that they are often considered to be a single phenomenon, neoliberal globalization. Debate has raged over the implications of the Crash of 2007–09 for neoliberal globalization, but other key consequences of the Crash include massive indebtedness in many developed economies and a major shift in the global balance of economic power."}, {"id": "hps7", "topic": "polsum", "front": "Politics Ch.7 — Politics, Society and Identity", "back": "• Societies are characterized by regular patterns of social interaction. However, the ‘thick’ social connectedness of close bonds and fixed allegiances is giving way to the ‘thin’ connectedness of more fluid, individualized social arrangements. This reflects, in large part, the transition from industrial to so-called post-industrial society, and, particularly, the declining importance of social class.\n• Post-industrialism is characterized, amongst other things, by an increasing emphasis on knowledge and information generally, with the advent of the internet and the wider use of computer-based technologies having given rise to the ‘information society’. Not only do information societies connect more people to more other people, but the nature of those connections has also changed, especially through the development of looser and more diffuse networks.\n• At the heart of the trend towards the ‘thinning’ of social connectedness is the rise of individualism. Individualism was a child of industrial capitalism, but it has been boosted by a growing ethic of materialism and consumerism, given greater prominence, from the 1980s onwards, by the wider influence of neoliberal or free-market thinking. However, the spread of individualism may weaken community and people’s sense of social belonging, a trend that may be particularly evident in the English-speaking world.\n• The rise of identity politics has been evident in the growing recognition of cultural and other forms of difference, especially providing a vehicle through which groups can challenge marginalization by adopting a more positive and assertive sense of identity. Nevertheless, identity politics does not have a settled political character and it has been shaped around many principles, the most important of which are race and ethnicity, gender, religion and culture.\n• Attempts to regenerate personal and social identity have given rise to new, and sometimes more radical, forms of politics. These include forms of ethnic assertiveness, often associated with black nationalism; second-wave feminism and a stronger emphasis on issues of gender equality and gender difference; religious revivalism, commonly expressed through fundamentalist movements, especially in Islam; and multiculturalism and the ‘celebration’ of cultural diversity."}, {"id": "hps8", "topic": "polsum", "front": "Politics Ch.8 — Political Culture and the Media", "back": "• There are rival theories of the media’s political impact. Pluralists portray the media as an ideological marketplace that enhances debate and electoral choice. However, others highlight systematic media bias, stemming either from links between the media and economic and social elites, or from the personal views of the editor, broadcasters and journalists. The market model suggests that the media output simply reflects the views of the general public.\n• The media play a key democratic role in four senses. They promote political education by providing a public forum for meaningful and serious debate; act as a public watchdog, exposing abuses of power; tend, through the ‘new’ media in particular, to widen access to information and facilitate political activism; and serve as a mechanism through which democracy takes place. Concerns have, nevertheless, been raised about the political views of the media, their lack of democratic accountability and their over-close links to government.\n• The mass media has affected governance in various ways. These include that they have transformed political leadership and, in the process, reapportioned government power. They have also changed the political culture and, some have warned, contributed to declining respect for politicians and politics in general. Finally, the growing influence of the media is evident in a policy-making process that has to react more rapidly and make sense of a vast amount of information.\n• The use of new media has been defended on the grounds that it facilitates political participation, widens citizen’s access to information, and stimulates new forms of decentralized political activism. Critics, nevertheless, warn against the growth of a consumerist form of citizenship and doubt the value of ‘technological fixes’.\n• The role of the media in promoting globalization has provoked particular controversy. Some have warned against ‘media imperialism’, drawing attention to the media’s role in spreading a global culture of consumerism and in strengthening ‘westernization or ‘Americanization’. However, cultural exchange facilitated by the mass media is by no means always a ‘top-down’ or one-way process.\n• Governments have sometimes used the media as a propaganda machine. This involves direct control over all kinds of media output to ensure that only ‘official’ views and ideas are distributed. Classic examples of this can be found in Nazi Germany and in communist regimes, but there has been a growing tendency for democratic regimes to engage in news management and the politics of ‘spin’, providing evidence of a symbiotic relationship that tends to develop between government and the media."}, {"id": "hps9", "topic": "polsum", "front": "Politics Ch.9 — Representation, Elections and Voting", "back": "• Representation is a relationship in which an individual or group stands for, or acts on behalf of, a larger body of people. This may be achieved through the exercise of wisdom by an educated elite, through guidance or instructions given to a delegate, through the winning of a popular mandate, or through representatives being drawn from the groups they represent.\n• In modern politics, representation is invariably linked with elections. Elections may not be a sufficient condition for political representation, but are certainly a necessary condition. For elections to serve representative purposes, however, they must be competitive, free and fair, and conducted on the basis of universal adult suffrage.\n• Elections have a variety of functions. On the one hand, they have ‘bottom-up’ functions, such as political recruitment, representation, making government and influencing policy. On the other hand, radical theorists emphasize their ‘top-down’ functions, which include that they build legitimacy, shape public opinion and help to strengthen elites.\n• Electoral systems are often classified as either majoritarian systems or proportional systems. In majoritarian systems, large parties typically win a higher proportion of seats than votes, thereby increasing the chances of single-party government. In proportional systems, there is an equal (or at least, more equal) relationship between the percentages of seats and votes won, increasing the likelihood of coalition government.\n• Majoritarian systems are usually defended on the grounds that they offer the electorate a clear choice of potential governments, invest winning parties with a policy mandate, and help to promote strong and stable government. In contrast, pro portional systems are defended on the grounds that they usually give government a broader electoral base, promote consensus and cooperation amongst a number of parties, and establish a healthy balance between the executive and the assembly.\n• The meaning of elections is closely linked to the factors that shape voting behaviour. Amongst the various theories of voting are models that highlight the importance of party identification and habitual attachments, those that emphasize the importance of group membership and social alignment, those that are based on rational choice and calculations of self-interest, and those that suggest that individual choices are shaped by ideological manipulation and control."}, {"id": "hps10", "topic": "polsum", "front": "Politics Ch.10 — Parties and Party Systems", "back": "• A political party is a group of people organized for the purpose of winning government power, and usually displays some measure of ideological cohesion. The principal classifications of parties have distinguished between cadre and mass or, later, catch-all parties, parties of representation and parties of integration, constitutional or ‘mainstream’ parties and revolutionary or anti-system ones, and left-wing parties and right-wing parties.\n• Parties have a number of functions in the political system. These include their role as a mechanism of representation, the formation of political elites and recruitment into politics, the formulation of social goals and government policy, the articulation and aggregation of interests, the mobilization and socialization of the electorate, and the organization of governmental processes and institutional relationships.\n• The organization and structure of parties crucially influence the distribution of power within society at large. Party democracy can be promoted either by a wide dispersal of power within the party, or by the concentration of power in the hands of the party’s elected and publicly accountable members. Oligarchic tendencies may be an inevitable consequence of organization, or they may arise from the need for party unity and electoral credibility.\n• A party system is a network of relationships through which parties interact and influence the political process. In one-party systems, a ‘ruling’ party effectively functions as a permanent government. In two-party systems, power alternates between two ‘major’ parties. In dominant-party systems, a single ‘major’ party retains power for a prolonged period. In multiparty systems, no party is large enough to rule alone, leading to a system of coalition government.\n• Party systems shape the broader political process in various ways. They influence the range and nature of choice available to the electorate, and affect the cohesion and stability of governments. They structure the relationship between the executive and the assembly, establish a bias in favour of either conflict or consensus, and shape the general character of the political culture.\n• Evidence of a crisis in party politics can be found in the decline in party membership and partisanship, as well as in the rise of ‘antiparty’ groups and movements. This can be explained by the perception that parties are tainted by power, ambition and corruption, and that they have suffered as a result of general disillusionment caused by the growing inability of governments to deliver on their promises. They are also seen to have failed to articulate the aspirations and sensibilities associated with postmaterialism, or generated within post-industrial societies."}, {"id": "hps11", "topic": "polsum", "front": "Politics Ch.11 — Groups, Interests and Movements", "back": "• An interest or pressure group is an organized association that aims to influence the policies or actions of government. Sectional groups advance or protect the (usually material) interests of their members, while promotional ones are concerned with shared values, ideals or principles. Whereas insider groups enjoy privileged access to policy formulation, outsider groups lack access to government and so are forced to ‘go public’.\n• Group politics has been understood in a number of ways. Pluralism emphasizes the dispersal of power and the ability of groups to guarantee democratic accountability. Corporatism highlights the privileged position that certain groups enjoy in relation to government. The New Right draws attention to the threat that groups pose in terms of over-government and economic inefficiency.\n• Organized groups benefit the political system by strengthening representation, promoting debate and discussion, broadening political participation and acting as a check on government power. They may, nevertheless, pose a threat, in that they en trench political inequality, are socially and politically divisive, exercise nonlegitimate and unaccountable power, and make the policy process more closed and secretive.\n• Interest groups exert influence through a variety of channels, including the bureaucracy, the assembly, the courts, the mass media, the parties and international bodies. The level of influence that groups have in a particular system, however, relates to how accommodating that system is to group activity in general, and to what access points it offers groups in terms of the distribution of policy-making power.\n• Interest groups have at their disposal a wide range of tactics and political strategies. Their resources may include public sympathy for the group and its goals, the size of its membership or activist base, its financial strength and organizational capabilities, its ability to use sanctions against government and its personal or institutional links with political parties or government bodies.\n• A social movement is a collective body in which there is a high level of commitment and political activism not necessarily based on a formal organization. New social movements are distinguished by their capacity to attract the young, better-educated and relatively affluent; their generally postmaterial orientation; and their commitment to new forms of political activism, sometimes called the ‘new politics’."}, {"id": "hps12", "topic": "polsum", "front": "Politics Ch.12 — Governments, Systems and Regimes", "back": "• Government is any mechanism through which ordered rule is maintained, its central feature being its ability to make collective decisions and enforce them. A political system, or regime, however, encompasses not only the mechanisms of government and institutions of the state, but also the structures and processes through which these interact with the larger society.\n• The classification of political systems serves two purposes. First, it aids understanding by making comparison possible, and helping to highlight similarities and differences between otherwise shapeless collections of facts. Second, it helps us to evaluate the effectiveness or success of different political systems.\n• Regimes have been classified on a variety of bases. ‘Classical’ typologies, stemming from Aristotle, concentrated on constitutional arrangements and institutional structures, while the ‘three worlds’ approach highlighted material and ideological differences between the systems found in ‘first world’ capitalist, ‘second world’ communist and ‘third world’ developing states.\n• The collapse of communism and advance of democratization have made it much more difficult to identify the political contours of the modern world, making conventional systems of classification redundant. It is, nevertheless, still possible to distinguish between regimes on the basis of how their political, economic and cultural characteristics interlock in practice, even though all systems of classification are provisional.\n• ‘End of history’ theorists have proclaimed that history has ended, or is destined to end, with the worldwide triumph of western liberal democracy. Indeed, the most common form of regime in the modern world is now some form of democracy. However, there is evidence that regime types have become both more complex and more diverse. Significant differences can be identified among western polyarchies, new democracies, East Asian regimes, Islamic regimes and military regimes.\n• Those who view democratization as an irresistable process usually argue that, once instigated, democratic reform gains an internal momentum, deriving from the ways in which the holding of competitive elections alter public expectations about the political process. Others, however, point out that many transition countries have been left, perhaps permanently in a ‘grey area’ between democracy and authoritarianism."}, {"id": "hps13", "topic": "polsum", "front": "Politics Ch.13 — Political Executives and Leadership", "back": "• The executive branch of government is responsible for the execution or implementation of policy. The political executive comprises a core of senior figures and is roughly equivalent to ‘the government of the day’ or ‘the administration’. The bureaucratic executive consists of public officials or civil servants. However, the political/bureaucratic distinction is often blurred by the complexities of the policy-making process.\n• Political executives act as the ‘commanding heights’ of the state apparatus and carry out a number of leadership roles. These include representing the state on ceremonial occasions, offering policy-making leadership in relation to strategic priorities, mobil izing popular support for the government or administration, overseeing the bureaucratic machine, and taking the initiative in the event of domestic or international crises.\n• Presidential executives concentrate executive power in the hands of a president who combines the roles of head of state and head of government, but confronts an assembly that enjoys constitutional and political independence. Prime ministers in parliamentary systems operate through two key sets of relationships: the first is with their cabinets, ministers and departments; the second is with their parties and the assembly from which their power stems.\n• The power of chief executives has been enhanced by the tendency of the media and electoral politics to focus on personality and image, by the opportunities to display statesmanship provided by international affairs and summitry, and by the need for political and ideological leadership within an increasingly large and complex executive branch. Their power is, nevertheless, checked by the importance of government and party unity, the need to maintain support in the assembly, and the difficulty of controlling the sprawling bureaucratic machine.\n• Political leadership has been understood in various ways. It has been interpreted as a personal gift based on individual qualities such as charisma, as a sociological phenomenon in which leaders express particular sociohistorical forces, as an organ izational necessity rooted in the need for coherence and unity of direction, and as a political skill that can be learned by leaders intent on manipulating their colleagues and the masses.\n• Leaders have adopted very different strategies to achieve their goals. Laissez-faire leadership attempts to foster harmony and teamwork by broadening the responsibilities of subordinates. Transactional leadership allows leaders to act as brokers, and balance rival factions and interests against each other. Transformational leadership places a heavy emphasis on the mobilization of support through the leader’s capacity to inspire and to advance a personal vision."}, {"id": "hps14", "topic": "polsum", "front": "Politics Ch.14 — Assemblies", "back": "• The terms ‘assembly’, ‘legislature’ and ‘parliament’ are usually used inter changeably. The term ‘assembly’ suggests that the body is a surrogate for the people, as it is com posed of lay politicians who claim to represent the people rather than of trained or expert government officials. The term ‘legislature’ is misleading, because assemblies never monopolize law-making power. The term ‘parliament’ draws attention to the importance within assemblies of debate and deliberation.\n• A parliamentary system is one in which government governs in and through the assembly or parliament, the executive being drawn from, and accountable to, the assembly. A presidential system is based on a separation of powers between the assembly and the executive. This establishes a relationship characterized by a com - bination of independence and interdependence between the two branches.\n• Assemblies provide a link between government and the people: that is, a channel of communication that can support government and uphold the regime, and force government to respond to popular demands. The chief functions of an assembly are to enact legislation, act as a representative body, oversee and scrutinize the execu tive, recruit and train politicians, and assist in maintaining the political system’s legitimacy.\n• Assemblies generally comprise either one or two chambers. The attraction of bicameralism is that it strengthens checks and balances and broadens representation, which is particularly useful in federal systems. Its disadvantage is that, in this type of system, there is a tendency towards immobilism and government gridlock. Committee systems are increasingly important in the legislative process; strong assemblies usually have strong committees, weak ones have weak committees.\n• Assemblies rarely make policy. More usually, they influence policy or are executive-dominated. The amount of power an assembly has is determined by a variety of factors. These include the extent of the assembly’s constitutional authority, its degree of political independence from the executive, the nature of the party system, and the assembly’s level of organizational coherence.\n• The decline of assemblies provokes anxiety because it is linked to the health of responsible and representative government. Assemblies have declined because of the emergence of disciplined political parties, the growth in the role of government, the executive’s greater capacity to formulate policy and provide leadership, and the increasing strength of interest groups and the mass media."}, {"id": "hps15", "topic": "polsum", "front": "Politics Ch.15 — Constitutions, Law and Judges", "back": "• A constitution is a set of rules that seek to establish the duties, powers and functions of the institutions of government and define the relationship between the state and the individual. Constitutions can be classified on the basis of the status of their rules, how easily their rules can be changed, the degree to which their rules are observed in practice, and the content of their rules and the institutional structure that they establish.\n• Constitutions do not serve a single or simple purpose. Amongst their functions are that they empower states by defining a sphere of independent authority, establish a set of values, ideals and goals for a society, bring stability, order and predictability to the workings of government, protect individuals from the state, and legitimize regimes in the eyes of other states and their people.\n• There is an imperfect relationship between the content of a constitution and political practice. Constitutions ‘work’ in certain conditions, notably when they correspond to, and are supported by, the political culture, when they are respected by rulers and accord with the interests and values of dominant groups, and when they are adaptable and can remain relevant in changing political circumstances.\n• Questions about the actual and desirable relationship between law and politics are deeply controversial. Liberal theory, sensitive to civil liberties and human rights, tends to emphasize the limited province of law operating simply as a means of guaranteeing orderly existence. The conservative view, however, emphasizes the link between law and social stability, acknowledging that law has an important role to play in enforcing public morality.\n• The separation of law from politics is accomplished through attempts to make the judiciary independent and impartial. Judicial independence, however, is threatened by the close involvement of political bodies in the process of judicial recruitment and promotion. Judicial impartiality is compromised by the fact that nowhere are judges representatives of the larger society. In western polyarchies, for instance, they are overwhelmingly male, white, materially privileged and relatively old.\n• As judges impose meaning on law, they cannot but be involved in the policy process. The extent of their influence varies according to the clarity and detail with which the law is specified and the scope available for judicial interpretation, and according to the existence or otherwise of a codified or written constitution, which invests in judges the power of judicial review."}, {"id": "hps16", "topic": "polsum", "front": "Politics Ch.16 — Public Policy and the Bureaucracy", "back": "• Public policy is made through a series of linked decisions. Decisions can be explained in terms of the goaldirected behaviour of rational actors, incremental judgements made in the light of changing circumstances, the bureaucratic or organizational factors that shape the decision-making process, and the beliefs and values held by decision-makers.\n• There are four stages to the policy process. In the initiation stage, policy proposals are originated and the policy agenda is set. In the formulation stage, broad policy proposals are developed into specific and detailed recommendations. The implementation stage consists of the processes through which policy decisions are put into effect. The evaluation stage takes the form of critical reflection on policy outputs designed to improve the policy process in the future.\n• The core function of the bureaucracy is to implement or execute law and policy through the administration of government business. However, civil servants also play a significant role in offering policy advice to ministers, in articulating and aggre gating interests (especially through links to client groups), and in maintaining political stability and continuity when there is a change of government or administration.\n• Bureaucracies have traditionally been organized on the basis of purpose or function: hence their division into departments, ministries and agencies. The degree of centra l ization or decentralization within them varies considerably. Modern trends, however, are towards the divorce of policy-making from policy implementation, and the incorporation of private-sector management techniques, if not outright privatiz ation.\n• There is concern about bureaucratic power because of the threat it poses to democratic accountability. The principal sources of bureaucratic power include the ability of civil servants to control the flow of information and, thus, determine what their political masters know, the logistical advantages that they enjoy as permanent and full-time public officials, and their status as experts and custodians of the national interest.\n• Control is exerted over bureaucracies in a number of ways. Mechanisms of public accountability to ministers, assemblies, the courts or ombudsmen can be established. The civil service can be politicized so that it shares the ideological enthus iasms of the government of the day. Counter-bureaucracies can be constructed to provide an alternative source of advice and to strengthen the hands of elected politicians."}, {"id": "hps17", "topic": "polsum", "front": "Politics Ch.17 — Multilevel Politics", "back": "• Politics has always had a spatial, or territorial, dimension, but this became more formalized and explicit with the emergence of the idea of territorial sovereignty. However, territorial politics have been reconfigured by a shift in political decision-making to bodies both ‘above’ and ‘below’ national government, giving rise to multilevel governance and the establishment of a complex policy process in which political authority is distributed vertically and horizontally.\n• The most common forms of subnational territorial organization are federal and unitary systems. Federalism is based on the notion of shared sovereignty, in which power is distributed between the central and peripheral levels of government. Unitary systems, however, vest sovereign power in a single, national institution, which allows the centre to determine the territorial organization of the state.\n• Other factors affecting territorial divisions include the party system and political culture; the economic system and level of material development; the geographical size of the state; and the level of cultural, ethnic and religious diversity. There has been a tendency towards centralization in most, if not all, systems. This reflects, in particular, the fact that central government alone has the resources and strategic position to manage economic life and deliver comprehensive social welfare.\n• Regionalism is a process through which geographical regions become significant political and/or economic units, serving as the basis for cooperation and, possibly, identity. Transnational regionalism takes different forms depending on whether the primary areas for cooperation are economic, security related or political. The main theories of regional integration are federalism, functionalism and neofunctionalism.\n• Regional integration has been taken furthest in Europe. The product of this process, the EU, is nevertheless a very difficult political organization to categorize, having both intergovernmental and supranational features. Amongst the challenges confronting the EU are tensions between the goals of ‘widening’ and ‘deepening’, continuing anxieties about the EU’s ‘democratic deficit’ and the crisis in the eurozone which may threaten the long-term viability of monetary union."}, {"id": "hps18", "topic": "polsum", "front": "Politics Ch.18 — Security: Domestic and International", "back": "• The central role of the police is to enforce criminal law and maintain civil order. The police force may nevertheless have a political character if social or other biases operate within it, if it is deployed in the event of civil unrest or political disputes, and if there is a police state in which the police force is turned into a private army that serves only the interests of the ruling elite.\n• The key purpose of the military is to be an instrument of war that can be directed against other political societies. However, the military may also help to maintain domestic order and stability when civilian mech - anisms are unable or unwilling to act, and it may, in particular circumstances, displace civilian government with a form of military rule. Military regimes, nevertheless, tend to be short-lived because they rely on coercive power in the absence of legitimacy.\n• Realists advance a power politics model of world affairs in which security is primarily understood in terms of ‘national security’ and war is kept in check by the balance of power. The liberal belief in interdependence and balance in world affairs inclines them to place their faith in ‘collective security’, while critical theorists have either emphasized the extent to which state interactions are mediated by beliefs, values and assumptions, or exposed masculinist biases in the conventional realist paradigm.\n• A variety of new security challenges have arisen in the post-Cold War era. These include: the shift from traditional, inter-state war to ‘new’ wars, in which the civilian/military divide is typically blurred; the advent of transnational terrorism which threatens to strike anywhere, at any time, and possibly with devastating effect; and increased horizontal nuclear proliferation, especially linked to fears about nuclear weapons getting into the ‘wrong’ hands.\n• The concept of ‘human security’ has shifted thinking about security away from the state and towards the individual. By extending the notion of security beyond ‘freedom from fear’ to include ‘freedom from want’, it has deepened and widened the notion of security, and thereby, potentially, extended the responsibilities of the international community. Critics, however, argue that this risks making the concept of security virtually meaningless, and creates false expectations about the international community’s capacity to banish violence and insecurity."}, {"id": "hps19", "topic": "polsum", "front": "Politics Ch.19 — World Order and Global Governance", "back": "• The end of the Cold War led to proclamations about the advent of a ‘new world order’; however, this new world order was always imprecisely defined, and the idea quickly became unfashionable. Instead, bipolarity came to be seen to have been replaced by unipolarity – the USA, as the sole remaining superpower, having become a ‘global hegemon’.\n• The implications of US hegemony became particularly apparent following September 11, as the USA embarked on the so-called ‘war on terror’. This, nevertheless, drew the USA into deeply problematic military interventions, which highlighted the limitations of the USA’s unrivalled military strength.\n• Twenty-first century world order increasingly has a multipolar character. This is evident in the relative decline of the USA and rise of so-called ‘emerging powers’, notably China; however, it is also a consequence of wider developments, including the advance of globalization and global governance, and the growing importance of non-state actors.\n• Global governance is a broad, dynamic and complex process of interactive decision-making at the global level. Liberal theorists argue that there is an unmistakable (and perhaps irresistible) trend in favour of global governance, reflecting growing interdependence and a greater willingness of states to engage in collective action. However, the USA’s role in promoting global governance for reasons of national interest has also been significant.\n• The trend towards global governance has been particularly prominent in the economic sphere, where it has been associated with three bodies: the International Monetary Fund, the World Bank and the World Trade Organization. These bodies have, nevertheless, each, in their different ways, been drawn into controversy through their association with neoliberal globalization.\n• The United Nations is the only truly global organization ever constructed, and it operates as the heart of the emerging global governance system. Its principal aims have been to maintain international peace and security, and to promote economic and social development. Although the UN has been no stranger to controversy and criticism, it is widely regarded as an indispensable framework for cooperation, should the international community choose to use it."}, {"id": "hps20", "topic": "polsum", "front": "Politics Ch.20 — A Crisis in Politics?", "back": "• Concerns about a crisis in politics stem largely from evidence of growing civic disengagement, reflected, in particular, in declining rates of voter turnout and falling levels of party membership and campaigning. However, such trends may not so much betoken a crisis in political participation, as indicate a shift from one kind of participation to another – as, for instance, protest movements rise in importance and ‘new media’ are more widely used to facilitate political debate and activism.\n• Growing cynicism about, and even anger towards, mainstream political parties and politicians has been expressed in the phenomenon of ‘anti-politics’. ‘Anti-politics’, nevertheless, does not encourage citizens to turn away from politics and retreat into private existence. Instead, it tends to spawn new groups and movements that express resentment or hostility towards established political structures, although these may range from anti-capitalist protests to far-right anti-immigration campaigns.\n• Evidence of growing voter apathy cannot easily be disregarded, as modern democracies are all representative democracies, in which elections play a vital role. However, the task of explaining declining levels of formal political participation is fraught with difficulties, not least because of the number of possible culprits. The most significant of these are politics, politicians and parties, the public, the media and modern society.\n• Political systems can be judged only in terms of their impact on the larger society, for good or ill. However, as this raises normative questions, there is no consensus about the desirable ‘outcomes’ of the political process. The most commonly used indexes of a government’s or system’s performance include its ability to maintain stability and order, deliver material prosperity, promote citizenship and foster democratic rule.\n• Evaluating political systems is difficult because each performance indicator embodies complexities. Stability can be promoted through consent and popular responsiveness, or through a shared culture and greater respect for authority. The quest for material prosperity may be hampered by policies designed to ensure that wealth is more equally distributed. The spread of citizenship rights may undermine civic duty and weaken the sense of community. The extension of democratic rule may simply lead to a majoritarian despotism that places restrictions on individual freedom or personal autonomy."}], "essays": [{"id": "e1", "topic": "ir", "prompt": "Critically outline Mearsheimer's case that institutions do not significantly affect state behaviour. Define institutions, set out the realist baseline, and show what each of the three institutionalist approaches lacks.", "key": ["Frame: institutions = a set of norms regulating interstate relations; non-binding, no centralized authority; states choose whether to comply.", "Four organizing questions: what are institutions? how do they cause peace? are they compelling? are they supported by evidence?", "Realist baseline — 5 assumptions: anarchy; military capability; uncertainty about intentions; survival as primary motive; rational action.", "Three behaviours: states fear each other; seek survival; maximize relative power.", "Realist view of cooperation: fails due to cheating + relative gains; institutions merely reflect existing power distribution (powerful states shape them).", "Liberal institutionalism: about economic cooperation, not war; weights economy over security; barrier = cheating; solution = institutions punish cheats. FLAW: ignores relative gains.", "Collective security: military might central; renounce force, confront 'troublemakers' collectively; requires trust. FLAW: never solves trust/fear (troublemaker problem); assumes a complex web of criteria.", "Critical theory: transform order into a cooperative global community; discourse constitutes reality; realism's dominance foreclosed alternatives; self-help is contingent. FLAW: inadequate and self-contradictory — cannot say why realism dominated, why discard it now, why communitarianism will replace it.", "Conclusion: by showing what the three lack, Mearsheimer argues institutions do not significantly affect state behaviour."]}, {"id": "e2", "topic": "methods", "prompt": "Compare small-N and large-N research designs, drawing on Mahoney & Goertz's (2006) qualitative vs quantitative distinction. What does each gain and lose?", "key": ["Small-N strengths: contextuality/causality better explicated; theory-building/confirmation; well-defined concepts → internal validity; careful case selection.", "Small-N weaknesses: too many variables/few cases; case-selection bias.", "Large-N strengths: random selection → no bias; generalizable → external validity; outliers don't damage the argument.", "Large-N weaknesses: costly/time-consuming; correlation ≠ causation; conceptual stretching (indicators over conceptual integrity).", "Mahoney & Goertz: qualitative = 'causes-of-effects' (necessary/sufficient causes, Boolean algebra; combinations matter); quantitative = 'effects-of-causes' (multivariate equations, average effects of individual IVs).", "Equifinality: qual handles carefully (process-tracing); quant treats it as infinite, hence irrelevant.", "Generalization narrow/context-sensitive (qual) vs wide (quant); case selection careful (agreement/difference) vs randomized; 'important' causes vs equal weights; deviation studied vs outliers ignored; concept-building/internal validity vs indicators/conceptual stretching."]}, {"id": "e3", "topic": "authoritarianism", "prompt": "How do institutions help authoritarian rulers survive? Discuss with reference to selectorate theory (Bueno de Mesquita), Magaloni, and Svolik & Boix.", "key": ["Selectorate (Bueno de Mesquita): small winning coalition (autocracy) → private goods buy loyalty; large coalition (democracy) → public goods secure incumbent survival.", "Magaloni (PRI of Mexico): elections signal the costs of deference via observed results; allocate the stake in the regime to different actors, making breakdown costly; in sum, settle intra-elite tension AND reveal the level of support.", "Svolik & Boix (2013): autocrats face a double threat — from the autocratic pact (intra-elite) and from broader society; credible institutions reduce information asymmetry between factions; BUT if power inequality is too large, credible commitment fails.", "Typology context: Geddes (regime types & survival), Levitsky (competitive authoritarianism), Schedler (electoral authoritarianism) situate these mechanisms."]}, {"id": "e4", "topic": "turkey", "prompt": "Assess the center–periphery framework in Turkish politics. How do Bakıner, Ceren Lord, Keyder, Birtek and Sunar revise or challenge Mardin?", "key": ["Mardin: center–periphery linkages missing and inimical; Anatolia neglected (devşirme, lack of Anatolian cadres); Anatolia turns reactionary, center suspicious of heterogeneity.", "Bakıner: center and periphery were never too separate — mobility/migration (esp. post-republic); neither side institutionally unified; religiosity not externalized but utilized → reciprocal Diyanet–state relation.", "Ceren Lord: that reciprocity existed from the beginning; Ottoman religious affairs were already relatively centralized vs European counterparts.", "Keyder (class lens): free labour/small landowners despite global markets; national bourgeoisie via dispossession of non-Muslims; heterogeneous DP coalition (war-hit urban classes + profiteers; middle farmers; state elite).", "Birtek (political economy): surplus accumulation via price controls/taxes → heavy/rapid industrialization; SEEs buy loyalty; RPP's contradictory aims (proletariat employment + private business).", "Sunar: bureaucracy grew earlier than pluralization → right-wing populist counter + clientelist ties to the periphery.", "Overall: the revisions replace Mardin's sharp, static center/periphery dichotomy with mobility, class and reciprocal religion–state relations."]}, {"id": "e5", "topic": "methods", "prompt": "What does it mean to say 'context matters' in small-N causal analysis? Discuss multicausality, context-conditionality and endogeneity, and the tools used to handle them.", "key": ["Multicausality: different causes can produce the same outcome → context must be accounted for.", "Context-conditionality: a theory may hold only in certain cases → theorize contextually.", "Endogeneity: reverse causality, simultaneity, multi-directional causality, intervening variables.", "Tools — cross-case: method of agreement/difference; necessary & sufficient causes; Boolean algebra; typological causation.", "Tools — within-case: process-tracing (also how qualitative work handles equifinality).", "Temporal tools: path-dependence; critical juncture; duration & conjunctural.", "Why it matters: combinations of variables (not individuals) carry causal weight; internal validity and concept-building are central."]}, {"id": "e6", "topic": "institutions", "prompt": "Explain Soifer's conceptualization of infrastructural power and its three dimensions.", "key": ["Infrastructural power = the reach/capacity of the state apparatus (state-making literature: Tilly, Slater, Soifer).", "Capabilities approach: the resources the state apparatus holds.", "State weight: the weight of the apparatus on societal actors and groups.", "Subnational variation: territorial reach of the apparatus — is it even or uneven across the territory?"]}, {"id": "e7", "topic": "ir", "prompt": "Using IR theory as a set of 'lenses', explain how realism, liberalism, constructivism and at least one critical theory would each read the role of the United Nations.", "key": ["Framing: theories are lenses on the same world; spectrum of traditional / middle-ground / critical.", "Liberal: faith in IOs and global governance (UN/IMF/WHO/World Bank); cooperation through trade and diplomacy beats chaos.", "Realist: anarchy; IOs have little authority and matter only when serving powerful states (League's failure; US–Iraq 2003).", "Constructivist: UN as a site of norm emergence; violating a norm (Iraq 2003) still carries consequences.", "Marxist: the UN serves the business/imperial class; humanitarian acts mask state-led exploitation.", "Feminist: masculine discourse and under-representation of women.", "Postcolonial: Security Council lacks African/Latin American permanent members; ex-colonial powers' veto perpetuates domination."]}]};
